insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c5349$distinct-q10-duplicados-que-no-lo-son$c5349$), $c5352$b$c5352$, $c5353$Volver a ejecutar la consulta: `DISTINCT` falló en eliminar los duplicados.$c5353$, false, $c5354$`DISTINCT` hizo exactamente lo que define: para el motor, tres textos que difieren en una tilde, una mayúscula o un espacio son tres valores distintos. No hay nada que reintentar.$c5354$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c5349$distinct-q10-duplicados-que-no-lo-son$c5349$), $c5355$c$c5355$, $c5356$Entregar la lista tal cual: es lo que hay en la base.$c5356$, false, $c5357$Es lo que hay en la base, pero la pregunta era por ciudades, no por escrituras. Entregar 3 filas donde hay 1 ciudad hace que quien lo lea cuente mal sus mercados.$c5357$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c5349$distinct-q10-duplicados-que-no-lo-son$c5349$), $c5358$d$c5358$, $c5359$Borrar las filas repetidas de la tabla para que la consulta quede limpia.$c5359$, false, $c5360$No son filas repetidas: son contactos distintos con la ciudad mal escrita. Y un análisis no modifica los datos de origen; el arreglo se acuerda con quien es responsable de esa tabla.$c5360$, 3);

