values ((select id from public.sections where slug = $c5709$operadores-comparacion-logicos$c5709$), (select id from public.lessons where slug = $c5710$operadores-precedencia-in-between$c5710$), $c5711$oper-q10-precedencia-de-not$c5711$, $c5712$query_interpretation$c5712$, $c5713$intermediate$c5713$, $c5714$Precedencia de NOT$c5714$, $c5715$¿Qué productos devuelve esta consulta?$c5715$, $c5716$```sql
SELECT id
FROM products
WHERE NOT is_active AND stock > 0;
