values ((select id from public.sections where slug = $c7811$having$c7811$), (select id from public.lessons where slug = $c7812$having-filtrar-grupos$c7812$), $c7813$having-q02-agregado-en-where$c7813$, $c7814$error_diagnosis$c7814$, $c7815$easy$c7815$, $c7816$Agregado en WHERE$c7816$, $c7817$Esta consulta falla. ¿Cuál es la causa y la corrección?$c7817$, $c7818$```sql
SELECT restaurant_id, count(*) AS entregados
