values ((select id from public.sections where slug = $c8573$subconsultas$c8573$), (select id from public.lessons where slug = $c8574$subconsultas-escalares-y-derivadas$c8574$), $c8575$sub-q06-interpretar-derivada$c8575$, $c8576$query_interpretation$c8576$, $c8577$intermediate$c8577$, $c8578$Tabla derivada$c8578$, $c8579$¿Qué devuelve esta consulta?$c8579$, $c8580$```sql
SELECT c.country, round(avg(p.pedidos), 2) AS pedidos_promedio
FROM (
  SELECT customer_id, count(*) AS pedidos
