values ((select id from public.sections where slug = $c8809$cte$c8809$), (select id from public.lessons where slug = $c8810$cte-recursiva-jerarquias$c8810$), $c8811$cte-q08-partes-recursiva$c8811$, $c8812$matching$c8812$, $c8813$intermediate$c8813$, $c8814$Anatomía de una CTE recursiva$c8814$, $c8815$Relaciona cada parte de una CTE recursiva con su función.$c8815$, null, $c8816$Toda CTE recursiva combina estas piezas: de dónde parte, cómo avanza y qué la detiene. Sin la última, un ciclo en los datos deja la consulta corriendo hasta el tiempo límite.$c8816$, null, $c8817$[{"left":"SELECT ... FROM categories WHERE parent_id IS NULL","right":"Caso base: las filas con las que arranca el recorrido"},{"left":"UNION ALL","right":"Separa el caso base del paso recursivo y acumula las filas de cada vuelta"},{"left":"INNER JOIN arbol AS a ON a.id = c.parent_id","right":"Paso recursivo: busca los hijos de las filas ya encontradas"},{"left":"WHERE a.nivel < 10","right":"Cota de profundidad que protege de una recursión sin fin"}]$c8817$::jsonb, array[$c8818$cte$c8818$,$c8819$recursiva$c8819$]::text[], 75, true)
