values ((select id from public.sections where slug = $c8821$cte$c8821$), (select id from public.lessons where slug = $c8822$cte-recursiva-jerarquias$c8822$), $c8823$cte-q09-terminacion$c8823$, $c8824$single$c8824$, $c8825$advanced$c8825$, $c8826$Terminación de la recursión$c8826$, $c8827$¿Cuándo deja de iterar una CTE recursiva?$c8827$, null, $c8828$La recursión termina sola cuando ya no encuentra filas nuevas. Si los datos tienen ciclos, eso no ocurre nunca: por eso se agrega una cota de nivel o se registra el camino visitado.$c8828$, null, null, array[$c8829$cte$c8829$,$c8830$recursiva$c8830$]::text[], 55, true)
