values ((select id from public.theory_questions where slug = $c8855$cte-q10-recursiva-sin-base$c8855$), $c8856$a$c8856$, $c8857$Una condición en el paso recursivo que deje de generar filas, por ejemplo `WHERE dia < DATE '2025-09-30'`.$c8857$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c8855$cte-q10-recursiva-sin-base$c8855$), $c8858$b$c8858$, $c8859$Cambiar `UNION ALL` por `UNION`.$c8859$, false, $c8860$`UNION` elimina duplicados, pero cada vuelta genera un día distinto: las filas nunca se repiten y la recursión sigue igual.$c8860$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c8855$cte-q10-recursiva-sin-base$c8855$), $c8861$c$c8861$, $c8862$Agregar la palabra `RECURSIVE` en el paso recursivo.$c8862$, false, $c8863$`RECURSIVE` se escribe una sola vez, junto a `WITH`, y ya está presente.$c8863$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
