insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9521$acum-q09-dias-faltantes$c9521$), $c9524$b$c9524$, $c9525$Nada: `ROWS` siempre cuenta días cuando la clave de orden es una fecha.$c9525$, false, $c9526$`ROWS` cuenta filas presentes en el resultado, no unidades de tiempo. Los días ausentes simplemente no existen para la ventana.$c9526$, 1);

