values ((select id from public.theory_questions where slug = $c9521$acum-q09-dias-faltantes$c9521$), $c9527$c$c9527$, $c9528$El promedio da NULL porque faltan días.$c9528$, false, $c9529$Los días faltantes no son filas con NULL: no son filas en absoluto. El promedio se calcula con las que hay.$c9529$, 2);

