insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9769$conjuntos-q09-precedencia$c9769$), $c9772$b$c9772$, $c9773$`(A UNION B) INTERSECT C`, porque se evalúa de izquierda a derecha.$c9773$, false, $c9774$La evaluación de izquierda a derecha aplica entre operadores de la misma precedencia (`UNION` y `EXCEPT`). `INTERSECT` se evalúa antes.$c9774$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9769$conjuntos-q09-precedencia$c9769$), $c9775$c$c9775$, $c9776$Depende del tamaño de los conjuntos: el planificador elige el orden más barato.$c9776$, false, $c9777$La precedencia es parte de la sintaxis del lenguaje, no una decisión del planificador: define qué significa la consulta, no cómo se ejecuta.$c9777$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9769$conjuntos-q09-precedencia$c9769$), $c9778$d$c9778$, $c9779$A ninguna: PostgreSQL rechaza la consulta y exige paréntesis explícitos.$c9779$, false, $c9780$La consulta es válida y se ejecuta sin advertencias; por eso conviene poner los paréntesis aunque el motor no los pida.$c9780$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9781$operaciones-de-conjuntos$c9781$), (select id from public.lessons where slug = $c9782$conjuntos-precedencia-y-alternativas$c9782$), $c9783$conjuntos-q10-except-vs-not-in$c9783$, $c9784$single$c9784$, $c9785$advanced$c9785$, $c9786$EXCEPT frente a NOT IN con valores NULL$c9786$, $c9787$Trabajas en una base donde la columna `items.product_id` admite valores `NULL`. Quieres los `id` de `products` que nunca aparecen en esa columna y lo resuelves con `SELECT id FROM products WHERE id NOT IN (SELECT product_id FROM items)`. Si la subconsulta devuelve al menos un `NULL`, ¿qué devuelve la consulta?$c9787$, null, $c9788$Es la trampa clásica de `NOT IN`. `EXCEPT` y `NOT EXISTS` no la tienen: en las operaciones de conjuntos, dos filas con `NULL` en la misma columna se consideran iguales, así que la comparación es determinista. Ante una columna que admite nulos, prefiere `SELECT id FROM products EXCEPT SELECT product_id FROM items` o un `NOT EXISTS`.$c9788$, null, null, array[$c9789$except$c9789$,$c9790$not_in$c9790$,$c9791$null$c9791$]::text[], 70, true)
