insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9839$conjuntos-q12-nombres-primera-rama$c9839$), $c9842$b$c9842$, $c9843$Falso$c9843$, false, $c9844$El alias de la segunda rama (`razon_social`) se ignora por completo. Solo la primera rama determina los nombres del resultado combinado.$c9844$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9845$lag-y-lead$c9845$), (select id from public.lessons where slug = $c9846$lag-y-lead-basico$c9846$), $c9847$laglead-q01-que-devuelve-lag$c9847$, $c9848$single$c9848$, $c9849$easy$c9849$, $c9850$Qué devuelve LAG$c9850$, $c9851$Una consulta devuelve una fila por mes con la columna `ventas` y calcula `lag(ventas) OVER (ORDER BY mes)`. ¿Qué valor muestra esa columna en la **primera** fila del resultado?$c9851$, null, $c9852$`lag(x)` mira una fila hacia atrás dentro de la partición, según el `ORDER BY` de la ventana. En la primera fila no hay nada que mirar, así que devuelve el valor por omisión, que es `NULL` salvo que indiques otro con el tercer argumento.$c9852$, null, null, array[$c9853$lag_lead$c9853$,$c9854$window_function$c9854$]::text[], 40, true)
