insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9913$laglead-q04-division-entera$c9913$), $c9914$a$c9914$, $c9915$Los tres operandos son enteros, así que la división es entera y trunca los decimales; hay que forzar `numeric`, por ejemplo con `100.0`.$c9915$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9913$laglead-q04-division-entera$c9913$), $c9916$b$c9916$, $c9917$Falta `PARTITION BY` en la ventana.$c9917$, false, $c9918$La serie es única (no hay grupos), así que no hace falta particionar. El problema está en los tipos.$c9918$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9913$laglead-q04-division-entera$c9913$), $c9919$c$c9919$, $c9920$`lag` no puede usarse dos veces en la misma expresión.$c9920$, false, $c9921$Puedes repetir la misma llamada a `lag` tantas veces como quieras; Postgres la evalúa una sola vez por fila.$c9921$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9913$laglead-q04-division-entera$c9913$), $c9922$d$c9922$, $c9923$Falta `round`, y sin redondeo Postgres devuelve 0.$c9923$, false, $c9924$`round` solo cambia cómo se presenta un número que ya es decimal; acá el valor ya se truncó antes, en la división.$c9924$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9925$lag-y-lead$c9925$), (select id from public.lessons where slug = $c9926$variaciones-entre-periodos$c9926$), $c9927$laglead-q05-nullif-division-cero$c9927$, $c9928$single$c9928$, $c9929$intermediate$c9929$, $c9930$División por cero$c9930$, $c9931$En una variación porcentual, ¿qué logra escribir el divisor como `nullif(lag(ventas) OVER (ORDER BY mes), 0)`?$c9931$, null, $c9932$`nullif(x, 0)` devuelve `NULL` cuando `x` vale 0. Dividir por `NULL` da `NULL`, y eso es exactamente lo que quieres reportar: «no se puede calcular». Sin esa protección, un solo mes en cero aborta la consulta completa con *division by zero*.$c9932$, null, null, array[$c9933$lag_lead$c9933$,$c9934$null_handling$c9934$]::text[], 45, true)
