insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9935$laglead-q05-nullif-division-cero$c9935$), $c9936$a$c9936$, $c9937$Que un mes anterior en cero produzca `NULL` en esa fila en lugar de hacer fallar toda la consulta.$c9937$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9935$laglead-q05-nullif-division-cero$c9935$), $c9938$b$c9938$, $c9939$Que los meses con valor cero se excluyan del resultado.$c9939$, false, $c9940$`nullif` no filtra filas: la fila sigue ahí, solo que su variación queda en `NULL`. Para excluirla necesitas un `WHERE` en un nivel externo.$c9940$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9935$laglead-q05-nullif-division-cero$c9935$), $c9941$c$c9941$, $c9942$Que el cero se reemplace por 1 para que la división sea posible.$c9942$, false, $c9943$Eso sería `coalesce(nullif(x, 0), 1)`, y además inventaría un porcentaje. `nullif` solo convierte el cero en `NULL`.$c9943$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9935$laglead-q05-nullif-division-cero$c9935$), $c9944$d$c9944$, $c9945$Que la división entera se convierta en decimal.$c9945$, false, $c9946$El tipo no cambia: `nullif` devuelve el mismo tipo de su primer argumento. Para el decimal necesitas `100.0` o un `::numeric`.$c9946$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9947$lag-y-lead$c9947$), (select id from public.lessons where slug = $c9948$variaciones-entre-periodos$c9948$), $c9949$laglead-q06-lag-12-serie-incompleta$c9949$, $c9950$true_false$c9950$, $c9951$advanced$c9951$, $c9952$Comparación interanual$c9952$, $c9953$«`lag(ventas, 12) OVER (ORDER BY mes)` siempre devuelve el valor del mismo mes del año anterior.» ¿Verdadero o falso?$c9953$, null, $c9954$`lag(x, 12)` toma la fila que está doce posiciones atrás dentro de la partición. Coincide con «hace un año» solo si la serie tiene todos los meses. Si un mes no tuvo actividad y por eso no existe la fila, comparas contra el mes equivocado sin ningún aviso. Para comparar por calendario, une la serie consigo misma con `mes = otro.mes + interval '1 year'`.$c9954$, null, null, array[$c9955$lag_lead$c9955$,$c9956$offset$c9956$,$c9957$series$c9957$]::text[], 45, true)
