values ((select id from public.theory_questions where slug = $c9958$laglead-q06-lag-12-serie-incompleta$c9958$), $c9959$a$c9959$, $c9960$Falso: retrocede doce **filas**, y si a la serie le falta un mes se desalinea.$c9960$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9958$laglead-q06-lag-12-serie-incompleta$c9958$), $c9961$b$c9961$, $c9962$Verdadero: el desplazamiento se calcula sobre la fecha del `ORDER BY`.$c9962$, false, $c9963$El segundo argumento de `lag` cuenta filas, no unidades de tiempo. La ventana no sabe que tu clave de orden son meses.$c9963$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9964$lag-y-lead$c9964$), (select id from public.lessons where slug = $c9965$brechas-y-valores-de-referencia$c9965$), $c9966$laglead-q07-interpretar-brechas$c9966$, $c9967$query_interpretation$c9967$, $c9968$intermediate$c9968$, $c9969$Brechas entre eventos$c9969$, $c9970$¿Qué mide la columna `d` de esta consulta?$c9970$, $c9971$SELECT
  user_id,
  played_at,
  extract(epoch FROM played_at
    - lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at)) / 86400 AS d
FROM plays;$c9971$, $c9972$`played_at - lag(played_at)` da un `interval`; `extract(epoch FROM ...)` lo pasa a segundos y dividir entre 86 400 lo convierte en días. `PARTITION BY user_id` garantiza que la comparación sea contra la reproducción anterior de la misma persona. La primera reproducción de cada oyente devuelve `NULL`.$c9972$, null, null, array[$c9973$lag_lead$c9973$,$c9974$date_functions$c9974$]::text[], 70, true)
on conflict (slug) do update set section_id = excluded.section_id, lesson_id = excluded.lesson_id, type = excluded.type, difficulty = excluded.difficulty, topic = excluded.topic, prompt_md = excluded.prompt_md, code_md = excluded.code_md, explanation_md = excluded.explanation_md, answer = excluded.answer, pairs = excluded.pairs, tags = excluded.tags, estimated_seconds = excluded.estimated_seconds, is_published = excluded.is_published;

