insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9975$laglead-q07-interpretar-brechas$c9975$), $c9976$a$c9976$, $c9977$Los días transcurridos entre cada reproducción y la reproducción anterior del mismo oyente.$c9977$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9975$laglead-q07-interpretar-brechas$c9975$), $c9978$b$c9978$, $c9979$Los días transcurridos desde la primera reproducción de ese oyente.$c9979$, false, $c9980$Eso requeriría `first_value(played_at)` o `min(played_at)` sobre la partición; `lag` solo mira una fila hacia atrás.$c9980$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9975$laglead-q07-interpretar-brechas$c9975$), $c9981$c$c9981$, $c9982$Los segundos entre reproducciones consecutivas de cualquier oyente.$c9982$, false, $c9983$`extract(epoch ...)` da segundos, pero la división entre 86 400 los convierte en días; y `PARTITION BY user_id` impide mezclar oyentes.$c9983$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9975$laglead-q07-interpretar-brechas$c9975$), $c9984$d$c9984$, $c9985$La cantidad de reproducciones que el oyente hizo ese día.$c9985$, false, $c9986$No hay ninguna agregación por día; la consulta devuelve una fila por reproducción, no un conteo.$c9986$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9987$lag-y-lead$c9987$), (select id from public.lessons where slug = $c9988$brechas-y-valores-de-referencia$c9988$), $c9989$laglead-q08-last-value-marco$c9989$, $c9990$error_diagnosis$c9990$, $c9991$advanced$c9991$, $c9992$LAST_VALUE y el marco$c9992$, $c9993$Esta consulta debería mostrar, en cada fila, el total del último mes de cada país. En cambio, `ultimo` siempre coincide con `total`. ¿Por qué?$c9993$, $c9994$SELECT
  country,
  mes,
  total,
  last_value(total) OVER (PARTITION BY country ORDER BY mes) AS ultimo
FROM serie_mensual;$c9994$, $c9995$Con `ORDER BY` y sin cláusula de marco, Postgres aplica `RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`. La «última fila» de ese marco es la fila actual. Abrir el marco hasta `UNBOUNDED FOLLOWING` resuelve el problema; una alternativa igual de válida y más legible es `first_value(total) OVER (PARTITION BY country ORDER BY mes DESC)`.$c9995$, null, null, array[$c9996$lag_lead$c9996$,$c9997$first_value$c9997$,$c9998$last_value$c9998$,$c9999$frame$c9999$]::text[], 75, true)
