insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10000$laglead-q08-last-value-marco$c10000$), $c10001$a$c10001$, $c10002$Con `ORDER BY` y sin marco explícito, la ventana termina en la fila actual; hay que abrirla con `ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING`.$c10002$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10000$laglead-q08-last-value-marco$c10000$), $c10003$b$c10003$, $c10004$`last_value` no admite `PARTITION BY` y por eso ignora el país.$c10004$, false, $c10005$Sí lo admite, y de hecho aquí funciona: el problema no es la partición sino hasta dónde llega el marco dentro de ella.$c10005$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10000$laglead-q08-last-value-marco$c10000$), $c10006$c$c10006$, $c10007$Falta ordenar la consulta externa por `country, mes`.$c10007$, false, $c10008$El `ORDER BY` final solo cambia la presentación; los valores calculados por la ventana serían los mismos.$c10008$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10000$laglead-q08-last-value-marco$c10000$), $c10009$d$c10009$, $c10010$`last_value` devuelve siempre la fila actual: es su comportamiento definido.$c10010$, false, $c10011$Devuelve la última fila **del marco**. Como el marco por omisión termina en la fila actual, parece hacer eso; con el marco abierto devuelve la última de la partición.$c10011$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10012$lag-y-lead$c10012$), (select id from public.lessons where slug = $c10013$lag-y-lead-basico$c10013$), $c10014$laglead-q09-filtrar-por-lag$c10014$, $c10015$single$c10015$, $c10016$advanced$c10016$, $c10017$Orden de evaluación$c10017$, $c10018$Quieres quedarte solo con los meses que cayeron respecto del anterior. ¿Cuál es la forma correcta de filtrar?$c10018$, null, $c10019$El orden lógico es `FROM` → `WHERE` → `GROUP BY` → `HAVING` → funciones de ventana → `SELECT` → `ORDER BY`. Para filtrar por el resultado de una ventana necesitas un nivel más: CTE o subconsulta, y el `WHERE` afuera.$c10019$, null, null, array[$c10020$lag_lead$c10020$,$c10021$where$c10021$,$c10022$cte$c10022$]::text[], 55, true)
