delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c10023$laglead-q09-filtrar-por-lag$c10023$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10023$laglead-q09-filtrar-por-lag$c10023$), $c10024$a$c10024$, $c10025$Calcular el `lag` en una CTE o subconsulta y aplicar el `WHERE` en la consulta externa.$c10025$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10023$laglead-q09-filtrar-por-lag$c10023$), $c10026$b$c10026$, $c10027$Escribir `WHERE ventas < lag(ventas) OVER (ORDER BY mes)` en la misma consulta.$c10027$, false, $c10028$No es válido: el `WHERE` se evalúa antes que las funciones de ventana, así que Postgres rechaza la consulta con «window functions are not allowed in WHERE».$c10028$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10023$laglead-q09-filtrar-por-lag$c10023$), $c10029$c$c10029$, $c10030$Usar `HAVING ventas < lag(ventas) OVER (ORDER BY mes)`.$c10030$, false, $c10031$`HAVING` también se evalúa antes que las ventanas, y además está pensado para condiciones sobre agregados de un `GROUP BY`.$c10031$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10023$laglead-q09-filtrar-por-lag$c10023$), $c10032$d$c10032$, $c10033$Agregar `FILTER (WHERE ventas < 0)` a la llamada de `lag`.$c10033$, false, $c10034$`FILTER` solo se aplica a funciones de agregación, no a funciones de ventana puras como `lag`, y tampoco expresa esa condición.$c10034$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10035$lag-y-lead$c10035$), (select id from public.lessons where slug = $c10036$brechas-y-valores-de-referencia$c10036$), $c10037$laglead-q10-emparejar-funciones$c10037$, $c10038$matching$c10038$, $c10039$intermediate$c10039$, $c10040$Funciones de posición$c10040$, $c10041$Relaciona cada función de ventana con lo que devuelve dentro de su partición (asumiendo el marco por omisión salvo que se indique otra cosa).$c10041$, null, $c10042$`lag` y `lead` son relativas a la fila actual; `first_value`, `last_value` y `nth_value` son absolutas dentro del marco. Por eso `last_value` depende tanto de la cláusula de marco: sin abrirla, «la última del marco» es la fila actual.$c10042$, null, $c10043$[{"left":"lag(x)","right":"El valor de x en la fila anterior"},{"left":"lead(x)","right":"El valor de x en la fila siguiente"},{"left":"first_value(x)","right":"El valor de x en la primera fila de la partición"},{"left":"last_value(x) con marco hasta UNBOUNDED FOLLOWING","right":"El valor de x en la última fila de la partición"},{"left":"nth_value(x, 3)","right":"El valor de x en la tercera fila del marco"}]$c10043$::jsonb, array[$c10044$lag_lead$c10044$,$c10045$first_value$c10045$,$c10046$last_value$c10046$]::text[], 80, true)
