insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10083$laglead-q12-periodo-incompleto$c10083$), $c10084$a$c10084$, $c10085$El mes está a la mitad: hay que excluirlo del informe o marcarlo como incompleto, no compararlo como si fuera un mes cerrado.$c10085$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10083$laglead-q12-periodo-incompleto$c10083$), $c10086$b$c10086$, $c10087$Multiplicar el valor de septiembre por 2 para dejarlo comparable.$c10087$, false, $c10088$Proyectar puede tener sentido como estimación **declarada**, pero nunca sustituyendo el dato real en la misma columna: mezcla un hecho con un supuesto.$c10088$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10083$laglead-q12-periodo-incompleto$c10083$), $c10089$c$c10089$, $c10090$Cambiar `lag(x)` por `lag(x, 2)` para comparar contra julio.$c10090$, false, $c10091$Comparar medio septiembre contra julio completo tiene el mismo defecto, y además cambia la métrica sin avisar a quien la lee.$c10091$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10083$laglead-q12-periodo-incompleto$c10083$), $c10092$d$c10092$, $c10093$Es una caída real del negocio y hay que investigar el producto.$c10093$, false, $c10094$Antes de investigar el producto conviene descartar el artefacto de corte de datos, que explica la caída por completo.$c10094$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10095$lag-y-lead$c10095$), (select id from public.lessons where slug = $c10096$lag-y-lead-basico$c10096$), $c10097$laglead-q13-empates-en-el-orden$c10097$, $c10098$scenario$c10098$, $c10099$advanced$c10099$, $c10100$Empates en el ORDER BY de la ventana$c10100$, $c10101$Calculas la diferencia contra el pago anterior con `lag(amount) OVER (PARTITION BY order_id ORDER BY paid_at)`. En esta tabla hay pedidos con dos pagos registrados exactamente en el mismo instante. Ejecutas la consulta dos veces y algunos valores cambian. ¿Por qué?$c10101$, null, $c10102$Un `ORDER BY` con empates deja el orden de las filas empatadas a criterio del motor, y ese criterio puede cambiar con el plan de ejecución o el paralelismo. Toda ventana que vaya a un informe necesita una clave de orden única: agrega una columna de desempate estable (el identificador, por ejemplo). Es el mismo cuidado que exige `row_number()`, y acá el síntoma es peor, porque el número sale distinto sin ningún error.$c10102$, null, null, array[$c10103$lag_lead$c10103$,$c10104$order_by$c10104$,$c10105$determinismo$c10105$]::text[], 80, true)
