delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c10129$laglead-q14-marco-no-afecta-a-lag$c10129$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10129$laglead-q14-marco-no-afecta-a-lag$c10129$), $c10130$a$c10130$, $c10131$Cambia el `avg`, que pasa a promediar solo las tres últimas filas; el `lag` devuelve lo mismo, porque las funciones de desplazamiento no miran el marco.$c10131$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10129$laglead-q14-marco-no-afecta-a-lag$c10129$), $c10132$b$c10132$, $c10133$Cambian las dos: el marco define qué filas ve cualquier función de ventana.$c10133$, false, $c10134$El marco define qué filas ve una función de agregación dentro de la ventana, y también `first_value`, `last_value` y `nth_value`. `lag` y `lead` se definen por posición dentro de la partición y lo ignoran.$c10134$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10129$laglead-q14-marco-no-afecta-a-lag$c10129$), $c10135$c$c10135$, $c10136$No cambia ninguna: el marco solo se aplica cuando se escribe `RANGE`.$c10136$, false, $c10137$`ROWS` y `RANGE` son dos maneras de expresar el marco, no la diferencia entre tenerlo y no tenerlo. Con `ORDER BY` siempre hay un marco: si no lo escribes, es `RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`.$c10137$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10129$laglead-q14-marco-no-afecta-a-lag$c10129$), $c10138$d$c10138$, $c10139$Cambia el `lag`, que pasa a mirar dos filas hacia atrás en lugar de una.$c10139$, false, $c10140$Cuántas filas retrocede `lag` lo decide su segundo argumento (`lag(ventas, 2)`), no el marco. La cláusula de marco no altera el desplazamiento.$c10140$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10141$cohortes-y-retencion$c10141$), (select id from public.lessons where slug = $c10142$definir-una-cohorte$c10142$), $c10143$cr-q01-que-define-una-cohorte$c10143$, $c10144$single$c10144$, $c10145$easy$c10145$, $c10146$Definición de cohorte$c10146$, $c10147$En un análisis de cohortes de altas, ¿qué determina a qué cohorte pertenece una persona?$c10147$, null, $c10148$Una cohorte agrupa a quienes comparten un evento de origen en un mismo período. Ese evento se fija una vez y no cambia: quien se dio de alta en marzo de 2024 pertenece a la cohorte de marzo de 2024 para siempre.$c10148$, null, null, array[$c10149$cohortes$c10149$,$c10150$retencion$c10150$]::text[], 45, true)
