insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10467$fn-q04-division-entera$c10467$), $c10470$b$c10470$, $c10471$95.89, redondeado automáticamente a dos decimales.$c10471$, false, $c10472$PostgreSQL no redondea por su cuenta; y con enteros no llega siquiera a calcular decimales.$c10472$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10467$fn-q04-division-entera$c10467$), $c10473$c$c10473$, $c10474$0, porque la división entera de 13 843 entre 14 437 da 0.$c10474$, false, $c10475$La multiplicación por 100 se evalúa **antes** que la división (misma precedencia, asociatividad de izquierda a derecha): se calcula `1384300 / 14437`, no `100 * (13843 / 14437)`.$c10475$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10467$fn-q04-division-entera$c10467$), $c10476$d$c10476$, $c10477$Un error: no se puede dividir un entero por el resultado de `lag()`.$c10477$, false, $c10478$`lag(pedidos)` devuelve el mismo tipo que su argumento, así que la división entre dos enteros es perfectamente válida.$c10478$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10479$funnels$c10479$), (select id from public.lessons where slug = $c10480$funnel-definicion-y-pasos$c10480$), $c10481$fn-q05-dos-tasas$c10481$, $c10482$matching$c10482$, $c10483$intermediate$c10483$, $c10484$Las dos tasas de conversión$c10484$, $c10485$Relaciona cada expresión, calculada sobre una serie de pasos ordenada por `paso`, con lo que mide.$c10485$, null, $c10486$Las dos tasas de un funnel salen de `lag()` (conversión paso a paso) y `first_value()` (conversión desde el inicio). `sum(...) OVER (ORDER BY ...)` es un acumulado: correcto como función, pero suma conteos de pasos que comparten las mismas unidades y por eso no significa nada aquí.$c10486$, null, $c10487$[{"left":"lag(pedidos) OVER (ORDER BY paso)","right":"El conteo del paso inmediatamente anterior; NULL en el primer paso"},{"left":"first_value(pedidos) OVER (ORDER BY paso)","right":"El conteo del primer paso del funnel, repetido en todas las filas"},{"left":"sum(pedidos) OVER (ORDER BY paso)","right":"La suma de los conteos desde el primer paso hasta el actual, que en un funnel no tiene sentido de negocio"},{"left":"lead(pedidos) OVER (ORDER BY paso)","right":"El conteo del paso siguiente; NULL en el último paso"}]$c10487$::jsonb, array[$c10488$funnel$c10488$,$c10489$window_function$c10489$,$c10490$lag_lead$c10490$]::text[], 80, true)
