insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10502$fn-q06-estricto-vs-cualquier-orden$c10502$), $c10505$b$c10505$, $c10506$El 1225 está mal: un funnel siempre exige orden temporal.$c10506$, false, $c10507$«Alcanzó el paso» es una definición legítima y muy usada, por ejemplo para medir adopción de funcionalidades. Lo incorrecto es publicarla sin decir que no verifica el orden.$c10507$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10502$fn-q06-estricto-vs-cualquier-orden$c10502$), $c10508$c$c10508$, $c10509$El 135 está mal: excluye usuarios que sí hicieron las dos cosas.$c10509$, false, $c10510$Los excluye a propósito, porque hicieron las dos cosas en el orden inverso. Esa exclusión es justamente lo que mide el funnel secuencial.$c10510$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10502$fn-q06-estricto-vs-cualquier-orden$c10502$), $c10511$d$c10511$, $c10512$La diferencia se debe a usuarios con más de una playlist.$c10512$, false, $c10513$Ambas cifras parten del mismo `min(created_at)` por usuario, así que tener varias playlists no cambia nada: la diferencia es puramente de orden temporal.$c10513$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10514$funnels$c10514$), (select id from public.lessons where slug = $c10515$funnel-orden-estricto-o-cualquier-orden$c10515$), $c10516$fn-q07-min-no-max$c10516$, $c10517$fill_blank$c10517$, $c10518$intermediate$c10518$, $c10519$El hito de cada paso$c10519$, $c10520$Para construir la tabla de hitos de un funnel secuencial, la marca de tiempo de cada paso se obtiene con la función de agregación `___(columna_de_fecha)` agrupando por unidad. Escribe el nombre de la función.$c10520$, null, $c10521$Se usa `min()`: el **primer** momento en que la unidad alcanzó ese paso. Con `max()` medirías la última vez que hizo la acción, y un usuario que armó una playlist en enero y otra en agosto podría pasar de cumplir el orden a no cumplirlo sin haber cambiado de comportamiento.$c10521$, $c10522${"accepted":["min","MIN","min()"],"case_sensitive":false}$c10522$::jsonb, null, array[$c10523$funnel$c10523$,$c10524$aggregate$c10524$]::text[], 40, true)
