insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10537$fn-q08-condiciones-encadenadas$c10537$), $c10542$c$c10542$, $c10543$No hace falta comprobar que los hitos no sean NULL: una comparación con NULL nunca es verdadera, así que esas filas ya quedan fuera.$c10543$, true, null, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10537$fn-q08-condiciones-encadenadas$c10537$), $c10544$d$c10544$, $c10545$Debe usar `OR` entre las condiciones de los pasos, para no perder usuarios que se saltaron alguno.$c10545$, false, $c10546$Con `OR` dejarías entrar caminos incompletos, que es exactamente lo que un funnel secuencial excluye. Las condiciones se combinan con `AND`.$c10546$, 3);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10537$fn-q08-condiciones-encadenadas$c10537$), $c10547$e$c10547$, $c10548$Debe incluir siempre una ventana de conversión de 30 días.$c10548$, false, $c10549$La ventana es una decisión de negocio, no un requisito. Puede no haberla; lo obligatorio es declarar si existe o no.$c10549$, 4);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10550$funnels$c10550$), (select id from public.lessons where slug = $c10551$funnel-orden-estricto-o-cualquier-orden$c10551$), $c10552$fn-q09-date-vs-timestamptz$c10552$, $c10553$true_false$c10553$, $c10554$advanced$c10554$, $c10555$Determinismo del huso horario$c10555$, $c10556$`started_on` es `date` y `created_at` es `timestamptz`. La condición `started_on >= created_at::date` produce el mismo resultado para cualquier persona que la ejecute.$c10556$, null, $c10557$Un `::date` o un `date_trunc` sobre `timestamptz` sin huso explícito es no determinista entre sesiones. La forma reproducible es `(created_at AT TIME ZONE 'UTC')::date`, que fija el calendario con el que se corta la fecha y deja el resultado igual para todo el mundo.$c10557$, null, null, array[$c10558$funnel$c10558$,$c10559$date_functions$c10559$]::text[], 45, true)
