insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10560$fn-q09-date-vs-timestamptz$c10560$), $c10563$b$c10563$, $c10564$Verdadero$c10564$, false, $c10565$`created_at::date` convierte usando el parámetro `TimeZone` de la sesión. Un evento del 1 de marzo a las 02:00 UTC cae el 28 de febrero para una sesión en `America/Argentina/Buenos_Aires` y el 1 de marzo para una en UTC.$c10565$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10566$funnels$c10566$), (select id from public.lessons where slug = $c10567$funnel-abandono-y-tiempo-de-conversion$c10567$), $c10568$fn-q10-ultimo-paso-alcanzado$c10568$, $c10569$query_interpretation$c10569$, $c10570$advanced$c10570$, $c10571$Punto de abandono$c10571$, $c10572$¿Qué propiedad tiene el resultado de esta consulta, que el funnel clásico (un conteo por evento) no tiene?$c10572$, $c10573$```sql
WITH avance AS (
  SELECT order_id,
         max(CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2
                        WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4
                        WHEN 'delivered' THEN 5 ELSE 0 END) AS ultimo_paso
  FROM order_events
  GROUP BY order_id
)
SELECT ultimo_paso, count(*) AS pedidos
FROM avance
GROUP BY ultimo_paso;
```$c10573$, $c10574$Clasificar por el último paso alcanzado convierte el funnel en una partición: cada unidad cae en una sola categoría y las cantidades suman el total. Es la tabla que responde «¿dónde priorizo?», mientras que el funnel acumulado responde «¿cuánto llega al final?».$c10574$, null, null, array[$c10575$funnel$c10575$,$c10576$case$c10576$,$c10577$aggregate$c10577$]::text[], 75, true)
