insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10578$fn-q10-ultimo-paso-alcanzado$c10578$), $c10579$a$c10579$, $c10580$Cada pedido aparece en una sola fila, así que las categorías son excluyentes y `pedidos` suma el total de pedidos.$c10580$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10578$fn-q10-ultimo-paso-alcanzado$c10578$), $c10581$b$c10581$, $c10582$Excluye los pedidos cancelados del resultado.$c10582$, false, $c10583$No los excluye: un pedido cancelado aparece con el número del último paso real que alcanzó, porque `cancelled` se mapea a 0 y `max()` se queda con el mayor.$c10583$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10578$fn-q10-ultimo-paso-alcanzado$c10578$), $c10584$c$c10584$, $c10585$Calcula la conversión paso a paso sin necesidad de `lag()`.$c10585$, false, $c10586$No calcula ninguna conversión. Da el reparto de abandonos; para las tasas de conversión hace falta el funnel acumulado.$c10586$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10578$fn-q10-ultimo-paso-alcanzado$c10578$), $c10587$d$c10587$, $c10588$Ordena los pedidos cronológicamente por su último evento.$c10588$, false, $c10589$No hay `ORDER BY` ni ninguna marca de tiempo en la consulta: `max()` opera sobre el número de paso, no sobre `event_at`.$c10589$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10590$funnels$c10590$), (select id from public.lessons where slug = $c10591$funnel-abandono-y-tiempo-de-conversion$c10591$), $c10592$fn-q11-mediana-o-promedio$c10592$, $c10593$scenario$c10593$, $c10594$advanced$c10594$, $c10595$Resumir duraciones$c10595$, $c10596$Operaciones te pide «cuánto tarda un pedido típico en entregarse». La mayoría se entrega entre 30 y 45 minutos, pero un puñado de pedidos quedó trabado varias horas. ¿Qué métrica entregas?$c10596$, null, $c10597$Las duraciones casi siempre tienen cola larga, así que la mediana describe la experiencia típica mejor que el promedio. `percentile_cont` es una agregación de conjunto ordenado: el `ORDER BY` va dentro de `WITHIN GROUP`. El percentil 90 es el complemento habitual, porque es el lenguaje de los acuerdos de nivel de servicio.$c10597$, null, null, array[$c10598$funnel$c10598$,$c10599$aggregate$c10599$,$c10600$numeric_functions$c10600$]::text[], 70, true)
