insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10601$fn-q11-mediana-o-promedio$c10601$), $c10604$b$c10604$, $c10605$El promedio con `avg(minutos)`, porque usa todos los datos.$c10605$, false, $c10606$Usar todos los datos no lo hace representativo: con cola larga, unos pocos pedidos trabados desplazan el promedio por encima de lo que vive el pedido típico.$c10606$, 1);

