delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c10855$dedup-q11-count-tras-left-join$c10855$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10855$dedup-q11-count-tras-left-join$c10855$), $c10856$a$c10856$, $c10857$`count(*)` cuenta filas, y el `LEFT JOIN` produce una fila con las columnas de `orders` en NULL para los clientes sin pedidos. Hay que usar `count(o.id)`, que ignora los NULL.$c10857$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10855$dedup-q11-count-tras-left-join$c10855$), $c10858$b$c10858$, $c10859$El `LEFT JOIN` debería ser `INNER JOIN`: así los clientes sin pedidos no generan filas fantasma.$c10859$, false, $c10860$Con `INNER JOIN` esos clientes desaparecen por completo del resultado en lugar de aparecer con 0. Para una regla de desempate necesitas que sigan compitiendo, aunque sea con cero pedidos.$c10860$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10855$dedup-q11-count-tras-left-join$c10855$), $c10861$c$c10861$, $c10862$Falta `o.id` en el `GROUP BY`, y por eso el conteo queda mal calculado.$c10862$, false, $c10863$Agregar `o.id` al `GROUP BY` produciría una fila por pedido en lugar de una por cliente. El nivel de agregación actual es el correcto; lo que está mal es qué se cuenta.$c10863$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10855$dedup-q11-count-tras-left-join$c10855$), $c10864$d$c10864$, $c10865$Hay que envolver el resultado en `coalesce(count(*), 0)`.$c10865$, false, $c10866$`count` nunca devuelve NULL: devuelve 0 cuando no hay nada que contar. `coalesce` no cambia nada aquí, porque el valor devuelto es 1, no NULL.$c10866$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10867$deduplicacion$c10867$), (select id from public.lessons where slug = $c10868$dedup-elegir-la-fila-ganadora$c10868$), $c10869$dedup-q12-orden-de-la-limpieza$c10869$, $c10870$single$c10870$, $c10871$advanced$c10871$, $c10872$Secuencia segura de una limpieza$c10872$, $c10873$Ya identificaste las cuentas duplicadas y elegiste la ganadora de cada grupo. ¿Cuál es la secuencia correcta para ejecutar la limpieza?$c10873$, null, $c10874$Deduplicar no termina con un `DELETE`. La secuencia sana es: detectar → cuantificar → elegir ganadora con una regla escrita → entregar la lista para revisión → repuntar las dependencias → eliminar → recién entonces prevenir con un índice único funcional. Cada paso deja evidencia, y esa evidencia es lo que te permite responder tres meses después por qué una métrica cambió.$c10874$, null, null, array[$c10875$proceso$c10875$,$c10876$integridad_referencial$c10876$,$c10877$auditoria$c10877$]::text[], 60, true)
