delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c10990$calidad-q05-palabra-clave-antijoin$c10990$);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10991$calidad-de-datos$c10991$), (select id from public.lessons where slug = $c10992$calidad-de-datos-validez-y-huecos$c10992$), $c10993$calidad-q06-not-in-con-nulos$c10993$, $c10994$error_diagnosis$c10994$, $c10995$advanced$c10995$, $c10996$NOT IN con valores nulos$c10996$, $c10997$Sabes que hay pedidos sin ítems, pero esta consulta devuelve **cero filas**. La columna `order_items.order_id` admite nulos en este sistema de origen y contiene algunos. ¿Por qué el resultado es vacío?$c10997$, $c10998$```sql
SELECT o.id
FROM orders o
WHERE o.id NOT IN (SELECT i.order_id FROM order_items i);
```$c10998$, $c10999$`x NOT IN (a, b, NULL)` equivale a `x <> a AND x <> b AND x <> NULL`, y esa última comparación nunca es verdadera: la conjunción entera queda en desconocido. Por eso, en auditorías, el antijoin se escribe con `NOT EXISTS` (inmune a los nulos) o con `LEFT JOIN ... IS NULL`.$c10999$, null, null, array[$c11000$null_handling$c11000$,$c11001$antijoin$c11001$,$c11002$subconsulta$c11002$]::text[], 80, true)
