values ((select id from public.theory_questions where slug = $c11003$calidad-q06-not-in-con-nulos$c11003$), $c11004$a$c11004$, $c11005$`NOT IN` compara contra cada valor de la lista; al haber un NULL, ninguna comparación puede dar falso con certeza, el resultado global queda en desconocido y ninguna fila pasa el filtro.$c11005$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11003$calidad-q06-not-in-con-nulos$c11003$), $c11006$b$c11006$, $c11007$`NOT IN` no acepta subconsultas, solo listas escritas a mano.$c11007$, false, $c11008$`NOT IN` acepta subconsultas sin problema; la consulta es sintácticamente válida y por eso no aparece ningún error.$c11008$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11003$calidad-q06-not-in-con-nulos$c11003$), $c11009$c$c11009$, $c11010$La subconsulta devuelve demasiadas filas y el motor la trunca silenciosamente.$c11010$, false, $c11011$PostgreSQL no trunca resultados de subconsultas. El problema no es el tamaño sino la presencia de un solo NULL.$c11011$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11003$calidad-q06-not-in-con-nulos$c11003$), $c11012$d$c11012$, $c11013$Falta un `DISTINCT` en la subconsulta y los valores repetidos se anulan entre sí.$c11013$, false, $c11014$Los valores repetidos no afectan el resultado de `NOT IN`; agregar `DISTINCT` no cambiaría nada mientras el NULL siga ahí.$c11014$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11015$calidad-de-datos$c11015$), (select id from public.lessons where slug = $c11016$calidad-de-datos-perfilar-una-tabla$c11016$), $c11017$calidad-q07-having-para-duplicados$c11017$, $c11018$single$c11018$, $c11019$advanced$c11019$, $c11020$Detectar claves duplicadas$c11020$, $c11021$Quieres comprobar si la combinación (`user_id`, `track_id`, `played_at`) identifica una sola fila en `plays`. ¿Cuál de estas consultas responde esa pregunta?$c11021$, null, $c11022$Probar una clave de negocio es agrupar por ella y quedarse con los grupos de más de una fila. La clave técnica (`id`) no sirve para esto porque es distinta por definición en cada fila; el duplicado siempre se define respecto de las columnas que el negocio considera identificatorias.$c11022$, null, null, array[$c11023$duplicados$c11023$,$c11024$group_by$c11024$,$c11025$having$c11025$]::text[], 70, true)
