delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c11133$calidad-q12-primer-dia-con-la-tabla$c11133$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11133$calidad-q12-primer-dia-con-la-tabla$c11133$), $c11134$a$c11134$, $c11135$Perfilar la tabla en una consulta: volumen, ventana temporal en UTC, granularidad (qué combinación identifica una fila) y nulos por columna, y recién después escribir la métrica.$c11135$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11133$calidad-q12-primer-dia-con-la-tabla$c11133$), $c11136$b$c11136$, $c11137$Escribir el reporte con las columnas que parecen correctas y entregarlo; si algo no cierra, el área de negocio lo va a notar.$c11137$, false, $c11138$El área de negocio casi nunca detecta un error del 1 %, que es donde viven los problemas de calidad: lo va a usar para decidir. Además, un número entregado sin verificar es difícil de corregir después sin perder credibilidad.$c11138$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11133$calidad-q12-primer-dia-con-la-tabla$c11133$), $c11139$c$c11139$, $c11140$Corregir de entrada los valores sospechosos (negativos, nulos, duplicados) con `UPDATE` y `DELETE` para trabajar sobre datos limpios.$c11140$, false, $c11141$Además de que solo tienes lectura, modificar una tabla de producción sin acuerdo destruye evidencia y rompe las conciliaciones de otras áreas. La limpieza se aplica en la consulta y se propone en el origen.$c11141$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11133$calidad-q12-primer-dia-con-la-tabla$c11133$), $c11142$d$c11142$, $c11143$Pedir que alguien documente la tabla antes de tocarla y esperar esa documentación para empezar.$c11143$, false, $c11144$La documentación rara vez llega a tiempo y, cuando llega, describe la intención y no el dato real. Perfilar te da en quince minutos la verdad de lo que hay, que es lo que después se contrasta con la documentación.$c11144$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11145$depuracion-de-consultas$c11145$), (select id from public.lessons where slug = $c11146$depuracion-descomponer-y-contar$c11146$), $c11147$dc-q01-consulta-que-corre-no-es-correcta$c11147$, $c11148$single$c11148$, $c11149$easy$c11149$, $c11150$Método de depuración$c11150$, $c11151$Una consulta se ejecuta sin errores y devuelve números con el orden de magnitud esperado. ¿Qué garantiza eso?$c11151$, null, $c11152$Los errores caros no son los que el motor reporta, sino los que no reporta: totales inflados, denominadores filtrados y promedios al grano equivocado. La única forma de saber que una consulta es correcta es verificarla contra cifras conocidas, descomponiéndola y contando cada paso.$c11152$, null, null, array[$c11153$depuracion$c11153$,$c11154$metodo$c11154$]::text[], 45, true)
