insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11155$dc-q01-consulta-que-corre-no-es-correcta$c11155$), $c11158$b$c11158$, $c11159$Que el resultado es correcto, porque el motor valida la lógica de la consulta.$c11159$, false, $c11160$El motor no conoce la pregunta del negocio. Verifica sintaxis y tipos; una suma multiplicada por un join 1:N es tan válida para Postgres como la suma correcta.$c11160$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11155$dc-q01-consulta-que-corre-no-es-correcta$c11155$), $c11161$c$c11161$, $c11162$Que no hay joins que multipliquen filas, porque eso produciría un error.$c11162$, false, $c11163$El fan-out no produce ningún error: es una operación perfectamente legal que simplemente devuelve más filas de las que esperabas.$c11163$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11155$dc-q01-consulta-que-corre-no-es-correcta$c11155$), $c11164$d$c11164$, $c11165$Que los datos de origen no tienen NULL en las columnas usadas.$c11165$, false, $c11166$Los NULL tampoco generan errores. Cambian silenciosamente el resultado de comparaciones, promedios y conteos.$c11166$, 3);

