values ((select id from public.theory_questions where slug = $c11202$dc-q03-error-fan-out-suma$c11202$), $c11203$a$c11203$, $c11204$El join con `order_items` repite cada pedido una vez por línea, así que `total_amount` se suma tantas veces como líneas tenga el pedido.$c11204$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11202$dc-q03-error-fan-out-suma$c11202$), $c11205$b$c11205$, $c11206$Falta un `HAVING sum(o.total_amount) > 0` para excluir pedidos sin importe.$c11206$, false, $c11207$Los pedidos con importe cero no cambian una suma. El problema es de repetición de filas, no de filas con valor cero.$c11207$, 1);

