values ((select id from public.theory_questions where slug = $c11202$dc-q03-error-fan-out-suma$c11202$), $c11208$c$c11208$, $c11209$`GROUP BY 1` agrupa por la posición equivocada y mezcla países.$c11209$, false, $c11210$`GROUP BY 1` agrupa por la primera columna del `SELECT`, que es `c.country`. Es equivalente a `GROUP BY c.country`.$c11210$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11202$dc-q03-error-fan-out-suma$c11202$), $c11211$d$c11211$, $c11212$El `INNER JOIN` con `customers` descarta pedidos y por eso el total se desvía.$c11212$, false, $c11213$Ese join descartaría filas, lo que bajaría el total, no lo duplicaría. Además `customer_id` apunta siempre a un cliente existente.$c11213$, 3);

