insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11303$dc-q08-avg-ignora-nulos$c11303$), $c11304$a$c11304$, $c11305$`avg` excluye los 222 nulos del numerador y del divisor; `sum(horas) / count(*)` los excluye del numerador pero los cuenta en el divisor, y el promedio queda más bajo.$c11305$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11303$dc-q08-avg-ignora-nulos$c11303$), $c11306$b$c11306$, $c11307$No hay diferencia: `avg` es exactamente `sum` dividido por `count(*)`.$c11307$, false, $c11308$`avg` equivale a `sum(x) / count(x)`, no a `sum(x) / count(*)`. La diferencia aparece justamente cuando hay nulos.$c11308$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11303$dc-q08-avg-ignora-nulos$c11303$), $c11309$c$c11309$, $c11310$`avg` trata los nulos como cero y por eso da un valor más bajo.$c11310$, false, $c11311$Es al revés: `avg` los ignora. Quien los trata implícitamente como cero es la división por `count(*)`.$c11311$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11303$dc-q08-avg-ignora-nulos$c11303$), $c11312$d$c11312$, $c11313$`sum` devuelve NULL en cuanto hay un NULL entre los valores, así que falla.$c11313$, false, $c11314$`sum` ignora los nulos y devuelve NULL solo cuando **todos** los valores lo son o el conjunto está vacío.$c11314$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11315$depuracion-de-consultas$c11315$), (select id from public.lessons where slug = $c11316$depuracion-joins-que-multiplican$c11316$), $c11317$dc-q09-grano-del-promedio$c11317$, $c11318$scenario$c11318$, $c11319$advanced$c11319$, $c11320$Grano de la agregación$c11320$, $c11321$Te piden el ticket promedio por canal. Tu consulta une `orders` con `order_items` y calcula `avg(o.total_amount)`. El resultado da un 28 % por encima del que informa facturación. ¿Cuál es la lectura correcta de tu número?$c11321$, null, $c11322$Dividir el número inflado por el promedio de líneas tampoco lo arregla, porque la ponderación no es uniforme. Hay que volver al grano de la entidad medida: una CTE con una fila por pedido y después `avg(total_amount)`. Verificación rápida: `promedio * pedidos` debe reconstruir el ingreso conocido del grupo.$c11322$, null, null, array[$c11323$depuracion$c11323$,$c11324$grano$c11324$,$c11325$promedio$c11325$]::text[], 90, true)
