values ((select id from public.theory_questions where slug = $c11326$dc-q09-grano-del-promedio$c11326$), $c11327$a$c11327$, $c11328$Es el ticket promedio ponderado por la cantidad de líneas de cada pedido: los pedidos con más artículos, que suelen ser más caros, pesan más.$c11328$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11326$dc-q09-grano-del-promedio$c11326$), $c11329$b$c11329$, $c11330$Es el ticket promedio correcto, y facturación está excluyendo pedidos que tú incluyes.$c11330$, false, $c11331$La diferencia no viene de la población sino del grano: la misma población promediada al grano de línea pesa más a los pedidos de varias líneas.$c11331$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11326$dc-q09-grano-del-promedio$c11326$), $c11332$c$c11332$, $c11333$Es el valor promedio de una línea de pedido, que es una métrica distinta pero igual de útil.$c11333$, false, $c11334$El valor promedio de una línea saldría de promediar `quantity * unit_price`. Aquí se promedia el total del pedido repetido por cada línea, que no mide ni el pedido ni la línea.$c11334$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11326$dc-q09-grano-del-promedio$c11326$), $c11335$d$c11335$, $c11336$Es el ticket promedio con impuestos, mientras que facturación lo informa sin ellos.$c11336$, false, $c11337$El join con `order_items` no agrega impuestos a nada; solo repite filas. La diferencia es estructural, no de definición fiscal.$c11337$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11338$depuracion-de-consultas$c11338$), (select id from public.lessons where slug = $c11339$depuracion-joins-que-multiplican$c11339$), $c11340$dc-q10-inner-join-que-elimina$c11340$, $c11341$single$c11341$, $c11342$intermediate$c11342$, $c11343$Joins que eliminan filas$c11343$, $c11344$Un informe sobre «todos los pedidos» agrega un `INNER JOIN shipments` para mostrar el transportista. ¿Qué efecto tiene sobre la población del informe?$c11344$, null, $c11345$Cada vez que agregues un join conviene responder dos preguntas con una consulta, no con una intuición: ¿puede multiplicar filas? ¿puede eliminarlas? Si puede eliminar y no quieres perder población, es un `LEFT JOIN`.$c11345$, null, null, array[$c11346$depuracion$c11346$,$c11347$join$c11347$,$c11348$cobertura$c11348$]::text[], 60, true)
