values ((select id from public.theory_questions where slug = $c11349$dc-q10-inner-join-que-elimina$c11349$), $c11350$a$c11350$, $c11351$Descarta en silencio los pedidos sin envío (cancelados y pendientes), así que el informe deja de cubrir a todos los pedidos.$c11351$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11349$dc-q10-inner-join-que-elimina$c11349$), $c11352$b$c11352$, $c11353$Ninguno: un join nunca quita filas, solo agrega columnas.$c11353$, false, $c11354$Un `INNER JOIN` conserva únicamente las filas con coincidencia en ambos lados; las que no la tienen desaparecen.$c11354$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11349$dc-q10-inner-join-que-elimina$c11349$), $c11355$c$c11355$, $c11356$Multiplica los pedidos, porque `shipments` es una tabla de detalle.$c11356$, false, $c11357$Podría multiplicar si un pedido tuviera varios envíos, pero el efecto que se pregunta aquí, y el más probable con «todos los pedidos», es la pérdida de los que no tienen ninguno.$c11357$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11349$dc-q10-inner-join-que-elimina$c11349$), $c11358$d$c11358$, $c11359$Convierte los pedidos sin envío en filas con NULL en las columnas de `shipments`.$c11359$, false, $c11360$Eso haría un `LEFT JOIN`. El `INNER JOIN` no rellena con NULL: elimina la fila.$c11360$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11361$depuracion-de-consultas$c11361$), (select id from public.lessons where slug = $c11362$depuracion-descomponer-y-contar$c11362$), $c11363$dc-q11-mensajes-de-error$c11363$, $c11364$matching$c11364$, $c11365$intermediate$c11365$, $c11366$Lectura de mensajes de error$c11366$, $c11367$Relaciona cada mensaje de Postgres con el diagnóstico que conviene revisar primero.$c11367$, null, $c11368$Un error visible es información gratis. El reflejo útil no es silenciarlo (agregar la columna al `GROUP BY`, envolver todo en `min()`, poner un `LIMIT 1`) sino leer qué supuesto sobre los datos acaba de romperse. El peligro real está en la consulta que no protesta.$c11368$, null, $c11369$[{"left":"column \"o.total_amount\" must appear in the GROUP BY clause or be used in an aggregate function","right":"Seleccionas una columna a un grano distinto del grupo: define cuál es el grano de la consulta"},{"left":"more than one row returned by a subquery used as an expression","right":"La subconsulta escalar devuelve varias filas: hay un problema de grano o falta un filtro"},{"left":"operator does not exist: text = integer","right":"Comparas columnas de tipos distintos: revisa qué guarda realmente cada columna"},{"left":"division by zero","right":"El denominador quedó vacío: protégelo con nullif y averigua por qué no tenía filas"}]$c11369$::jsonb, array[$c11370$depuracion$c11370$,$c11371$errores$c11371$,$c11372$postgres$c11372$]::text[], 100, true)
