insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11386$dc-q12-reconciliacion-paso-que-sube$c11386$), $c11387$a$c11387$, $c11388$El `INNER JOIN` con `payments` multiplica: los pedidos con más de un pago aparecen varias veces. Con `EXISTS` o `SELECT DISTINCT` el paso vuelve a bajar, como corresponde.$c11388$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11386$dc-q12-reconciliacion-paso-que-sube$c11386$), $c11389$b$c11389$, $c11390$El paso 3 encontró pedidos que el paso 2 no había incluido.$c11390$, false, $c11391$Imposible: el paso 3 se apoya en `finalizados`, así que solo puede quedarse con un subconjunto de sus pedidos. Si el conteo sube, lo que creció son las filas, no los pedidos.$c11391$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11386$dc-q12-reconciliacion-paso-que-sube$c11386$), $c11392$c$c11392$, $c11393$El paso 3 debería usar `LEFT JOIN` para no perder los pedidos sin pago.$c11393$, false, $c11394$Un `LEFT JOIN` evitaría perder filas, pero no evitaría duplicarlas: los pedidos con dos pagos seguirían generando dos filas y el conteo seguiría subiendo.$c11394$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11386$dc-q12-reconciliacion-paso-que-sube$c11386$), $c11395$d$c11395$, $c11396$Falta `ORDER BY` y los pasos se muestran desordenados.$c11396$, false, $c11397$El orden de presentación no cambia los conteos. Aquí el valor del paso 3 es realmente mayor que el del paso 2.$c11397$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11398$casos-de-negocio$c11398$), (select id from public.lessons where slug = $c11399$de-un-pedido-vago-a-una-especificacion$c11399$), $c11400$cn-q01-primera-decision$c11400$, $c11401$single$c11401$, $c11402$easy$c11402$, $c11403$Especificar un pedido de negocio$c11403$, $c11404$Un colega te pide «las ventas de México del mes pasado». ¿Cuál de estas decisiones determina la estructura de la consulta (el `GROUP BY`) y por lo tanto conviene resolver primero?$c11404$, null, $c11405$El grano —una fila por qué cosa— define el `GROUP BY` y con él la mayor parte de la consulta. Formato, estilo y rendimiento se ajustan después, sin cambiar la pregunta que se responde.$c11405$, null, null, array[$c11406$casos-de-negocio$c11406$,$c11407$especificacion$c11407$]::text[], 45, true)
