insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11420$casos-de-negocio$c11420$), (select id from public.lessons where slug = $c11421$de-un-pedido-vago-a-una-especificacion$c11421$), $c11422$cn-q02-cifra-sin-comparacion$c11422$, $c11423$true_false$c11423$, $c11424$easy$c11424$, $c11425$Base de comparación$c11425$, $c11426$Ante la pregunta «¿por qué cayeron las ventas?», entregar el total de ventas del mes en cuestión es una respuesta completa.$c11426$, null, $c11427$Toda pregunta sobre un cambio necesita una base de comparación explícita: el mes anterior, el mismo mes del año pasado o el plan. Sin ella, el número es verdadero e inútil.$c11427$, null, null, array[$c11428$casos-de-negocio$c11428$,$c11429$metricas$c11429$]::text[], 40, true)
