insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11430$cn-q02-cifra-sin-comparacion$c11430$), $c11433$b$c11433$, $c11434$Verdadero$c11434$, false, $c11435$Un total suelto no permite saber si hubo caída ni de qué tamaño. La palabra «cayeron» ya implica una comparación que la respuesta tiene que incluir.$c11435$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11436$casos-de-negocio$c11436$), (select id from public.lessons where slug = $c11437$de-un-pedido-vago-a-una-especificacion$c11437$), $c11438$cn-q03-descomponer-ingresos$c11438$, $c11439$scenario$c11439$, $c11440$intermediate$c11440$, $c11441$Descomposición de métricas$c11441$, $c11442$Los ingresos de agosto cayeron 9 % contra julio. Calculaste que los pedidos bajaron 8 % y que el ticket promedio quedó prácticamente igual. ¿Cuál es la conclusión que se desprende de esos números?$c11442$, null, $c11443$Descomponer ingresos en pedidos × ticket permite ver cuál de los dos factores se movió. Aquí el ticket queda quieto y los pedidos caen: el problema es de volumen, y esa es una conversación distinta a la de precios.$c11443$, null, null, array[$c11444$casos-de-negocio$c11444$,$c11445$metricas$c11445$,$c11446$diagnostico$c11446$]::text[], 70, true)
