values ((select id from public.theory_questions where slug = $c11447$cn-q03-descomponer-ingresos$c11447$), $c11450$b$c11450$, $c11451$Hubo una guerra de precios y conviene revisar los descuentos.$c11451$, false, $c11452$Una caída de precios se vería en el ticket promedio, que en este caso no se movió. Los descuentos no explican una baja de pedidos.$c11452$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11447$cn-q03-descomponer-ingresos$c11447$), $c11453$c$c11453$, $c11454$Los datos están mal: si el ticket no cambió, los ingresos no podían caer.$c11454$, false, $c11455$Los ingresos son pedidos por ticket. Con el ticket estable, una caída de 8 % en pedidos produce casi exactamente una caída de 9 % en ingresos: los números son coherentes.$c11455$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11447$cn-q03-descomponer-ingresos$c11447$), $c11456$d$c11456$, $c11457$Se perdieron clientes grandes, porque el ticket promedio se mantuvo.$c11457$, false, $c11458$Si se hubieran ido los clientes de mayor ticket, el promedio de los que quedan habría bajado. Un promedio estable sugiere que se perdieron pedidos de todos los tamaños.$c11458$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11459$casos-de-negocio$c11459$), (select id from public.lessons where slug = $c11460$de-un-pedido-vago-a-una-especificacion$c11460$), $c11461$cn-q04-mes-pasado-huso$c11461$, $c11462$fill_blank$c11462$, $c11463$intermediate$c11463$, $c11464$Cortes de calendario con timestamptz$c11464$, $c11465$`orders.created_at` es `timestamptz`. Para que el mes de calendario no dependa de la zona horaria de quien ejecuta la consulta, hay que fijar el huso: `date_trunc('month', created_at AT TIME ZONE '____')::date`. Escribe el valor que hace el corte reproducible cuando el informe se declara en hora universal.$c11465$, null, $c11466$Sin `AT TIME ZONE`, `date_trunc` usa el huso de la sesión y un pedido del 1 de marzo a las 00:30 UTC cae en febrero para una sesión en Bogotá. Fijar `'UTC'` (o el huso del negocio, declarándolo) hace que el resultado sea igual en cualquier máquina.$c11466$, $c11467${"accepted":["UTC","utc"],"case_sensitive":false}$c11467$::jsonb, null, array[$c11468$casos-de-negocio$c11468$,$c11469$fechas$c11469$,$c11470$timestamptz$c11470$]::text[], 60, true)
