insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11508$cn-q06-inner-join-supuesto$c11508$), $c11511$b$c11511$, $c11512$Que todos los movimientos están en la misma moneda.$c11512$, false, $c11513$Ese también es un problema real de la consulta, pero no lo introduce el join: lo introduce el `sum()` sobre importes de monedas distintas. La pregunta es por el supuesto que agrega esta línea de más.$c11513$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
