insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11520$casos-de-negocio$c11520$), (select id from public.lessons where slug = $c11521$supuestos-que-se-escriben$c11521$), $c11522$cn-q07-tipo-de-cambio-del-dia$c11522$, $c11523$single$c11523$, $c11524$advanced$c11524$, $c11525$Conversión de monedas$c11525$, $c11526$Preparas un informe mensual histórico que convierte importes locales a dólares. ¿Por qué conviene usar la cotización del día de cada operación en lugar de la cotización de hoy?$c11526$, null, $c11527$Convertir con la cotización de hoy reescribe el pasado en cada ejecución: la serie cambia sin que haya cambiado ningún dato. La cotización del día de la operación congela la historia y hace auditable el informe.$c11527$, null, null, array[$c11528$casos-de-negocio$c11528$,$c11529$supuestos$c11529$,$c11530$fx$c11530$]::text[], 70, true)
