values ((select id from public.theory_questions where slug = $c11555$cn-q08-ended-on-null$c11555$), $c11556$a$c11556$, $c11557$Las suscripciones abiertas tienen `ended_on` nulo, y `NULL > fecha` no es verdadero, así que quedan fuera del conteo.$c11557$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11555$cn-q08-ended-on-null$c11555$), $c11558$b$c11558$, $c11559$`count(*)` no cuenta las filas con algún valor nulo.$c11559$, false, $c11560$`count(*)` cuenta filas, tengan o no nulos. La pérdida ocurre antes, en el `WHERE`, que descarta las filas cuya condición no es verdadera.$c11560$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11555$cn-q08-ended-on-null$c11555$), $c11561$c$c11561$, $c11562$Falta `AT TIME ZONE 'UTC'` en las comparaciones de fecha.$c11562$, false, $c11563$`started_on` y `ended_on` son de tipo `date`, no `timestamptz`: no tienen hora ni huso, así que la zona horaria no interviene.$c11563$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
