insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11567$casos-de-negocio$c11567$), (select id from public.lessons where slug = $c11568$supuestos-que-se-escriben$c11568$), $c11569$cn-q09-donde-se-esconden$c11569$, $c11570$matching$c11570$, $c11571$intermediate$c11571$, $c11572$Dónde se esconden los supuestos$c11572$, $c11573$Relaciona cada decisión silenciosa de una consulta con el supuesto de negocio que introduce.$c11573$, null, $c11574$Cada línea de una consulta de negocio codifica una definición. Filtros, joins, tratamiento de nulos, unidades y ventanas de tiempo son los cinco lugares donde más seguido se esconde un supuesto que nadie escribió.$c11574$, null, $c11575$[{"left":"`INNER JOIN` con la tabla de comercios","right":"Solo cuentan los pagos en comercios"},{"left":"`status = 'completed'`","right":"Los pagos pendientes no forman parte de la métrica"},{"left":"`sum(amount)` sobre varias monedas","right":"Los importes de distintas monedas son sumables"},{"left":"`coalesce(rating, 0)` en un promedio","right":"No tener calificación equivale a tener cero"},{"left":"`created_at >= now() - INTERVAL '30 days'`","right":"El resultado cambia cada día que se ejecuta"}]$c11575$::jsonb, array[$c11576$casos-de-negocio$c11576$,$c11577$supuestos$c11577$]::text[], 90, true)
