values ((select id from public.theory_questions where slug = $c11614$cn-q11-umbral-minimo$c11614$), $c11617$b$c11617$, $c11618$Sacar `samba` de la tabla porque el número no parece razonable.$c11618$, false, $c11619$Eliminar una fila puntual porque no gusta el resultado es elegir la conclusión. La regla tiene que ser una sola, definida de antemano y aplicada a todos por igual.$c11619$, 1);

