insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11626$casos-de-negocio$c11626$), (select id from public.lessons where slug = $c11627$revisar-antes-de-enviar$c11627$), $c11628$cn-q12-correlacion-no-es-causa$c11628$, $c11629$scenario$c11629$, $c11630$advanced$c11630$, $c11631$Qué se puede concluir de una comparación$c11631$, $c11632$Mediste que quienes estrenaron la app con el cupón de bienvenida recompran 45,20 % (177 clientes) contra 40,12 % de quienes estrenaron sin promoción (2777 clientes). Marketing quiere titular «el cupón aumenta la fidelidad 5 puntos». ¿Qué corresponde responder?$c11632$, null, $c11633$Cuando los grupos se autoseleccionan, la diferencia observada mezcla el efecto de la intervención con el de quién la eligió. Lo que se entrega es la asociación, el tamaño de la muestra y la propuesta de medirlo bien: asignación aleatoria en la próxima campaña.$c11633$, null, null, array[$c11634$casos-de-negocio$c11634$,$c11635$interpretacion$c11635$,$c11636$revision$c11636$]::text[], 90, true)
