values ((select id from public.theory_questions where slug = $c11725$entrevista-q04-count-estrella-tras-left-join$c11725$), $c11728$b$c11728$, $c11729$`marcadas = 0`$c11729$, false, $c11730$Ese sería el resultado de `count(t.id)`, que ignora los nulos. `count(*)` cuenta filas, y el comercio 77 aporta una fila con las columnas de `transactions` en NULL.$c11730$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11725$entrevista-q04-count-estrella-tras-left-join$c11725$), $c11731$c$c11731$, $c11732$`marcadas = NULL`$c11732$, false, $c11733$`count()` nunca devuelve NULL: como mínimo devuelve 0. El nulo aparecería con `sum()`, no con `count()`.$c11733$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11725$entrevista-q04-count-estrella-tras-left-join$c11725$), $c11734$d$c11734$, $c11735$El comercio 77 no aparece en el resultado.$c11735$, false, $c11736$Las condiciones están en el `ON`, así que el `LEFT JOIN` conserva la fila del comercio; lo que cambia es el valor que informa el conteo.$c11736$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11737$desafios-de-entrevista$c11737$), (select id from public.lessons where slug = $c11738$entrevista-errores-que-cuestan-la-oferta$c11738$), $c11739$entrevista-q05-antiunion-palabra-clave$c11739$, $c11740$fill_blank$c11740$, $c11741$easy$c11741$, $c11742$La antiunión segura ante nulos$c11742$, $c11743$Completa el operador que hace segura la antiunión cuando la subconsulta puede devolver nulos:

`SELECT * FROM couriers AS c WHERE ______ (SELECT 1 FROM orders AS o WHERE o.courier_id = c.id);`

Escribe las dos palabras.$c11743$, null, $c11744$`NOT EXISTS` pregunta si la subconsulta devuelve **alguna** fila, no compara valores, así que un nulo simplemente no coincide y no contamina el resultado. Es la forma preferida para antiuniones en PostgreSQL y además suele planificarse igual o mejor que `NOT IN`.$c11744$, $c11745${"accepted":["NOT EXISTS","not exists"],"case_sensitive":false}$c11745$::jsonb, null, array[$c11746$not_exists$c11746$,$c11747$antiunion$c11747$,$c11748$null$c11748$]::text[], 40, true)
