insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11750$desafios-de-entrevista$c11750$), (select id from public.lessons where slug = $c11751$entrevista-patrones-clasicos$c11751$), $c11752$entrevista-q06-patron-y-tecnica$c11752$, $c11753$matching$c11753$, $c11754$intermediate$c11754$, $c11755$Reconocer el patrón detrás del enunciado$c11755$, $c11756$Relaciona cada pedido típico de entrevista con la técnica que lo resuelve de forma natural.$c11756$, null, $c11757$Casi toda pregunta de entrevista es una variante de estos patrones con otros nombres de tablas. Nombrar el patrón en voz alta antes de escribir la primera línea es parte de la respuesta: le muestra al entrevistador que reconoces la forma del problema y le da la oportunidad de corregir el rumbo temprano.$c11757$, null, $c11758$[{"left":"Las 3 canciones más escuchadas de cada género","right":"row_number() con PARTITION BY y filtro en una capa externa"},{"left":"La racha más larga de días consecutivos con actividad","right":"Brechas e islas: fecha menos su número de fila"},{"left":"La misma canción reproducida tres veces seguidas","right":"lag(columna) y lag(columna, 2) sobre una ventana ordenada por tiempo"},{"left":"Qué vendedores explican el 50 % de la facturación","right":"Total acumulado con sum(...) OVER (ORDER BY ...) y un corte sobre el total"},{"left":"Clientes registrados dos veces con el mismo correo","right":"GROUP BY sobre la clave normalizada con HAVING count(*) > 1"},{"left":"Repartidores que no tomaron ningún pedido en agosto","right":"NOT EXISTS correlacionado con el rango dentro de la subconsulta"}]$c11758$::jsonb, array[$c11759$patrones$c11759$,$c11760$ventanas$c11760$,$c11761$diagnostico$c11761$]::text[], 110, true)
