insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11763$desafios-de-entrevista$c11763$), (select id from public.lessons where slug = $c11764$entrevista-como-razonar-en-voz-alta$c11764$), $c11765$entrevista-q07-pedido-ambiguo$c11765$, $c11766$scenario$c11766$, $c11767$intermediate$c11767$, $c11768$Qué hacer con un enunciado ambiguo$c11768$, $c11769$El entrevistador dice: «dame los clientes activos del último mes». No aclara qué significa activo, qué mes ni qué zona horaria. Quedan 20 minutos. ¿Cuál es la mejor jugada?$c11769$, null, $c11770$La ambigüedad es parte del ejercicio. La respuesta profesional es proponer una definición, decirla, confirmarla en una frase y dejarla escrita como comentario o en la explicación del resultado. Así, si la definición era otra, el cambio se limita a una línea del `WHERE` y no a rehacer el análisis.$c11770$, null, null, array[$c11771$supuestos$c11771$,$c11772$comunicacion$c11772$,$c11773$entrevista$c11773$]::text[], 70, true)
on conflict (slug) do update set section_id = excluded.section_id, lesson_id = excluded.lesson_id, type = excluded.type, difficulty = excluded.difficulty, topic = excluded.topic, prompt_md = excluded.prompt_md, code_md = excluded.code_md, explanation_md = excluded.explanation_md, answer = excluded.answer, pairs = excluded.pairs, tags = excluded.tags, estimated_seconds = excluded.estimated_seconds, is_published = excluded.is_published;

