insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11868$entrevista-q11-corte-del-acumulado$c11868$), $c11869$a$c11869$, $c11870$Deja afuera al restaurante que cruza la mitad, así que el grupo devuelto acumula menos del 50 %. El corte correcto compara el acumulado **previo**: `gmv_acumulado - gmv < 0.5 * gmv_total`.$c11870$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
