insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11980$sql-analitico-avanzado$c11980$), (select id from public.lessons where slug = $c11981$avanzado-consultas-en-capas$c11981$), $c11982$avanzado-q-lateral-afirmaciones$c11982$, $c11983$multiple$c11983$, $c11984$expert$c11984$, $c11985$LATERAL$c11985$, $c11986$¿Cuáles de estas afirmaciones sobre `LATERAL` son correctas? Marca todas las que apliquen.$c11986$, null, $c11987$`LATERAL` es «por cada fila de la izquierda, ejecuta esta consulta». De ahí que el `LIMIT` interno sea por grupo y que la variante `CROSS` se comporte como un join interno (descarta) y la variante `LEFT ... ON true` como uno externo (conserva).$c11987$, null, null, array[$c11988$lateral$c11988$,$c11989$top-n$c11989$,$c11990$join$c11990$]::text[], 120, true)
