values ((select id from public.theory_questions where slug = $c12086$avanzado-q-json-vs-jsonb$c12086$), $c12087$a$c12087$, $c12088$Con `jsonb` el texto sale igual para ambas, porque `jsonb` normaliza y ordena las claves; con `json` sale en el orden en que cada una las escribió.$c12088$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12086$avanzado-q-json-vs-jsonb$c12086$), $c12089$b$c12089$, $c12090$Sale igual en los dos casos: el orden de las claves nunca se conserva.$c12090$, false, $c12091$`json` guarda el texto tal cual, incluidos el orden de las claves, los espacios y las claves repetidas.$c12091$, 1);

