values ((select id from public.theory_questions where slug = $c12123$avanzado-q-elegir-la-forma-del-reporte$c12123$), $c12124$a$c12124$, $c12125$`GROUP BY CUBE (country, channel)` con `grouping()` para etiquetar: entrega los cuatro niveles y no hay que tocar la consulta cuando aparece un canal nuevo.$c12125$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12123$avanzado-q-elegir-la-forma-del-reporte$c12123$), $c12126$b$c12126$, $c12127$Un pivote con `count(*) FILTER (WHERE channel = 'app')` y una columna por canal, más una columna de total.$c12127$, false, $c12128$Un pivote tiene columnas fijas: cada canal nuevo obliga a editar la consulta, y además no entrega el total de cada canal como fila comparable.$c12128$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12123$avanzado-q-elegir-la-forma-del-reporte$c12123$), $c12129$c$c12129$, $c12130$`GROUP BY ROLLUP (country, channel)`, que ya trae todos los totales pedidos.$c12130$, false, $c12131$`ROLLUP` no calcula el subtotal por canal solo: quita columnas de derecha a izquierda, así que entrega el cruce, el total por país y el general, pero no el total por canal.$c12131$, 2);

