insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12147$avanzado-q-participacion-antes-del-limit$c12147$), $c12150$b$c12150$, $c12151$Sobre las reproducciones de los 10 artistas devueltos, así que los porcentajes suman 100.$c12151$, false, $c12152$El `LIMIT` es lo último que se aplica. Para obtener el peso dentro del top 10 habría que recortar en una capa previa y calcular la ventana después.$c12152$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12147$avanzado-q-participacion-antes-del-limit$c12147$), $c12153$c$c12153$, $c12154$Sobre las reproducciones del artista de cada fila, por lo que siempre da 100.$c12154$, false, $c12155$`OVER ()` sin `PARTITION BY` define una sola ventana con todas las filas, no una por artista.$c12155$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12147$avanzado-q-participacion-antes-del-limit$c12147$), $c12156$d$c12156$, $c12157$La consulta falla porque `sum()` no puede convivir con `ORDER BY` y `LIMIT`.$c12157$, false, $c12158$Es una función de ventana, no un agregado del `GROUP BY`: convive sin problema con `ORDER BY` y `LIMIT`.$c12158$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c12159$proyectos-finales$c12159$), (select id from public.lessons where slug = $c12160$proyectos-finales-planificar-antes-de-escribir$c12160$), $c12161$pf-q01-pregunta-lista-para-escribir$c12161$, $c12162$scenario$c12162$, $c12163$intermediate$c12163$, $c12164$Cuándo un pedido está listo para convertirse en SQL$c12164$, $c12165$Marketing te escribe: «necesito saber cómo viene la retención». ¿Cuál es el primer paso antes de abrir el editor?$c12165$, null, $c12166$Una pregunta está lista cuando puedes escribir en una línea qué es una fila del resultado. Esa frase fija la granularidad, el universo y la métrica de una sola vez, y es lo que después te permite revisar el resultado: si sabes que debería haber una fila por mes, sabes cuántas filas esperar.$c12166$, null, null, array[$c12167$planificacion$c12167$,$c12168$granularidad$c12168$,$c12169$definiciones$c12169$]::text[], 60, true)
