insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12271$pf-q06-diagnostico-inner-join-ratings$c12271$), $c12272$a$c12272$, $c12273$El join a `ratings` es interno: descarta los pedidos entregados que nadie calificó, así que `delivered_orders` cuenta pedidos calificados y no pedidos entregados. Debe ser `LEFT JOIN`.$c12273$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12271$pf-q06-diagnostico-inner-join-ratings$c12271$), $c12274$b$c12274$, $c12275$Falta `HAVING count(*) > 0`, porque los restaurantes sin calificaciones producen grupos vacíos que el motor descarta mal.$c12275$, false, $c12276$Un grupo vacío no existe: si no hay filas, no hay grupo. `HAVING count(*) > 0` no cambia nada, y el problema es de qué filas llegan a la agregación, no de cómo se filtran los grupos.$c12276$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12271$pf-q06-diagnostico-inner-join-ratings$c12271$), $c12277$c$c12277$, $c12278$`avg` no puede usarse junto a `count(*)` en el mismo `SELECT` cuando una de las tablas tiene valores nulos.$c12278$, false, $c12279$Sí puede: `avg` ignora los `NULL` y `count(*)` cuenta todas las filas del grupo. Convivir en el mismo `SELECT` es justamente lo que permite reportar ambos números.$c12279$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12271$pf-q06-diagnostico-inner-join-ratings$c12271$), $c12280$d$c12280$, $c12281$El `WHERE o.status = 'delivered'` debería estar en el `ON` del join a `ratings` para no perder filas.$c12281$, false, $c12282$Mover ese filtro al `ON` de `ratings` no recupera ningún pedido: el filtro es sobre `orders` y con un join interno los pedidos sin calificación se pierden igual.$c12282$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c12283$proyectos-finales$c12283$), (select id from public.lessons where slug = $c12284$proyectos-finales-del-curso-al-trabajo$c12284$), $c12285$pf-q07-pedido-de-negocio-y-tecnica$c12285$, $c12286$matching$c12286$, $c12287$intermediate$c12287$, $c12288$Del pedido de negocio a la técnica adecuada$c12288$, $c12289$Relaciona cada pedido tal como llega en el trabajo con la técnica que lo resuelve.$c12289$, null, $c12290$Casi todos los pedidos de una vacante de analista caen en unas pocas familias. Reconocer a cuál pertenece un pedido en los primeros treinta segundos es lo que separa una tarde de trabajo de una semana: la técnica ya la sabes, lo que hay que entrenar es el mapeo.$c12290$, null, $c12291$[{"left":"«¿La gente que se registró en marzo sigue usando el producto?»","right":"Cohortes por mes de alta con ventanas relativas a la fecha de registro"},{"left":"«¿En qué paso del registro se nos cae la gente?»","right":"Funnel con pasos ordenados en el tiempo y denominador fijo"},{"left":"«Dame los 5 vendedores más grandes de cada país»","right":"ROW_NUMBER con PARTITION BY país y un criterio de desempate explícito"},{"left":"«Este total no coincide con el informe de finanzas»","right":"Reconciliación: recalcular la métrica sin joins y comparar dos caminos"},{"left":"«La misma persona aparece dos veces en el listado»","right":"Deduplicación por clave de negocio con una regla de fila ganadora"}]$c12291$::jsonb, array[$c12292$cohortes$c12292$,$c12293$funnels$c12293$,$c12294$ranking$c12294$,$c12295$calidad$c12295$]::text[], 90, true)
