delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c12471$optimizacion-q01-por-que-no-usa-el-indice$c12471$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12471$optimizacion-q01-por-que-no-usa-el-indice$c12471$), $c12472$a$c12472$, $c12473$Porque el índice está ordenado por el valor de `placed_at`, no por el resultado de `date_trunc`, así que el motor tiene que calcular la función en cada fila para saber cuáles pasan.$c12473$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12471$optimizacion-q01-por-que-no-usa-el-indice$c12471$), $c12474$b$c12474$, $c12475$Porque `date_trunc` devuelve un `timestamp` y la columna es `timestamptz`, y PostgreSQL nunca usa un índice cuando los tipos difieren.$c12475$, false, $c12476$La diferencia de tipos no es la causa. Aunque los tipos coincidieran exactamente, el índice seguiría sin servir: lo que lo inutiliza es que el filtro compara una **expresión calculada**, no el valor indexado.$c12476$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12471$optimizacion-q01-por-que-no-usa-el-indice$c12471$), $c12477$c$c12477$, $c12478$Porque `date_trunc` no es una función inmutable y PostgreSQL no puede indexar valores que cambian.$c12478$, false, $c12479$La inmutabilidad importa para poder crear un índice por expresión, pero el problema aquí es anterior: no existe ningún índice sobre esa expresión, solo sobre la columna cruda.$c12479$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12471$optimizacion-q01-por-que-no-usa-el-indice$c12471$), $c12480$d$c12480$, $c12481$Porque el filtro devuelve demasiadas filas y el motor decide que recorrer la tabla es más barato.$c12481$, false, $c12482$Eso puede pasar con un filtro poco selectivo, pero no es este caso: julio es una fracción chica de la tabla. Con la versión de rango, el mismo filtro sí usa el índice.$c12482$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c12483$fundamentos-de-optimizacion$c12483$), (select id from public.lessons where slug = $c12484$optimizacion-el-trabajo-que-hace-el-motor$c12484$), $c12485$optimizacion-q02-limit-sin-order-by$c12485$, $c12486$true_false$c12486$, $c12487$easy$c12487$, $c12488$LIMIT sin ORDER BY$c12488$, $c12489$`SELECT id, total FROM orders LIMIT 10;` devuelve siempre las mismas diez filas mientras la tabla no cambie.$c12489$, null, $c12490$`LIMIT` sin `ORDER BY` significa «diez filas cualesquiera». Si el `LIMIT` responde una pregunta de negocio, necesita un `ORDER BY` con **desempate único**, normalmente agregando la clave primaria al final: `ORDER BY total DESC, id`. Sin ese desempate, dos filas con el mismo `total` pueden alternarse entre ejecuciones y el reporte deja de ser reproducible.$c12490$, null, null, array[$c12491$limit$c12491$,$c12492$reproducibilidad$c12492$,$c12493$order_by$c12493$]::text[], 40, true)
