insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12978$ia-q01-el-mejor-pedido$c12978$), $c12979$a$c12979$, $c12980$«Uso PostgreSQL 18. Tabla `orders` (una fila por pedido): `status` (texto, por ejemplo 'delivered'), `created_at` (timestamptz, en UTC) y `channel` (texto). Quiero la cantidad de pedidos con `status = 'delivered'` de agosto de 2025, en UTC, por canal. Resultado: columnas `canal` y `pedidos`, ordenado por `pedidos` de mayor a menor.»$c12980$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12978$ia-q01-el-mejor-pedido$c12978$), $c12981$b$c12981$, $c12982$«Dame una consulta SQL con los pedidos por canal del mes pasado.»$c12982$, false, $c12983$No dice el motor, ni las tablas, ni qué es un pedido válido. Además, «el mes pasado» depende del día en que se ejecute la consulta: la IA va a usar la fecha actual y no agosto de 2025.$c12983$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12978$ia-q01-el-mejor-pedido$c12978$), $c12984$c$c12984$, $c12985$«Escribe `SELECT channel, count(*) FROM orders GROUP BY channel` pero filtrado por agosto y por entregados.»$c12985$, false, $c12986$Dicta una parte del SQL en lugar de describir el resultado, y deja sin definir lo que más importa: el motor, cómo se llama la columna de estado y en qué zona horaria se corta agosto.$c12986$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c12978$ia-q01-el-mejor-pedido$c12978$), $c12987$d$c12987$, $c12988$«Aquí van 50 filas de la tabla `orders` copiadas de la base: [...]. Con esto, dime cuántos pedidos entregados hubo por canal en agosto.»$c12988$, false, $c12989$Pegar filas no reemplaza al esquema y, en una empresa real, puede exponer datos de clientes. Tampoco dice el motor ni el formato de salida.$c12989$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c12990$sql-con-ia$c12990$), (select id from public.lessons where slug = $c12991$ia-como-pedir-sql$c12991$), $c12992$ia-q02-que-va-en-el-contexto$c12992$, $c12993$multiple$c12993$, $c12994$intermediate$c12994$, $c12995$Qué información forma parte del contexto$c12995$, $c12996$Vas a pedirle a una IA una consulta que une `orders` con `customers`. ¿Qué elementos conviene incluir en el pedido? Marca todas las opciones correctas.$c12996$, null, $c12997$Con las tablas, la columna de unión, el resultado esperado y el motor, la IA tiene lo que necesita para escribir la consulta. Si hace falta mostrar un ejemplo, se inventan valores con la misma forma que los reales.$c12997$, null, null, array[$c12998$prompt$c12998$,$c12999$contexto$c12999$,$c13000$esquema$c13000$]::text[], 75, true)
