insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c13071$sql-con-ia$c13071$), (select id from public.lessons where slug = $c13072$ia-verificar-antes-de-entregar$c13072$), $c13073$ia-q06-la-ia-no-se-audita-sola$c13073$, $c13074$true_false$c13074$, $c13075$intermediate$c13075$, $c13076$Por qué la misma IA no verifica su propia respuesta$c13076$, $c13077$Preguntarle a la misma IA «¿esta consulta está bien?» es una verificación suficiente antes de entregar el resultado.$c13077$, null, $c13078$Es un caso de sesgo de confirmación: la tendencia a buscar argumentos que confirman lo que ya se cree. La verificación real es un dato calculado por otro camino, como una consulta de control más simple o un conteo de filas por paso, que coincide con el resultado.$c13078$, null, null, array[$c13079$verificacion$c13079$,$c13080$sesgo_de_confirmacion$c13080$]::text[], 45, true)
