insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13099$ia-q07-ingreso-tras-unir-items$c13099$), $c13100$a$c13100$, $c13101$La suma de los totales de los pedidos, donde cada total se repite una vez por cada línea que tiene el pedido.$c13101$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13099$ia-q07-ingreso-tras-unir-items$c13099$), $c13102$b$c13102$, $c13103$El ingreso correcto por canal, porque el join solo agrega columnas.$c13103$, false, $c13104$Un join con una tabla que tiene varias filas por pedido también agrega filas: cada pedido aparece una vez por línea, y su total se suma esa misma cantidad de veces.$c13104$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13099$ia-q07-ingreso-tras-unir-items$c13099$), $c13105$c$c13105$, $c13106$La suma del precio de cada línea (`quantity * unit_price`).$c13106$, false, $c13107$La consulta suma `o.total_amount`, que es una columna del pedido, no de la línea. Para sumar líneas habría que usar las columnas de `order_items`.$c13107$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13099$ia-q07-ingreso-tras-unir-items$c13099$), $c13108$d$c13108$, $c13109$El ingreso solo de los pedidos que tienen una única línea.$c13109$, false, $c13110$El `INNER JOIN` conserva a todos los pedidos que tienen al menos una línea, no solo a los de una línea. Los de varias líneas entran, y entran repetidos.$c13110$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c13111$sql-con-ia$c13111$), (select id from public.lessons where slug = $c13112$ia-verificar-antes-de-entregar$c13112$), $c13113$ia-q08-rango-semiabierto$c13113$, $c13114$fill_blank$c13114$, $c13115$intermediate$c13115$, $c13116$El extremo final de un rango semiabierto$c13116$, $c13117$Una IA filtró agosto con `BETWEEN '2025-08-01' AND '2025-08-31'` sobre una columna `timestamptz`. Lo corriges con un rango semiabierto: `created_at >= '2025-08-01' AND created_at ___ '2025-09-01'`. ¿Qué operador completa el espacio? Escribe solo el operador.$c13117$, null, $c13118$El rango semiabierto incluye el inicio y excluye el fin. Con `<` entra todo el 31 de agosto, hasta la última fracción de segundo, y no entra nada del 1 de septiembre. Con `<=` entraría un movimiento registrado exactamente a las 00:00 del 1 de septiembre.$c13118$, $c13119${"accepted":["<"],"case_sensitive":false}$c13119$::jsonb, null, array[$c13120$fechas$c13120$,$c13121$rango_semiabierto$c13121$,$c13122$timestamptz$c13122$]::text[], 45, true)
