values ((select id from public.theory_questions where slug = $c13135$ia-q09-filas-de-clientes-en-una-ia$c13135$), $c13136$a$c13136$, $c13137$Pegar solo el esquema de la tabla (columnas y tipos) y, si hace falta un ejemplo, dos o tres filas con valores inventados que tengan la misma forma. Antes de usar la IA con información del trabajo, revisar la política de la empresa.$c13137$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13135$ia-q09-filas-de-clientes-en-una-ia$c13135$), $c13138$b$c13138$, $c13139$Pegar las 200 filas, pero borrar la conversación al terminar.$c13139$, false, $c13140$Borrar la conversación no deshace el envío: los datos ya salieron de la empresa y llegaron a los servidores de otra. Y la IA no necesita filas reales para escribir SQL.$c13140$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13135$ia-q09-filas-de-clientes-en-una-ia$c13135$), $c13141$c$c13141$, $c13142$Pegar las filas quitando solo la columna del DNI.$c13142$, false, $c13143$El correo también identifica a una persona, igual que el nombre o el teléfono. Quitar una columna no anonimiza la fila.$c13143$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13135$ia-q09-filas-de-clientes-en-una-ia$c13135$), $c13144$d$c13144$, $c13145$Pegar 20 filas en lugar de 200, porque con menos datos el riesgo es menor.$c13145$, false, $c13146$Exponer datos personales de 20 personas sigue siendo exponer datos personales. Con menos filas el problema no desaparece: los datos igual salen de la empresa.$c13146$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c13147$sql-con-ia$c13147$), (select id from public.lessons where slug = $c13148$ia-verificar-antes-de-entregar$c13148$), $c13149$ia-q10-senales-para-revisar$c13149$, $c13150$multiple$c13150$, $c13151$intermediate$c13151$, $c13152$Señales de que un resultado necesita revisión$c13152$, $c13153$Ejecutaste la consulta que te dio una IA. ¿Cuáles de estas situaciones son señales de que el resultado necesita revisión antes de entregarlo? Marca todas las opciones correctas.$c13153$, null, $c13154$Filas que crecen tras un join, totales por encima de una referencia y resultados vacíos son las señales clásicas. La cuarta es más sutil: si pediste empates y siempre recibes exactamente tres filas por grupo, lo más probable es que la consulta use `row_number()`, que nunca empata. Una consulta con alias legibles, en cambio, es más fácil de revisar.$c13154$, null, null, array[$c13155$verificacion$c13155$,$c13156$conteos$c13156$,$c13157$control$c13157$]::text[], 75, true)
