insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c13204$ia-q12-prueba-tecnica-para-casa$c13204$), $c13210$c$c13210$, $c13211$Reescribir las consultas con otros alias para que no parezcan de una IA.$c13211$, false, $c13212$Disfrazar el origen no cambia el hecho y va contra lo que pidieron. Lo que la empresa quiere evaluar es tu criterio, no quién tipeó cada línea.$c13212$, 2);

