insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14692$desafio-restaurantes-de-montevideo-en-agosto$c14692$), $c14693$SELECT r.id, r.name, count(o.id) AS pedidos_agosto
FROM restaurants AS r
LEFT JOIN orders AS o
  ON o.restaurant_id = r.id
 AND o.placed_at >= '2025-08-01'
 AND o.placed_at < '2025-09-01'
WHERE r.city_id = 8
GROUP BY r.id, r.name
ORDER BY pedidos_agosto DESC, r.id;$c14693$, true, 'reference', 0);

