insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14761$participacion-por-rubro-uruguay$c14761$), $c14762$SELECT
  m.category,
  sum(t.amount) AS total,
  round(100 * sum(t.amount) / sum(sum(t.amount)) OVER (), 2) AS pct
FROM transactions AS t
INNER JOIN merchants AS m ON m.id = t.merchant_id
INNER JOIN accounts AS a ON a.id = t.account_id
WHERE a.currency = 'UYU'
  AND t.kind IN ('card_payment', 'qr_payment')
  AND t.status = 'completed'
GROUP BY m.category
ORDER BY total DESC;$c14762$, true, 'reference', 0);

