insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14794$saldo-acumulado-de-la-cuenta-2364$c14794$), $c14795$SELECT
  id,
  created_at,
  direction,
  amount,
  sum(CASE WHEN direction = 'credit' THEN amount ELSE -amount END)
    OVER (ORDER BY created_at, id) AS saldo
FROM transactions
WHERE account_id = 2364
  AND status IN ('completed', 'reversed')
ORDER BY created_at, id;$c14795$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14796$saldo-acumulado-de-la-cuenta-2364$c14796$), $c14797$SELECT id, created_at, direction, amount, sum(CASE WHEN direction = 'credit' THEN amount ELSE -amount END) OVER (ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS saldo FROM transactions WHERE account_id = 2364 AND status IN ('completed', 'reversed') ORDER BY created_at, id;$c14797$, false, $c14798$Marco explícito$c14798$, 1);

