insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14864$desafio-media-movil-del-dolar$c14864$), $c14865$SELECT
  rate_date,
  usd_rate,
  round(avg(usd_rate) OVER (
    ORDER BY rate_date
    ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
  ), 4) AS media_7d
FROM fx_rates
WHERE currency = 'ARS'
  AND rate_date >= '2025-08-01'
  AND rate_date < '2025-09-01'
ORDER BY rate_date;$c14865$, true, 'reference', 0);

