insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15413$riesgo-de-movimientos-marcados$c15413$), $c15414$SELECT
  id,
  account_id,
  kind,
  amount,
  currency,
  created_at,
  CASE status
    WHEN 'reversed' THEN 'Fraude confirmado'
    WHEN 'failed' THEN 'Bloqueado'
    WHEN 'pending' THEN 'En revisión'
