WHERE is_flagged
ORDER BY created_at DESC, id ASC;$c15414$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15415$riesgo-de-movimientos-marcados$c15415$), $c15416$SELECT
