insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15523$dias-de-entrega-por-envio$c15523$), $c15524$SELECT order_id,
       shipped_at,
       delivered_at,
       delivered_at::date - shipped_at::date AS delivery_days
FROM shipments
WHERE shipped_at >= DATE '2025-09-01'
  AND shipped_at < DATE '2025-09-08'
