insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15525$dias-de-entrega-por-envio$c15525$), $c15526$SELECT order_id, shipped_at, delivered_at, CAST(delivered_at AS date) - CAST(shipped_at AS date) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c15526$, false, $c15527$Con CAST explícito$c15527$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15528$dias-de-entrega-por-envio$c15528$), $c15529$SELECT order_id, shipped_at, delivered_at, EXTRACT(DAY FROM AGE(delivered_at::date, shipped_at::date)) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c15529$, false, $c15530$Con AGE y EXTRACT$c15530$, 2);

