insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15564$entregas-fuera-de-la-promesa$c15564$), $c15565$SELECT id,
       placed_at,
       delivered_at,
       ROUND(EXTRACT(EPOCH FROM (delivered_at - placed_at)) / 60) - promised_minutes AS delay_minutes
FROM orders
WHERE placed_at >= DATE '2025-09-13'
  AND placed_at < DATE '2025-09-14'
  AND delivered_at > placed_at + promised_minutes * INTERVAL '1 minute'
ORDER BY delay_minutes DESC, id;$c15565$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15566$entregas-fuera-de-la-promesa$c15566$), $c15567$SELECT id, placed_at, delivered_at, ROUND(EXTRACT(EPOCH FROM (delivered_at - (placed_at + promised_minutes * INTERVAL '1 minute'))) / 60) AS delay_minutes FROM orders WHERE placed_at >= DATE '2025-09-13' AND placed_at < DATE '2025-09-14' AND delivered_at IS NOT NULL AND delivered_at > placed_at + promised_minutes * INTERVAL '1 minute' ORDER BY delay_minutes DESC, id;$c15567$, false, $c15568$Midiendo el retraso contra la hora prometida$c15568$, 1);

