insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15789$comision-de-retiro-con-minimo-y-tope$c15789$), $c15790$SELECT id,
       amount,
       LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00) AS fee,
       ROUND(amount - LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c15790$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15791$comision-de-retiro-con-minimo-y-tope$c15791$), $c15792$SELECT id,
       amount,
       GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))) AS fee,
       ROUND(amount - GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c15792$, false, $c15793$Tope primero y tasa como 1.5/100$c15793$, 1);

