FROM transactions AS orig
INNER JOIN transactions AS rev ON rev.reversal_of = orig.id
WHERE orig.kind = 'card_payment'
ORDER BY horas_hasta_reverso DESC, reversal_id;$c16087$, false, $c16088$Partiendo del pago original$c16088$, 1);

