insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16121$posibles-publicaciones-duplicadas$c16121$), $c16122$SELECT
  a.seller_id,
  a.id AS producto_a,
  b.id AS producto_b,
  a.list_price AS precio_a,
  b.list_price AS precio_b
FROM products AS a
INNER JOIN products AS b
  ON b.seller_id = a.seller_id
 AND b.category_id = a.category_id
 AND b.id > a.id
WHERE abs(a.list_price - b.list_price) <= 0.05 * least(a.list_price, b.list_price)
ORDER BY a.seller_id, producto_a, producto_b;$c16122$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16123$posibles-publicaciones-duplicadas$c16123$), $c16124$SELECT
  a.seller_id,
  a.id AS producto_a,
  b.id AS producto_b,
  a.list_price AS precio_a,
  b.list_price AS precio_b
FROM products AS a
INNER JOIN products AS b
  ON b.seller_id = a.seller_id
 AND b.category_id = a.category_id
 AND b.id > a.id
 AND abs(a.list_price - b.list_price) <= 0.05 * least(a.list_price, b.list_price)
ORDER BY 1, 2, 3;$c16124$, false, $c16125$Toda la condición dentro del ON$c16125$, 1);

