insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16239$productos-mas-vendidos-con-tienda-y-categoria$c16239$), $c16240$SELECT
  p.name AS product_name,
  s.store_name,
  cat.name AS category_name,
  sum(oi.quantity) AS unidades
FROM orders AS o
INNER JOIN order_items AS oi ON oi.order_id = o.id
INNER JOIN products AS p ON p.id = oi.product_id
INNER JOIN sellers AS s ON s.id = p.seller_id
INNER JOIN categories AS cat ON cat.id = p.category_id
WHERE o.created_at >= '2025-01-01'
  AND o.status <> 'cancelled'
GROUP BY p.name, s.store_name, cat.name
HAVING sum(oi.quantity) >= 24
ORDER BY unidades DESC, product_name;$c16240$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16241$productos-mas-vendidos-con-tienda-y-categoria$c16241$), $c16242$SELECT
  p.name AS product_name,
  s.store_name,
  cat.name AS category_name,
  sum(oi.quantity) AS unidades
FROM order_items AS oi
INNER JOIN orders AS o ON o.id = oi.order_id
INNER JOIN products AS p ON p.id = oi.product_id
INNER JOIN categories AS cat ON cat.id = p.category_id
INNER JOIN sellers AS s ON s.id = p.seller_id
WHERE o.status <> 'cancelled'
  AND o.created_at >= '2025-01-01'
GROUP BY p.id, p.name, s.store_name, cat.name
HAVING sum(oi.quantity) >= 24
ORDER BY unidades DESC, p.name;$c16242$, false, $c16243$Conducida por order_items y agrupada por la clave del producto$c16243$, 1);

