insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16359$bebidas-por-ciudad-y-cocina$c16359$), $c16360$SELECT
  ci.name AS city_name,
  r.cuisine,
  sum(oi.quantity) AS unidades,
  round(sum(oi.quantity * oi.unit_price), 2) AS ingreso
FROM cities AS ci
INNER JOIN restaurants AS r ON r.city_id = ci.id
