insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16436$clientes-uruguayos-que-compraron-tecnologia$c16436$), $c16437$SELECT c.id, c.full_name, c.city
FROM customers AS c
WHERE c.country = 'UY'
  AND EXISTS (
    SELECT 1
    FROM orders AS o
    INNER JOIN order_items AS oi ON oi.order_id = o.id
