delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16509$pedidos-promedio-por-cliente-y-pais$c16509$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16510$pedidos-promedio-por-cliente-y-pais$c16510$), $c16511$SELECT
  c.country,
  count(*) AS clientes_con_pedidos,
  round(avg(p.pedidos), 2) AS pedidos_promedio
FROM (
  SELECT customer_id, count(*) AS pedidos
  FROM orders
  WHERE status = 'delivered'
  GROUP BY customer_id
) AS p
