insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16585$gasto-promedio-por-pais$c16585$), $c16586$WITH gasto_por_cliente AS (
  SELECT c.id AS customer_id, c.country, sum(o.total_amount) AS gasto
  FROM orders AS o
  INNER JOIN customers AS c ON c.id = o.customer_id
