insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16624$entregas-tardias-por-ciudad$c16624$), $c16625$WITH entregas AS (
  SELECT
    ci.name AS city,
    o.promised_minutes,
    EXTRACT(EPOCH FROM (o.delivered_at - o.placed_at)) / 60 AS minutos_reales
  FROM orders AS o
  INNER JOIN restaurants AS r ON r.id = o.restaurant_id
  INNER JOIN cities AS ci ON ci.id = r.city_id
  WHERE o.status = 'delivered'
),
por_ciudad AS (
  SELECT
    city,
    count(*) AS entregas,
    count(*) FILTER (WHERE minutos_reales > promised_minutes) AS tardias
  FROM entregas
  GROUP BY city
)
SELECT
  city,
  entregas,
  tardias,
  round(100.0 * tardias / entregas, 2) AS pct_tardias
FROM por_ciudad
ORDER BY pct_tardias DESC, city;$c16625$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16626$entregas-tardias-por-ciudad$c16626$), $c16627$WITH entregas AS (SELECT ci.name AS city, o.promised_minutes, EXTRACT(EPOCH FROM (o.delivered_at - o.placed_at)) / 60 AS minutos_reales FROM orders AS o INNER JOIN restaurants AS r ON r.id = o.restaurant_id INNER JOIN cities AS ci ON ci.id = r.city_id WHERE o.status = 'delivered'), por_ciudad AS (SELECT city, count(*) AS entregas, sum(CASE WHEN minutos_reales > promised_minutes THEN 1 ELSE 0 END) AS tardias FROM entregas GROUP BY city) SELECT city, entregas, tardias, round(100.0 * tardias / entregas, 2) AS pct_tardias FROM por_ciudad ORDER BY pct_tardias DESC, city;$c16627$, false, $c16628$SUM(CASE ...) en lugar de FILTER$c16628$, 1);

