WITH ventas_por_categoria AS (
  SELECT cat.name AS category, round(sum(oi.quantity * oi.___), 2) AS ingresos
  FROM order_items AS oi
  INNER JOIN orders AS o ON o.id = oi.order_id
  INNER JOIN products AS p ON p.id = oi.product_id
  INNER JOIN categories AS cat ON cat.id = p.___
  WHERE o.status = 'delivered' AND o.currency = '___'
  GROUP BY cat.name
)
SELECT category, ingresos,
       round(ingresos - (SELECT ___(ingresos) FROM ventas_por_categoria), 2) AS diferencia_vs_promedio
FROM ventas_por_categoria
WHERE ingresos > (SELECT ___(ingresos) FROM ventas_por_categoria)
ORDER BY ingresos DESC;
