insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16702$arbol-de-categorias$c16702$), $c16703$WITH RECURSIVE arbol(id, name, parent_id, nivel, ruta) AS (
  SELECT id, name, parent_id, 1, name
  FROM categories
  WHERE parent_id IS NULL

  UNION ALL

  SELECT c.id, c.name, c.parent_id, a.nivel + 1, a.ruta || ' > ' || c.name
  FROM categories AS c
  INNER JOIN arbol AS a ON a.id = c.parent_id
)
SELECT id, name, nivel, ruta
FROM arbol
ORDER BY ruta;$c16703$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16704$arbol-de-categorias$c16704$), $c16705$WITH RECURSIVE arbol(id, name, parent_id, nivel, ruta) AS (SELECT id, name, parent_id, 1, name FROM categories WHERE parent_id IS NULL UNION ALL SELECT c.id, c.name, c.parent_id, a.nivel + 1, a.ruta || ' > ' || c.name FROM categories AS c INNER JOIN arbol AS a ON a.id = c.parent_id WHERE a.nivel < 5) SELECT id, name, nivel, ruta FROM arbol ORDER BY ruta;$c16705$, false, $c16706$Con cota de profundidad explícita$c16706$, 1);

