delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16905$aprobacion-de-pagos-por-metodo-en-mexico$c16905$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16906$aprobacion-de-pagos-por-metodo-en-mexico$c16906$), $c16907$SELECT
  p.method,
  count(*) AS payment_attempts,
  sum(p.amount) FILTER (WHERE p.status = 'approved') AS approved_amount,
  sum(p.amount) FILTER (WHERE p.status = 'refunded') AS refunded_amount,
  round(100.0 * count(*) FILTER (WHERE p.status = 'approved') / nullif(count(*), 0), 2) AS approval_rate_pct
FROM payments p
JOIN orders o ON o.id = p.order_id
WHERE o.currency = 'MXN'
GROUP BY p.method
ORDER BY approved_amount DESC;$c16907$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16908$aprobacion-de-pagos-por-metodo-en-mexico$c16908$), $c16909$SELECT
  p.method,
  count(*) AS payment_attempts,
  sum(CASE WHEN p.status = 'approved' THEN p.amount END) AS approved_amount,
  sum(CASE WHEN p.status = 'refunded' THEN p.amount END) AS refunded_amount,
  round(100.0 * sum(CASE WHEN p.status = 'approved' THEN 1 ELSE 0 END) / nullif(count(*), 0), 2) AS approval_rate_pct
FROM payments p
JOIN orders o ON o.id = p.order_id
WHERE o.currency = 'MXN'
GROUP BY p.method
ORDER BY approved_amount DESC;$c16909$, false, $c16910$SUM con CASE en todas las columnas condicionales$c16910$, 1);

