delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16948$promotores-y-detractores-por-vendedor$c16948$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16949$promotores-y-detractores-por-vendedor$c16949$), $c16950$SELECT
  s.store_name,
  count(*) AS total_reviews,
  count(*) FILTER (WHERE r.rating >= 4) AS promoter_reviews,
  count(*) FILTER (WHERE r.rating <= 2) AS detractor_reviews,
  round(
    100.0 * (count(*) FILTER (WHERE r.rating >= 4) - count(*) FILTER (WHERE r.rating <= 2))
      / nullif(count(*), 0),
    1
  ) AS nps
FROM reviews r
JOIN products p ON p.id = r.product_id
JOIN sellers s ON s.id = p.seller_id
GROUP BY s.id, s.store_name
HAVING count(*) >= 20
ORDER BY nps DESC, s.store_name;$c16950$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16951$promotores-y-detractores-por-vendedor$c16951$), $c16952$SELECT
  s.store_name,
  count(*) AS total_reviews,
  sum(CASE WHEN r.rating >= 4 THEN 1 ELSE 0 END) AS promoter_reviews,
  sum(CASE WHEN r.rating <= 2 THEN 1 ELSE 0 END) AS detractor_reviews,
  round(
    100.0 * sum(CASE WHEN r.rating >= 4 THEN 1 WHEN r.rating <= 2 THEN -1 ELSE 0 END)
      / nullif(count(*), 0),
    1
  ) AS nps
FROM reviews r
JOIN products p ON p.id = r.product_id
JOIN sellers s ON s.id = p.seller_id
GROUP BY s.id, s.store_name
HAVING count(*) >= 20
ORDER BY nps DESC, s.store_name;$c16952$, false, $c16953$SUM con CASE y una sola expresión para el saldo$c16953$, 1);

