delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16991$adopcion-de-la-app-por-pais$c16991$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16992$adopcion-de-la-app-por-pais$c16992$), $c16993$SELECT
  c.country,
  count(DISTINCT o.customer_id) AS buying_customers,
  count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'app') AS app_customers,
  count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'web') AS web_customers,
  round(
    100.0 * count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'app')
      / nullif(count(DISTINCT o.customer_id), 0),
    1
  ) AS app_adoption_pct
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE o.status <> 'cancelled'
GROUP BY c.country
ORDER BY app_adoption_pct DESC, c.country;$c16993$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16994$adopcion-de-la-app-por-pais$c16994$), $c16995$SELECT
  c.country,
  count(DISTINCT o.customer_id) AS buying_customers,
  count(DISTINCT CASE WHEN o.channel = 'app' THEN o.customer_id END) AS app_customers,
  count(DISTINCT CASE WHEN o.channel = 'web' THEN o.customer_id END) AS web_customers,
  round(
    100.0 * count(DISTINCT CASE WHEN o.channel = 'app' THEN o.customer_id END)
      / nullif(count(DISTINCT o.customer_id), 0),
    1
  ) AS app_adoption_pct
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE o.status <> 'cancelled'
GROUP BY c.country
ORDER BY app_adoption_pct DESC, c.country;$c16995$, false, $c16996$CASE dentro de COUNT(DISTINCT ...) (portable)$c16996$, 1);

