insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17067$empates-rank-contra-dense-rank$c17067$), $c17068$SELECT
  name,
  monthly_listeners,
  rank() OVER (ORDER BY monthly_listeners DESC) AS puesto,
  dense_rank() OVER (ORDER BY monthly_listeners DESC) AS puesto_denso
FROM artists
