insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17144$top-3-canciones-por-genero$c17144$), $c17145$WITH reproducciones_por_cancion AS (
  SELECT ar.genre, t.id AS track_id, t.title, count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  INNER JOIN artists AS ar ON ar.id = al.artist_id
  GROUP BY ar.genre, t.id, t.title
),
ranking AS (
  SELECT
    genre,
    title,
    reproducciones,
    row_number() OVER (PARTITION BY genre ORDER BY reproducciones DESC, track_id) AS puesto
  FROM reproducciones_por_cancion
)
SELECT genre, puesto, title, reproducciones
FROM ranking
WHERE puesto <= 3
ORDER BY genre, puesto;$c17145$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17146$top-3-canciones-por-genero$c17146$), $c17147$SELECT genre, puesto, title, reproducciones FROM (SELECT genre, title, reproducciones, row_number() OVER (PARTITION BY genre ORDER BY reproducciones DESC, track_id) AS puesto FROM (SELECT ar.genre, t.id AS track_id, t.title, count(*) AS reproducciones FROM plays AS p INNER JOIN tracks AS t ON t.id = p.track_id INNER JOIN albums AS al ON al.id = t.album_id INNER JOIN artists AS ar ON ar.id = al.artist_id GROUP BY ar.genre, t.id, t.title) AS base) AS r WHERE puesto <= 3 ORDER BY genre, puesto;$c17147$, false, $c17148$Subconsulta en el FROM$c17148$, 1);

