insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17185$primera-cancion-de-cada-oyente$c17185$), $c17186$WITH primeras AS (
  SELECT
    p.user_id,
    p.played_at,
    t.title AS track,
    ar.name AS artista,
    row_number() OVER (PARTITION BY p.user_id ORDER BY p.played_at, p.id) AS puesto
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  INNER JOIN artists AS ar ON ar.id = al.artist_id
  WHERE u.signup_at >= '2025-03-01'
    AND u.signup_at < '2025-04-01'
)
SELECT user_id, played_at, track, artista
FROM primeras
WHERE puesto = 1
ORDER BY user_id;$c17186$, true, 'reference', 0);

