delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17224$desafio-top-3-artistas-por-mes-en-peru$c17224$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17225$desafio-top-3-artistas-por-mes-en-peru$c17225$), $c17226$WITH mensual AS (
  SELECT
    date_trunc('month', p.played_at)::date AS mes,
    ar.name AS artista,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  INNER JOIN artists AS ar ON ar.id = al.artist_id
  WHERE u.country = 'PE'
    AND p.played_at >= '2025-01-01'
    AND p.played_at < '2025-09-01'
  GROUP BY mes, ar.id, ar.name
),
ranking AS (
  SELECT
    mes,
    artista,
    reproducciones,
    dense_rank() OVER (PARTITION BY mes ORDER BY reproducciones DESC) AS puesto
  FROM mensual
)
SELECT mes, puesto, artista, reproducciones
FROM ranking
WHERE puesto <= 3
ORDER BY mes, puesto, artista;$c17226$, true, 'reference', 0);

