insert into public.exercise_hints (exercise_id, level, body_md, coin_cost, xp_penalty_percent)
values ((select id from public.exercises where slug = $c17231$desafio-top-3-artistas-por-mes-en-peru$c17231$), 3, $c17232$```sql
WITH mensual AS (
  SELECT date_trunc('___', p.played_at)::date AS mes, ar.name AS artista, count(*) AS reproducciones
