insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17259$altas-acumuladas-por-mes$c17259$), $c17260$WITH altas_por_mes AS (
  SELECT
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS altas
  FROM users
  GROUP BY 1
)
SELECT
  mes,
  altas,
  sum(altas) OVER (ORDER BY mes) AS altas_acumuladas
FROM altas_por_mes
ORDER BY mes;$c17260$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17261$altas-acumuladas-por-mes$c17261$), $c17262$WITH altas_por_mes AS (SELECT date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS altas FROM users GROUP BY 1) SELECT mes, altas, sum(altas) OVER (ORDER BY mes ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS altas_acumuladas FROM altas_por_mes ORDER BY mes;$c17262$, false, $c17263$Marco explícito$c17263$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17264$altas-acumuladas-por-mes$c17264$), $c17265$SELECT mes, altas, sum(altas) OVER (ORDER BY mes) AS altas_acumuladas FROM (SELECT date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS altas FROM users GROUP BY 1) AS altas_por_mes ORDER BY mes;$c17265$, false, $c17266$Subconsulta en lugar de CTE$c17266$, 2);

