insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17299$reproducciones-acumuladas-de-agosto$c17299$), $c17300$WITH diario AS (
  SELECT
    (played_at AT TIME ZONE 'UTC')::date AS dia,
    count(*) AS reproducciones
  FROM plays
  WHERE played_at >= timestamptz '2025-08-01 00:00:00+00'
    AND played_at < timestamptz '2025-09-01 00:00:00+00'
  GROUP BY 1
)
SELECT
  dia,
  reproducciones,
  sum(reproducciones) OVER (ORDER BY dia) AS acumulado_mes
FROM diario
ORDER BY dia;$c17300$, true, 'reference', 0);

