insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17336$media-movil-de-siete-dias$c17336$), $c17337$WITH diario AS (
  SELECT
    (played_at AT TIME ZONE 'UTC')::date AS dia,
    count(*) AS reproducciones
  FROM plays
  WHERE played_at >= timestamptz '2025-07-01 00:00:00+00'
  GROUP BY 1
),
con_media AS (
  SELECT
    dia,
    reproducciones,
    round(avg(reproducciones) OVER (
      ORDER BY dia
      ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
    ), 2) AS media_7d
  FROM diario
)
SELECT dia, reproducciones, media_7d
FROM con_media
WHERE dia >= DATE '2025-08-01'
ORDER BY dia;$c17337$, true, 'reference', 0);

