insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17371$acumulado-de-reproducciones-por-pais$c17371$), $c17372$WITH mensual AS (
  SELECT
    u.country,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  WHERE p.played_at >= timestamptz '2025-01-01 00:00:00+00'
  GROUP BY 1, 2
)
SELECT
  country,
  mes,
  reproducciones,
  sum(reproducciones) OVER (PARTITION BY country ORDER BY mes) AS acumulado
FROM mensual
ORDER BY country, mes;$c17372$, true, 'reference', 0);

