insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17408$curva-de-pareto-de-artistas$c17408$), $c17409$WITH por_artista AS (
  SELECT
    ar.name AS artista,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  INNER JOIN artists AS ar ON ar.id = al.artist_id
  WHERE p.played_at >= timestamptz '2025-01-01 00:00:00+00'
  GROUP BY 1
)
SELECT
  artista,
  reproducciones,
  round(
    100.0 * sum(reproducciones) OVER (ORDER BY reproducciones DESC, artista)
    / sum(reproducciones) OVER (),
    2
  ) AS pct_acumulado
FROM por_artista
ORDER BY reproducciones DESC, artista;$c17409$, true, 'reference', 0);

