insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17629$clientes-uruguay-que-no-volvieron$c17629$), $c17630$SELECT c.id AS customer_id, c.full_name, c.email
FROM orders AS o
INNER JOIN customers AS c ON c.id = o.customer_id
WHERE c.country = 'UY'
  AND o.status = 'delivered'
  AND o.created_at < DATE '2025-01-01'

EXCEPT

SELECT c.id AS customer_id, c.full_name, c.email
FROM orders AS o
INNER JOIN customers AS c ON c.id = o.customer_id
WHERE c.country = 'UY'
  AND o.status = 'delivered'
