delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17748$desafio-flujo-neto-mensual$c17748$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17749$desafio-flujo-neto-mensual$c17749$), $c17750$WITH movimientos AS (
  SELECT 'cobro' AS tipo, date_trunc('month', p.paid_at)::date AS mes, p.amount AS monto
  FROM payments AS p
  INNER JOIN orders AS o ON o.id = p.order_id
  WHERE p.status = 'approved'
    AND o.currency = 'MXN'
    AND p.paid_at >= DATE '2025-01-01'

  UNION ALL

  SELECT 'reembolso' AS tipo, date_trunc('month', r.requested_at)::date AS mes, r.refund_amount AS monto
  FROM returns AS r
  INNER JOIN orders AS o ON o.id = r.order_id
  WHERE o.currency = 'MXN'
    AND r.requested_at >= DATE '2025-01-01'
)
SELECT
  mes,
  round(sum(monto) FILTER (WHERE tipo = 'cobro'), 2) AS cobros,
  round(sum(monto) FILTER (WHERE tipo = 'reembolso'), 2) AS reembolsos,
  round(sum(monto) FILTER (WHERE tipo = 'cobro') - sum(monto) FILTER (WHERE tipo = 'reembolso'), 2) AS neto
FROM movimientos
GROUP BY mes
ORDER BY mes;$c17750$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17751$desafio-flujo-neto-mensual$c17751$), $c17752$WITH movimientos AS (SELECT 'cobro' AS tipo, date_trunc('month', p.paid_at)::date AS mes, p.amount AS monto FROM payments AS p INNER JOIN orders AS o ON o.id = p.order_id WHERE p.status = 'approved' AND o.currency = 'MXN' AND p.paid_at >= DATE '2025-01-01' UNION ALL SELECT 'reembolso' AS tipo, date_trunc('month', r.requested_at)::date AS mes, r.refund_amount AS monto FROM returns AS r INNER JOIN orders AS o ON o.id = r.order_id WHERE o.currency = 'MXN' AND r.requested_at >= DATE '2025-01-01') SELECT mes, round(sum(CASE WHEN tipo = 'cobro' THEN monto ELSE 0 END), 2) AS cobros, round(sum(CASE WHEN tipo = 'reembolso' THEN monto ELSE 0 END), 2) AS reembolsos, round(sum(CASE WHEN tipo = 'cobro' THEN monto ELSE -monto END), 2) AS neto FROM movimientos GROUP BY mes ORDER BY mes;$c17752$, false, $c17753$SUM(CASE ...) en lugar de FILTER$c17753$, 1);

