delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17786$reproducciones-contra-el-mes-anterior$c17786$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17787$reproducciones-contra-el-mes-anterior$c17787$), $c17788$WITH mensual AS (
  SELECT
    date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays
  GROUP BY 1
)
SELECT
  mes,
  reproducciones,
  lag(reproducciones) OVER (ORDER BY mes) AS reproducciones_mes_anterior,
  reproducciones - lag(reproducciones) OVER (ORDER BY mes) AS variacion
FROM mensual
ORDER BY mes;$c17788$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17789$reproducciones-contra-el-mes-anterior$c17789$), $c17790$WITH mensual AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays GROUP BY 1), con_anterior AS (SELECT mes, reproducciones, lag(reproducciones) OVER (ORDER BY mes) AS anterior FROM mensual) SELECT mes, reproducciones, anterior AS reproducciones_mes_anterior, reproducciones - anterior AS variacion FROM con_anterior ORDER BY mes;$c17790$, false, $c17791$Segunda CTE para no repetir el lag$c17791$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17792$reproducciones-contra-el-mes-anterior$c17792$), $c17793$SELECT mes, reproducciones, lag(reproducciones) OVER (ORDER BY mes) AS reproducciones_mes_anterior, reproducciones - lag(reproducciones) OVER (ORDER BY mes) AS variacion FROM (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays GROUP BY 1) AS mensual ORDER BY mes;$c17793$, false, $c17794$Subconsulta en lugar de CTE$c17794$, 2);

