delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17828$variacion-porcentual-de-altas$c17828$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17829$variacion-porcentual-de-altas$c17829$), $c17830$WITH altas_por_mes AS (
  SELECT
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS altas
  FROM users
  GROUP BY 1
),
con_anterior AS (
  SELECT
    mes,
    altas,
    lag(altas) OVER (ORDER BY mes) AS altas_mes_anterior
  FROM altas_por_mes
)
SELECT
  mes,
  altas,
  altas_mes_anterior,
  round(100.0 * (altas - altas_mes_anterior) / nullif(altas_mes_anterior, 0), 1) AS variacion_pct
FROM con_anterior
ORDER BY mes;$c17830$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17831$variacion-porcentual-de-altas$c17831$), $c17832$WITH altas_por_mes AS (SELECT date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS altas FROM users GROUP BY 1) SELECT mes, altas, lag(altas) OVER (ORDER BY mes) AS altas_mes_anterior, round(100.0 * (altas - lag(altas) OVER (ORDER BY mes)) / nullif(lag(altas) OVER (ORDER BY mes), 0), 1) AS variacion_pct FROM altas_por_mes ORDER BY mes;$c17832$, false, $c17833$Repitiendo el lag en la fórmula$c17833$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17834$variacion-porcentual-de-altas$c17834$), $c17835$WITH altas_por_mes AS (SELECT date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS altas FROM users GROUP BY 1), con_anterior AS (SELECT mes, altas, lag(altas) OVER (ORDER BY mes) AS altas_mes_anterior FROM altas_por_mes) SELECT mes, altas, altas_mes_anterior, round(100.0 * (altas::numeric / nullif(altas_mes_anterior, 0) - 1), 1) AS variacion_pct FROM con_anterior ORDER BY mes;$c17835$, false, $c17836$Razón menos uno$c17836$, 2);

