insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17871$variacion-mensual-por-pais$c17871$), $c17872$WITH mensual AS (
  SELECT
    u.country,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  GROUP BY 1, 2
)
SELECT
  country,
  mes,
  reproducciones,
  reproducciones - lag(reproducciones) OVER (PARTITION BY country ORDER BY mes) AS variacion
FROM mensual
ORDER BY country, mes;$c17872$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17873$variacion-mensual-por-pais$c17873$), $c17874$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id GROUP BY 1, 2), con_anterior AS (SELECT country, mes, reproducciones, lag(reproducciones) OVER (PARTITION BY country ORDER BY mes) AS anterior FROM mensual) SELECT country, mes, reproducciones, reproducciones - anterior AS variacion FROM con_anterior ORDER BY country, mes;$c17874$, false, $c17875$CTE intermedia con el mes anterior$c17875$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17876$variacion-mensual-por-pais$c17876$), $c17877$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id GROUP BY 1, 2) SELECT country, mes, reproducciones, reproducciones - lag(reproducciones, 1) OVER (PARTITION BY country ORDER BY mes ASC) AS variacion FROM mensual ORDER BY country ASC, mes ASC;$c17877$, false, $c17878$Desplazamiento y sentido del orden explícitos$c17878$, 2);

