insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17952$dias-hasta-el-siguiente-album$c17952$), $c17953$SELECT
  ar.name AS artista,
  al.title AS album,
  al.released_on,
  lead(al.released_on) OVER (PARTITION BY ar.id ORDER BY al.released_on) AS siguiente_lanzamiento,
  lead(al.released_on) OVER (PARTITION BY ar.id ORDER BY al.released_on) - al.released_on AS dias_hasta_siguiente
FROM albums AS al
INNER JOIN artists AS ar ON ar.id = al.artist_id
WHERE ar.genre = 'cumbia'
ORDER BY artista, al.released_on;$c17953$, true, 'reference', 0);

