delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17994$indice-contra-el-ultimo-mes$c17994$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17995$indice-contra-el-ultimo-mes$c17995$), $c17996$WITH mensual AS (
  SELECT
    u.country,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00'
  GROUP BY 1, 2
),
con_base AS (
  SELECT
    country,
    mes,
    reproducciones,
    last_value(reproducciones) OVER (
      PARTITION BY country
      ORDER BY mes
      ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS reproducciones_ultimo_mes
  FROM mensual
)
SELECT
  country,
  mes,
  reproducciones,
  reproducciones_ultimo_mes,
  round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes
FROM con_base
ORDER BY country, mes;$c17996$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17997$indice-contra-el-ultimo-mes$c17997$), $c17998$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00' GROUP BY 1, 2), con_base AS (SELECT country, mes, reproducciones, first_value(reproducciones) OVER (PARTITION BY country ORDER BY mes DESC) AS reproducciones_ultimo_mes FROM mensual) SELECT country, mes, reproducciones, reproducciones_ultimo_mes, round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes FROM con_base ORDER BY country, mes;$c17998$, false, $c17999$first_value con orden descendente$c17999$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18000$indice-contra-el-ultimo-mes$c18000$), $c18001$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00' GROUP BY 1, 2), con_base AS (SELECT country, mes, reproducciones, nth_value(reproducciones, 1) OVER (PARTITION BY country ORDER BY mes DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS reproducciones_ultimo_mes FROM mensual) SELECT country, mes, reproducciones, reproducciones_ultimo_mes, round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes FROM con_base ORDER BY country, mes;$c18001$, false, $c18002$nth_value desde el final$c18002$, 2);

