insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18038$sesiones-de-escucha-por-mes$c18038$), $c18039$WITH marcadas AS (
  SELECT
    played_at,
    lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior
  FROM plays
),
clasificadas AS (
  SELECT
    date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes,
    CASE
      WHEN anterior IS NULL OR played_at - anterior > interval '30 minutes' THEN 1
      ELSE 0
    END AS inicia_sesion
  FROM marcadas
)
SELECT
  mes,
  count(*) AS reproducciones,
  sum(inicia_sesion) AS sesiones,
  round(count(*)::numeric / sum(inicia_sesion), 2) AS reproducciones_por_sesion
FROM clasificadas
GROUP BY mes
ORDER BY mes;$c18039$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18040$sesiones-de-escucha-por-mes$c18040$), $c18041$WITH marcadas AS (SELECT played_at, lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior FROM plays), clasificadas AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, (anterior IS NULL OR played_at - anterior > interval '30 minutes') AS inicia_sesion FROM marcadas) SELECT mes, count(*) AS reproducciones, count(*) FILTER (WHERE inicia_sesion) AS sesiones, round(count(*)::numeric / count(*) FILTER (WHERE inicia_sesion), 2) AS reproducciones_por_sesion FROM clasificadas GROUP BY mes ORDER BY mes;$c18041$, false, $c18042$Bandera booleana con FILTER$c18042$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18043$sesiones-de-escucha-por-mes$c18043$), $c18044$WITH marcadas AS (SELECT played_at, lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior FROM plays), clasificadas AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, CASE WHEN anterior IS NULL OR extract(epoch FROM played_at - anterior) > 1800 THEN 1 ELSE 0 END AS inicia_sesion FROM marcadas) SELECT mes, count(*) AS reproducciones, sum(inicia_sesion) AS sesiones, round(count(*)::numeric / sum(inicia_sesion), 2) AS reproducciones_por_sesion FROM clasificadas GROUP BY mes ORDER BY mes;$c18044$, false, $c18045$Comparando segundos en lugar de intervalos$c18045$, 2);

