delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18118$activacion-en-los-primeros-siete-dias$c18118$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18119$activacion-en-los-primeros-siete-dias$c18119$), $c18120$WITH cohortes AS (
  SELECT
    id,
    signup_at,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
  WHERE signup_at < timestamptz '2025-09-01 00:00:00+00'
),
activados AS (
  SELECT DISTINCT c.id
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
  WHERE p.played_at < c.signup_at + INTERVAL '7 days'
)
SELECT
  c.cohorte,
  count(*) AS usuarios,
  count(a.id) AS activados,
  round(100.0 * count(a.id) / count(*), 2) AS tasa_activacion_pct
FROM cohortes AS c
LEFT JOIN activados AS a ON a.id = c.id
GROUP BY 1
ORDER BY 1;$c18120$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18121$activacion-en-los-primeros-siete-dias$c18121$), $c18122$WITH cohortes AS (SELECT id, signup_at, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-09-01 00:00:00+00'), activados AS (SELECT c.id FROM cohortes AS c WHERE EXISTS (SELECT 1 FROM plays AS p WHERE p.user_id = c.id AND p.played_at < c.signup_at + INTERVAL '7 days')) SELECT c.cohorte, count(*) AS usuarios, count(a.id) AS activados, round(100.0 * count(a.id) / count(*), 2) AS tasa_activacion_pct FROM cohortes AS c LEFT JOIN activados AS a ON a.id = c.id GROUP BY 1 ORDER BY 1;$c18122$, false, $c18123$Con EXISTS$c18123$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18124$activacion-en-los-primeros-siete-dias$c18124$), $c18125$WITH cohortes AS (SELECT id, signup_at, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-09-01 00:00:00+00'), marcados AS (SELECT c.cohorte, c.id, max(CASE WHEN p.played_at < c.signup_at + INTERVAL '7 days' THEN 1 ELSE 0 END) AS activado FROM cohortes AS c LEFT JOIN plays AS p ON p.user_id = c.id GROUP BY c.cohorte, c.id) SELECT cohorte, count(*) AS usuarios, coalesce(sum(activado), 0)::bigint AS activados, round(100.0 * coalesce(sum(activado), 0) / count(*), 2) AS tasa_activacion_pct FROM marcados GROUP BY 1 ORDER BY 1;$c18125$, false, $c18126$Marca por persona y suma condicional$c18126$, 2);

