insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18160$retencion-a-30-dias-por-cohorte$c18160$), $c18161$WITH cohortes AS (
  SELECT
    id,
    signup_at,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
  WHERE signup_at < timestamptz '2025-08-01 00:00:00+00'
),
retenidos AS (
  SELECT DISTINCT c.id
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
  WHERE p.played_at >= c.signup_at + INTERVAL '1 day'
    AND p.played_at < c.signup_at + INTERVAL '31 days'
)
SELECT
  c.cohorte,
  count(*) AS usuarios,
  count(r.id) AS retenidos_30d,
  round(100.0 * count(r.id) / count(*), 2) AS retencion_30d_pct
FROM cohortes AS c
LEFT JOIN retenidos AS r ON r.id = c.id
GROUP BY 1
ORDER BY 1;$c18161$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18162$retencion-a-30-dias-por-cohorte$c18162$), $c18163$WITH cohortes AS (SELECT id, signup_at, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-08-01 00:00:00+00') SELECT c.cohorte, count(*) AS usuarios, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM plays AS p WHERE p.user_id = c.id AND p.played_at >= c.signup_at + INTERVAL '1 day' AND p.played_at < c.signup_at + INTERVAL '31 days')) AS retenidos_30d, round(100.0 * count(*) FILTER (WHERE EXISTS (SELECT 1 FROM plays AS p WHERE p.user_id = c.id AND p.played_at >= c.signup_at + INTERVAL '1 day' AND p.played_at < c.signup_at + INTERVAL '31 days')) / count(*), 2) AS retencion_30d_pct FROM cohortes AS c GROUP BY 1 ORDER BY 1;$c18163$, false, $c18164$Con EXISTS$c18164$, 1);

