insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18199$matriz-de-cohortes-mensual$c18199$), $c18200$WITH cohortes AS (
  SELECT
    id,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
),
tamano AS (
  SELECT cohorte, count(*) AS usuarios_cohorte
  FROM cohortes
  GROUP BY 1
),
actividad AS (
  SELECT DISTINCT
    c.cohorte,
    c.id,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
)
SELECT
  a.cohorte,
  (12 * (date_part('year', a.mes) - date_part('year', a.cohorte))
      + (date_part('month', a.mes) - date_part('month', a.cohorte)))::int AS mes_indice,
  t.usuarios_cohorte,
  count(*) AS usuarios_activos,
  round(100.0 * count(*) / t.usuarios_cohorte, 2) AS retencion_pct
FROM actividad AS a
INNER JOIN tamano AS t ON t.cohorte = a.cohorte
GROUP BY a.cohorte, 2, t.usuarios_cohorte
ORDER BY a.cohorte, 2;$c18200$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18201$matriz-de-cohortes-mensual$c18201$), $c18202$WITH cohortes AS (SELECT id, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users), tamano AS (SELECT cohorte, count(*) AS usuarios_cohorte FROM cohortes GROUP BY 1), actividad AS (SELECT c.cohorte, c.id, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes FROM cohortes AS c INNER JOIN plays AS p ON p.user_id = c.id) SELECT a.cohorte, (12 * (date_part('year', a.mes) - date_part('year', a.cohorte)) + (date_part('month', a.mes) - date_part('month', a.cohorte)))::int AS mes_indice, t.usuarios_cohorte, count(DISTINCT a.id) AS usuarios_activos, round(100.0 * count(DISTINCT a.id) / t.usuarios_cohorte, 2) AS retencion_pct FROM actividad AS a INNER JOIN tamano AS t ON t.cohorte = a.cohorte GROUP BY a.cohorte, 2, t.usuarios_cohorte ORDER BY a.cohorte, 2;$c18202$, false, $c18203$Sin DISTINCT en la CTE, con count(DISTINCT ...)$c18203$, 1);

