insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18238$curva-de-retencion-promedio$c18238$), $c18239$WITH cohortes AS (
  SELECT
    id,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
  WHERE signup_at < timestamptz '2025-04-01 00:00:00+00'
),
base AS (
  SELECT count(*) AS usuarios_base FROM cohortes
),
actividad AS (
  SELECT DISTINCT
    c.id,
    (12 * (date_part('year', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date)
            - date_part('year', c.cohorte))
        + (date_part('month', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date)
            - date_part('month', c.cohorte)))::int AS mes_indice
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
)
SELECT
  a.mes_indice,
  b.usuarios_base,
  count(*) AS usuarios_activos,
  round(100.0 * count(*) / b.usuarios_base, 2) AS retencion_pct
FROM actividad AS a
CROSS JOIN base AS b
WHERE a.mes_indice <= 5
GROUP BY a.mes_indice, b.usuarios_base
ORDER BY a.mes_indice;$c18239$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18240$curva-de-retencion-promedio$c18240$), $c18241$WITH cohortes AS (SELECT id, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-04-01 00:00:00+00'), base AS (SELECT count(*) AS usuarios_base FROM cohortes), meses AS (SELECT DISTINCT c.id, c.cohorte, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes FROM cohortes AS c INNER JOIN plays AS p ON p.user_id = c.id), indices AS (SELECT id, (12 * (date_part('year', mes) - date_part('year', cohorte)) + (date_part('month', mes) - date_part('month', cohorte)))::int AS mes_indice FROM meses) SELECT i.mes_indice, b.usuarios_base, count(*) AS usuarios_activos, round(100.0 * count(*) / b.usuarios_base, 2) AS retencion_pct FROM indices AS i CROSS JOIN base AS b WHERE i.mes_indice <= 5 GROUP BY i.mes_indice, b.usuarios_base ORDER BY i.mes_indice;$c18241$, false, $c18242$Mes de actividad en una CTE intermedia$c18242$, 1);

