insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18276$churn-mensual-de-suscripciones$c18276$), $c18277$WITH meses AS (
  SELECT g::date AS mes
  FROM generate_series(DATE '2024-06-01', DATE '2025-08-01', INTERVAL '1 month') AS g
)
SELECT
  m.mes,
  count(*) FILTER (
    WHERE s.started_on < m.mes AND (s.ended_on IS NULL OR s.ended_on >= m.mes)
  ) AS activas_inicio,
  count(*) FILTER (
    WHERE s.ended_on >= m.mes AND s.ended_on < (m.mes + INTERVAL '1 month')::date
  ) AS bajas,
  round(
    100.0 * count(*) FILTER (
      WHERE s.ended_on >= m.mes AND s.ended_on < (m.mes + INTERVAL '1 month')::date
    )
    / nullif(count(*) FILTER (
        WHERE s.started_on < m.mes AND (s.ended_on IS NULL OR s.ended_on >= m.mes)
      ), 0),
    2
  ) AS churn_pct
FROM meses AS m
CROSS JOIN subscriptions AS s
GROUP BY m.mes
ORDER BY m.mes;$c18277$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18278$churn-mensual-de-suscripciones$c18278$), $c18279$WITH meses AS (SELECT g::date AS mes FROM generate_series(DATE '2024-06-01', DATE '2025-08-01', INTERVAL '1 month') AS g), conteos AS (SELECT m.mes, sum(CASE WHEN s.started_on < m.mes AND (s.ended_on IS NULL OR s.ended_on >= m.mes) THEN 1 ELSE 0 END) AS activas_inicio, sum(CASE WHEN s.ended_on >= m.mes AND s.ended_on < (m.mes + INTERVAL '1 month')::date THEN 1 ELSE 0 END) AS bajas FROM meses AS m CROSS JOIN subscriptions AS s GROUP BY m.mes) SELECT mes, activas_inicio, bajas, round(100.0 * bajas / nullif(activas_inicio, 0), 2) AS churn_pct FROM conteos ORDER BY mes;$c18279$, false, $c18280$Con CASE WHEN en lugar de FILTER$c18280$, 1);

