insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18315$retencion-del-mes-1-por-pais$c18315$), $c18316$WITH cohortes AS (
  SELECT
    id,
    country,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
  WHERE signup_at < timestamptz '2025-08-01 00:00:00+00'
),
activos_m1 AS (
  SELECT DISTINCT c.id
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
  WHERE date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date
        = (c.cohorte + INTERVAL '1 month')::date
)
SELECT
  c.country,
  count(*) AS usuarios,
  count(a.id) AS retenidos_m1,
  round(100.0 * count(a.id) / count(*), 2) AS retencion_m1_pct
FROM cohortes AS c
LEFT JOIN activos_m1 AS a ON a.id = c.id
GROUP BY c.country
ORDER BY 4 DESC, 1;$c18316$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18317$retencion-del-mes-1-por-pais$c18317$), $c18318$WITH cohortes AS (SELECT id, country, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-08-01 00:00:00+00'), activos_m1 AS (SELECT DISTINCT c.id FROM cohortes AS c INNER JOIN plays AS p ON p.user_id = c.id WHERE (12 * (date_part('year', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date) - date_part('year', c.cohorte)) + (date_part('month', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date) - date_part('month', c.cohorte)))::int = 1) SELECT c.country, count(*) AS usuarios, count(a.id) AS retenidos_m1, round(100.0 * count(a.id) / count(*), 2) AS retencion_m1_pct FROM cohortes AS c LEFT JOIN activos_m1 AS a ON a.id = c.id GROUP BY c.country ORDER BY 4 DESC, 1;$c18318$, false, $c18319$Índice de mes en lugar de suma de intervalo$c18319$, 1);

