insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18353$funnel-pasos-de-pedidos$c18353$), $c18354$SELECT
  CASE event
    WHEN 'placed' THEN 1
    WHEN 'accepted' THEN 2
    WHEN 'preparing' THEN 3
    WHEN 'picked_up' THEN 4
    WHEN 'delivered' THEN 5
  END AS paso,
  event AS etapa,
  count(DISTINCT order_id) AS pedidos
FROM order_events
WHERE event <> 'cancelled'
GROUP BY 1, 2
ORDER BY paso;$c18354$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18355$funnel-pasos-de-pedidos$c18355$), $c18356$SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event IN ('placed', 'accepted', 'preparing', 'picked_up', 'delivered') GROUP BY 1, 2 ORDER BY paso;$c18356$, false, $c18357$Filtro por lista de eventos del funnel$c18357$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18358$funnel-pasos-de-pedidos$c18358$), $c18359$SELECT paso, etapa, count(DISTINCT order_id) AS pedidos FROM (SELECT order_id, event AS etapa, CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso FROM order_events WHERE event <> 'cancelled') AS eventos_del_funnel GROUP BY paso, etapa ORDER BY paso;$c18359$, false, $c18360$El paso se calcula en una subconsulta$c18360$, 2);

