delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18393$funnel-conversion-paso-a-paso$c18393$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18394$funnel-conversion-paso-a-paso$c18394$), $c18395$WITH por_paso AS (
  SELECT
    CASE event
      WHEN 'placed' THEN 1
      WHEN 'accepted' THEN 2
      WHEN 'preparing' THEN 3
      WHEN 'picked_up' THEN 4
      WHEN 'delivered' THEN 5
    END AS paso,
    event AS etapa,
    count(DISTINCT order_id) AS pedidos
  FROM order_events
  WHERE event <> 'cancelled'
  GROUP BY 1, 2
)
SELECT
  paso,
  etapa,
  pedidos,
  round(100.0 * pedidos / lag(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_anterior,
  round(100.0 * pedidos / first_value(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_inicio
FROM por_paso
ORDER BY paso;$c18395$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18396$funnel-conversion-paso-a-paso$c18396$), $c18397$WITH por_paso AS (SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event <> 'cancelled' GROUP BY 1, 2) SELECT paso, etapa, pedidos, round(100.0 * pedidos / lag(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_anterior, round(100.0 * pedidos / (SELECT p.pedidos FROM por_paso AS p WHERE p.paso = 1), 2) AS pct_vs_inicio FROM por_paso ORDER BY paso;$c18397$, false, $c18398$El total del paso 1 con una subconsulta escalar$c18398$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18399$funnel-conversion-paso-a-paso$c18399$), $c18400$WITH por_paso AS (SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event <> 'cancelled' GROUP BY 1, 2) SELECT paso, etapa, pedidos, round(100.0 * pedidos / lag(pedidos, 1) OVER (ORDER BY paso), 2) AS pct_vs_anterior, round(100.0 * pedidos / first_value(pedidos) OVER (ORDER BY paso ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 2) AS pct_vs_inicio FROM por_paso ORDER BY paso;$c18400$, false, $c18401$Marco explícito en las dos ventanas$c18401$, 2);

