delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18436$funnel-pedido-pago-envio-entrega$c18436$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18437$funnel-pedido-pago-envio-entrega$c18437$), $c18438$WITH hitos AS (
  SELECT
    o.id AS order_id,
    min(pay.paid_at) AS pagado_at,
    min(shp.shipped_at) AS enviado_at,
    min(shp.delivered_at) AS entregado_at
  FROM orders AS o
  LEFT JOIN payments AS pay
    ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded')
  LEFT JOIN shipments AS shp ON shp.order_id = o.id
  WHERE o.created_at >= timestamptz '2025-01-01 00:00:00+00'
    AND o.created_at < timestamptz '2025-07-01 00:00:00+00'
  GROUP BY o.id
)
SELECT 1 AS paso, 'creado' AS etapa, count(*) AS pedidos FROM hitos
UNION ALL
SELECT 2, 'pagado', count(pagado_at) FROM hitos
UNION ALL
SELECT 3, 'enviado', count(enviado_at) FROM hitos
UNION ALL
SELECT 4, 'entregado', count(entregado_at) FROM hitos
ORDER BY paso;$c18438$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18439$funnel-pedido-pago-envio-entrega$c18439$), $c18440$WITH hitos AS (SELECT o.id AS order_id, min(pay.paid_at) AS pagado_at, min(shp.shipped_at) AS enviado_at, min(shp.delivered_at) AS entregado_at FROM orders AS o LEFT JOIN payments AS pay ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded') LEFT JOIN shipments AS shp ON shp.order_id = o.id WHERE o.created_at >= timestamptz '2025-01-01 00:00:00+00' AND o.created_at < timestamptz '2025-07-01 00:00:00+00' GROUP BY o.id) SELECT 1 AS paso, 'creado' AS etapa, count(*) AS pedidos FROM hitos UNION ALL SELECT 2, 'pagado', count(*) FILTER (WHERE pagado_at IS NOT NULL) FROM hitos UNION ALL SELECT 3, 'enviado', count(*) FILTER (WHERE enviado_at IS NOT NULL) FROM hitos UNION ALL SELECT 4, 'entregado', count(*) FILTER (WHERE entregado_at IS NOT NULL) FROM hitos ORDER BY paso;$c18440$, false, $c18441$count(*) FILTER en lugar de count(columna)$c18441$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18442$funnel-pedido-pago-envio-entrega$c18442$), $c18443$WITH hitos AS (SELECT o.id AS order_id, EXISTS (SELECT 1 FROM payments AS p WHERE p.order_id = o.id AND p.status IN ('approved', 'refunded')) AS pago_ok, EXISTS (SELECT 1 FROM shipments AS s WHERE s.order_id = o.id AND s.shipped_at IS NOT NULL) AS envio_ok, EXISTS (SELECT 1 FROM shipments AS s WHERE s.order_id = o.id AND s.delivered_at IS NOT NULL) AS entrega_ok FROM orders AS o WHERE o.created_at >= timestamptz '2025-01-01 00:00:00+00' AND o.created_at < timestamptz '2025-07-01 00:00:00+00') SELECT 1 AS paso, 'creado' AS etapa, count(*) AS pedidos FROM hitos UNION ALL SELECT 2, 'pagado', count(*) FILTER (WHERE pago_ok) FROM hitos UNION ALL SELECT 3, 'enviado', count(*) FILTER (WHERE envio_ok) FROM hitos UNION ALL SELECT 4, 'entregado', count(*) FILTER (WHERE entrega_ok) FROM hitos ORDER BY paso;$c18443$, false, $c18444$Hitos con subconsultas EXISTS$c18444$, 2);

