insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18480$funnel-por-canal-de-venta$c18480$), $c18481$WITH hitos AS (
  SELECT
    o.id AS order_id,
    o.channel,
    min(pay.paid_at) AS pagado_at,
    min(shp.delivered_at) AS entregado_at
  FROM orders AS o
  LEFT JOIN payments AS pay
    ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded')
  LEFT JOIN shipments AS shp ON shp.order_id = o.id
  GROUP BY o.id, o.channel
)
SELECT
  channel AS canal,
  count(*) AS pedidos,
  count(pagado_at) AS pagados,
  count(entregado_at) AS entregados,
  round(100.0 * count(pagado_at) / count(*), 2) AS pct_pago,
  round(100.0 * count(entregado_at) / nullif(count(pagado_at), 0), 2) AS pct_entrega_sobre_pago
FROM hitos
GROUP BY channel
ORDER BY canal;$c18481$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18482$funnel-por-canal-de-venta$c18482$), $c18483$WITH hitos AS (SELECT o.id AS order_id, o.channel, min(pay.paid_at) AS pagado_at, min(shp.delivered_at) AS entregado_at FROM orders AS o LEFT JOIN payments AS pay ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded') LEFT JOIN shipments AS shp ON shp.order_id = o.id GROUP BY o.id, o.channel) SELECT channel AS canal, count(*) AS pedidos, count(*) FILTER (WHERE pagado_at IS NOT NULL) AS pagados, count(*) FILTER (WHERE entregado_at IS NOT NULL) AS entregados, round(100.0 * count(*) FILTER (WHERE pagado_at IS NOT NULL) / count(*), 2) AS pct_pago, round(100.0 * count(*) FILTER (WHERE entregado_at IS NOT NULL) / nullif(count(*) FILTER (WHERE pagado_at IS NOT NULL), 0), 2) AS pct_entrega_sobre_pago FROM hitos GROUP BY channel ORDER BY canal;$c18483$, false, $c18484$FILTER en todos los conteos$c18484$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18485$funnel-por-canal-de-venta$c18485$), $c18486$WITH hitos AS (SELECT o.id AS order_id, o.channel, min(pay.paid_at) AS pagado_at, min(shp.delivered_at) AS entregado_at FROM orders AS o LEFT JOIN payments AS pay ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded') LEFT JOIN shipments AS shp ON shp.order_id = o.id GROUP BY o.id, o.channel), conteos AS (SELECT channel AS canal, count(*) AS pedidos, count(pagado_at) AS pagados, count(entregado_at) AS entregados FROM hitos GROUP BY channel) SELECT canal, pedidos, pagados, entregados, round(100.0 * pagados / pedidos, 2) AS pct_pago, round(100.0 * entregados / nullif(pagados, 0), 2) AS pct_entrega_sobre_pago FROM conteos ORDER BY canal;$c18486$, false, $c18487$Conteos en una CTE y tasas afuera$c18487$, 2);

