insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18521$funnel-punto-de-abandono$c18521$), $c18522$WITH avance AS (
  SELECT
    order_id,
    max(CASE event
      WHEN 'placed' THEN 1
      WHEN 'accepted' THEN 2
      WHEN 'preparing' THEN 3
      WHEN 'picked_up' THEN 4
      WHEN 'delivered' THEN 5
      ELSE 0
    END) AS ultimo_paso
  FROM order_events
  GROUP BY order_id
)
SELECT
  ultimo_paso,
  CASE ultimo_paso
    WHEN 1 THEN 'placed'
    WHEN 2 THEN 'accepted'
    WHEN 3 THEN 'preparing'
    WHEN 4 THEN 'picked_up'
    WHEN 5 THEN 'delivered'
  END AS ultima_etapa,
  count(*) AS pedidos,
  round(100.0 * count(*) / sum(count(*)) OVER (), 2) AS pct_del_total
FROM avance
GROUP BY 1, 2
ORDER BY ultimo_paso;$c18522$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18523$funnel-punto-de-abandono$c18523$), $c18524$WITH avance AS (SELECT order_id, max(CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 ELSE 0 END) AS ultimo_paso FROM order_events GROUP BY order_id), total AS (SELECT count(*) AS n FROM avance) SELECT a.ultimo_paso, CASE a.ultimo_paso WHEN 1 THEN 'placed' WHEN 2 THEN 'accepted' WHEN 3 THEN 'preparing' WHEN 4 THEN 'picked_up' WHEN 5 THEN 'delivered' END AS ultima_etapa, count(*) AS pedidos, round(100.0 * count(*) / (SELECT n FROM total), 2) AS pct_del_total FROM avance AS a GROUP BY 1, 2 ORDER BY a.ultimo_paso;$c18524$, false, $c18525$El total en una CTE aparte$c18525$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18526$funnel-punto-de-abandono$c18526$), $c18527$WITH avance AS (SELECT order_id, max(CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 ELSE 0 END) AS paso FROM order_events GROUP BY order_id), etiquetado AS (SELECT order_id, paso AS ultimo_paso, CASE paso WHEN 1 THEN 'placed' WHEN 2 THEN 'accepted' WHEN 3 THEN 'preparing' WHEN 4 THEN 'picked_up' WHEN 5 THEN 'delivered' END AS ultima_etapa FROM avance) SELECT ultimo_paso, ultima_etapa, count(*) AS pedidos, round(100.0 * count(*) / sum(count(*)) OVER (), 2) AS pct_del_total FROM etiquetado GROUP BY ultimo_paso, ultima_etapa ORDER BY ultimo_paso;$c18527$, false, $c18528$El nombre de la etapa se resuelve en la CTE$c18528$, 2);

