insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18611$funnel-tiempo-hasta-convertir-por-ciudad$c18611$), $c18612$WITH hitos AS (
  SELECT
    oe.order_id,
    min(oe.event_at) FILTER (WHERE oe.event = 'placed') AS placed_at,
    min(oe.event_at) FILTER (WHERE oe.event = 'accepted') AS accepted_at,
    min(oe.event_at) FILTER (WHERE oe.event = 'delivered') AS delivered_at
  FROM order_events AS oe
  GROUP BY oe.order_id
)
SELECT
  c.name AS ciudad,
  count(*) AS pedidos_entregados,
  round(avg(extract(epoch FROM h.accepted_at - h.placed_at) / 60), 2) AS min_prom_aceptacion,
  round(
    percentile_cont(0.5) WITHIN GROUP (
      ORDER BY extract(epoch FROM h.delivered_at - h.placed_at) / 60
    )::numeric,
    2
  ) AS min_mediana_entrega
FROM hitos AS h
INNER JOIN orders AS o ON o.id = h.order_id
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE h.delivered_at IS NOT NULL
GROUP BY c.name
ORDER BY min_mediana_entrega DESC, ciudad;$c18612$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18613$funnel-tiempo-hasta-convertir-por-ciudad$c18613$), $c18614$WITH hitos AS (SELECT oe.order_id, min(oe.event_at) FILTER (WHERE oe.event = 'placed') AS placed_at, min(oe.event_at) FILTER (WHERE oe.event = 'accepted') AS accepted_at, min(oe.event_at) FILTER (WHERE oe.event = 'delivered') AS delivered_at FROM order_events AS oe GROUP BY oe.order_id), duraciones AS (SELECT c.name AS ciudad, extract(epoch FROM h.accepted_at - h.placed_at) / 60 AS min_aceptacion, extract(epoch FROM h.delivered_at - h.placed_at) / 60 AS min_entrega FROM hitos AS h INNER JOIN orders AS o ON o.id = h.order_id INNER JOIN restaurants AS r ON r.id = o.restaurant_id INNER JOIN cities AS c ON c.id = r.city_id WHERE h.delivered_at IS NOT NULL) SELECT ciudad, count(*) AS pedidos_entregados, round(avg(min_aceptacion), 2) AS min_prom_aceptacion, round((percentile_cont(0.5) WITHIN GROUP (ORDER BY min_entrega))::numeric, 2) AS min_mediana_entrega FROM duraciones GROUP BY ciudad ORDER BY min_mediana_entrega DESC, ciudad;$c18614$, false, $c18615$Duraciones precalculadas en una segunda CTE$c18615$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18616$funnel-tiempo-hasta-convertir-por-ciudad$c18616$), $c18617$WITH hitos AS (SELECT oe.order_id, min(CASE WHEN oe.event = 'placed' THEN oe.event_at END) AS placed_at, min(CASE WHEN oe.event = 'accepted' THEN oe.event_at END) AS accepted_at, min(CASE WHEN oe.event = 'delivered' THEN oe.event_at END) AS delivered_at FROM order_events AS oe GROUP BY oe.order_id) SELECT c.name AS ciudad, count(*) AS pedidos_entregados, round(avg(extract(epoch FROM h.accepted_at - h.placed_at) / 60), 2) AS min_prom_aceptacion, round((percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM h.delivered_at - h.placed_at) / 60))::numeric, 2) AS min_mediana_entrega FROM hitos AS h INNER JOIN orders AS o ON o.id = h.order_id INNER JOIN restaurants AS r ON r.id = o.restaurant_id INNER JOIN cities AS c ON c.id = r.city_id WHERE h.delivered_at IS NOT NULL GROUP BY c.name ORDER BY min_mediana_entrega DESC, ciudad;$c18617$, false, $c18618$Hitos con CASE en lugar de FILTER$c18618$, 2);

