insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18688$dedup-listar-reproducciones-repetidas$c18688$), $c18689$SELECT user_id, track_id, played_at, veces
FROM (
  SELECT
    user_id,
    track_id,
    played_at,
    count(*) OVER (PARTITION BY user_id, track_id, played_at) AS veces,
    row_number() OVER (PARTITION BY user_id, track_id, played_at ORDER BY id) AS copia
  FROM plays
) AS marcadas
WHERE veces > 1 AND copia = 1
ORDER BY user_id, track_id, played_at;$c18689$, false, $c18690$Con una función de ventana en lugar de GROUP BY$c18690$, 1);

