insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18726$dedup-impacto-por-pais$c18726$), $c18727$SELECT
  u.country,
  count(*) AS reproducciones_crudas,
  count(DISTINCT (p.user_id, p.track_id, p.played_at)) AS reproducciones_unicas,
  count(*) - count(DISTINCT (p.user_id, p.track_id, p.played_at)) AS filas_sobrantes
FROM plays AS p
INNER JOIN users AS u ON u.id = p.user_id
GROUP BY u.country
ORDER BY filas_sobrantes DESC;$c18727$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18728$dedup-impacto-por-pais$c18728$), $c18729$WITH crudas AS (
  SELECT u.country, count(*) AS n
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  GROUP BY u.country
),
unicas AS (
  SELECT u.country, count(*) AS n
  FROM (SELECT DISTINCT user_id, track_id, played_at FROM plays) AS d
  INNER JOIN users AS u ON u.id = d.user_id
  GROUP BY u.country
)
SELECT
  c.country,
  c.n AS reproducciones_crudas,
  x.n AS reproducciones_unicas,
  c.n - x.n AS filas_sobrantes
FROM crudas AS c
INNER JOIN unicas AS x ON x.country = c.country
ORDER BY filas_sobrantes DESC;$c18729$, false, $c18730$Dos CTE: una con las filas crudas y otra con las únicas$c18730$, 1);

