insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18802$dedup-lista-de-filas-a-eliminar$c18802$), $c18803$WITH marcadas AS (
  SELECT
    id,
    user_id,
    track_id,
    row_number() OVER (PARTITION BY user_id, track_id, played_at ORDER BY id) AS copia,
    min(id) OVER (PARTITION BY user_id, track_id, played_at) AS id_conservado
  FROM plays
)
SELECT
  id AS id_a_eliminar,
  id_conservado,
  user_id,
  track_id
FROM marcadas
WHERE copia > 1
ORDER BY id_a_eliminar;$c18803$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18804$dedup-lista-de-filas-a-eliminar$c18804$), $c18805$SELECT
  p.id AS id_a_eliminar,
  g.id_conservado,
  p.user_id,
  p.track_id
FROM plays AS p
INNER JOIN (
  SELECT user_id, track_id, played_at, min(id) AS id_conservado
  FROM plays
  GROUP BY user_id, track_id, played_at
  HAVING count(*) > 1
) AS g
  ON g.user_id = p.user_id
 AND g.track_id = p.track_id
 AND g.played_at = p.played_at
WHERE p.id > g.id_conservado
ORDER BY id_a_eliminar;$c18805$, false, $c18806$Con una subconsulta agregada en lugar de ventanas$c18806$, 1);

