insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19006$chequeos-de-validez-en-reproducciones$c19006$), $c19007$SELECT
  count(*) AS checked_rows,
  count(*) FILTER (WHERE p.seconds_played IS NULL) AS null_seconds,
  count(*) FILTER (WHERE p.seconds_played < 0) AS negative_seconds,
  count(*) FILTER (WHERE p.seconds_played > t.duration_seconds) AS over_duration,
  round(
    100.0 * count(*) FILTER (
      WHERE p.seconds_played IS NULL
         OR p.seconds_played < 0
         OR p.seconds_played > t.duration_seconds
    ) / count(*),
    2
  ) AS invalid_pct
FROM plays p
JOIN tracks t ON t.id = p.track_id;$c19007$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19008$chequeos-de-validez-en-reproducciones$c19008$), $c19009$SELECT
  count(*) AS checked_rows,
  sum(CASE WHEN p.seconds_played IS NULL THEN 1 ELSE 0 END) AS null_seconds,
