insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19047$escuchas-mas-largas-que-la-cancion$c19047$), $c19048$SELECT
  p.id AS play_id,
  t.title AS track_title,
  t.duration_seconds,
  p.seconds_played,
  round(p.seconds_played::numeric / t.duration_seconds, 2) AS played_ratio
FROM plays p
JOIN tracks t ON t.id = p.track_id
WHERE p.seconds_played > t.duration_seconds
ORDER BY played_ratio DESC, play_id
LIMIT 20;$c19048$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19049$escuchas-mas-largas-que-la-cancion$c19049$), $c19050$SELECT
  p.id AS play_id,
  t.title AS track_title,
  t.duration_seconds,
  p.seconds_played,
  round(cast(p.seconds_played AS numeric) / t.duration_seconds, 2) AS played_ratio
FROM plays p
JOIN tracks t ON t.id = p.track_id
WHERE p.seconds_played > t.duration_seconds
ORDER BY round(cast(p.seconds_played AS numeric) / t.duration_seconds, 2) DESC, p.id ASC
LIMIT 20;$c19050$, false, $c19051$CAST explícito y orden por la expresión completa$c19051$, 1);

