insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19087$duplicados-exactos-en-reproducciones$c19087$), $c19088$SELECT
  user_id,
  track_id,
  played_at AT TIME ZONE 'UTC' AS played_at_utc,
  count(*) AS copies
FROM plays
GROUP BY user_id, track_id, played_at
HAVING count(*) > 1
ORDER BY user_id, track_id, played_at_utc;$c19088$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19089$duplicados-exactos-en-reproducciones$c19089$), $c19090$SELECT
  user_id,
  track_id,
  played_at AT TIME ZONE 'UTC' AS played_at_utc,
  count(*) AS copies
FROM plays
GROUP BY user_id, track_id, played_at AT TIME ZONE 'UTC'
HAVING count(*) > 1
ORDER BY 1, 2, 3;$c19090$, false, $c19091$Agrupando directamente por la marca convertida a UTC$c19091$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19092$duplicados-exactos-en-reproducciones$c19092$), $c19093$SELECT user_id, track_id, played_at_utc, copies
FROM (
  SELECT
    user_id,
    track_id,
    played_at AT TIME ZONE 'UTC' AS played_at_utc,
