delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c19175$tablero-de-calidad-de-reproducciones$c19175$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19176$tablero-de-calidad-de-reproducciones$c19176$), $c19177$WITH total AS (
  SELECT count(*) AS rows_checked FROM plays
),
fails AS (
  SELECT 'device_nulo' AS check_name, count(*) AS failing_rows
  FROM plays WHERE device IS NULL
  UNION ALL
  SELECT 'segundos_nulos', count(*)
  FROM plays WHERE seconds_played IS NULL
  UNION ALL
  SELECT 'segundos_negativos', count(*)
  FROM plays WHERE seconds_played < 0
  UNION ALL
  SELECT 'segundos_mayores_que_la_cancion', count(*)
  FROM plays p JOIN tracks t ON t.id = p.track_id
  WHERE p.seconds_played > t.duration_seconds
  UNION ALL
  SELECT 'claves_duplicadas', count(*)
  FROM (
    SELECT user_id, track_id, played_at
    FROM plays
    GROUP BY user_id, track_id, played_at
    HAVING count(*) > 1
  ) d
  UNION ALL
  SELECT 'escucha_posterior_al_churn', count(*)
  FROM plays p JOIN users u ON u.id = p.user_id
  WHERE u.churned_at IS NOT NULL AND p.played_at > u.churned_at
)
SELECT
  f.check_name,
  f.failing_rows,
  t.rows_checked,
  round(100.0 * f.failing_rows / t.rows_checked, 3) AS failing_pct
FROM fails f
CROSS JOIN total t
ORDER BY f.failing_rows DESC, f.check_name;$c19177$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19178$tablero-de-calidad-de-reproducciones$c19178$), $c19179$WITH fails AS (
  SELECT 'device_nulo' AS check_name, count(*) AS failing_rows
  FROM plays WHERE device IS NULL
  UNION ALL
  SELECT 'segundos_nulos', count(*)
  FROM plays WHERE seconds_played IS NULL
  UNION ALL
  SELECT 'segundos_negativos', count(*)
  FROM plays WHERE seconds_played < 0
  UNION ALL
  SELECT 'segundos_mayores_que_la_cancion', count(*)
  FROM plays p JOIN tracks t ON t.id = p.track_id
  WHERE p.seconds_played > t.duration_seconds
  UNION ALL
  SELECT 'claves_duplicadas', count(*)
  FROM (
    SELECT user_id, track_id, played_at
    FROM plays
    GROUP BY user_id, track_id, played_at
    HAVING count(*) > 1
  ) d
  UNION ALL
  SELECT 'escucha_posterior_al_churn', count(*)
  FROM plays p JOIN users u ON u.id = p.user_id
  WHERE u.churned_at IS NOT NULL AND p.played_at > u.churned_at
)
SELECT
  check_name,
  failing_rows,
  (SELECT count(*) FROM plays) AS rows_checked,
  round(100.0 * failing_rows / (SELECT count(*) FROM plays), 3) AS failing_pct
FROM fails
ORDER BY failing_rows DESC, check_name;$c19179$, false, $c19180$Total con una subconsulta escalar, sin CTE para el total$c19180$, 1);

