insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19303$ingresos-por-pais-sin-inflar$c19303$), $c19304$WITH items AS (SELECT order_id, count(*) AS lineas FROM order_items GROUP BY order_id) SELECT c.country, count(*) AS pedidos, round(sum(o.total_amount), 2) AS ingresos FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id LEFT JOIN items AS i ON i.order_id = o.id WHERE o.status = 'delivered' GROUP BY c.country ORDER BY c.country;$c19304$, false, $c19305$Con order_items agregado antes de unir$c19305$, 1);

