insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19343$ticket-promedio-al-grano-correcto$c19343$), $c19344$WITH por_pedido AS (
  SELECT
    o.id,
    c.country,
    o.channel,
    o.total_amount,
    count(*) AS lineas
  FROM orders AS o
  INNER JOIN customers AS c ON c.id = o.customer_id
  INNER JOIN order_items AS oi ON oi.order_id = o.id
  WHERE o.status = 'delivered'
  GROUP BY o.id, c.country, o.channel, o.total_amount
)
SELECT
  country,
  channel,
  count(*) AS pedidos,
  round(avg(total_amount), 2) AS ticket_promedio,
  round(avg(lineas), 3) AS lineas_por_pedido
FROM por_pedido
GROUP BY country, channel
ORDER BY country, channel;$c19344$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19345$ticket-promedio-al-grano-correcto$c19345$), $c19346$WITH items AS (SELECT order_id, count(*) AS lineas FROM order_items GROUP BY order_id) SELECT c.country, o.channel, count(*) AS pedidos, round(avg(o.total_amount), 2) AS ticket_promedio, round(avg(i.lineas), 3) AS lineas_por_pedido FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id INNER JOIN items AS i ON i.order_id = o.id WHERE o.status = 'delivered' GROUP BY c.country, o.channel ORDER BY c.country, o.channel;$c19346$, false, $c19347$Líneas agregadas antes de unir$c19347$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19348$ticket-promedio-al-grano-correcto$c19348$), $c19349$WITH por_pedido AS (SELECT o.id, c.country, o.channel, o.total_amount, (SELECT count(*) FROM order_items AS oi WHERE oi.order_id = o.id) AS lineas FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id WHERE o.status = 'delivered') SELECT country, channel, count(*) AS pedidos, round(avg(total_amount), 2) AS ticket_promedio, round(avg(lineas), 3) AS lineas_por_pedido FROM por_pedido WHERE lineas > 0 GROUP BY country, channel ORDER BY country, channel;$c19349$, false, $c19350$Líneas con una subconsulta correlacionada$c19350$, 2);

