insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19383$tiempo-de-entrega-sin-contaminar$c19383$), $c19384$SELECT
  s.carrier,
  count(*) AS envios,
  count(s.delivered_at) AS entregados,
  count(*) - count(s.delivered_at) AS sin_entregar,
  round(avg(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0)::numeric, 2) AS horas_promedio
FROM shipments AS s
GROUP BY s.carrier
ORDER BY s.carrier;$c19384$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19385$tiempo-de-entrega-sin-contaminar$c19385$), $c19386$SELECT s.carrier, count(*) AS envios, count(*) FILTER (WHERE s.delivered_at IS NOT NULL) AS entregados, count(*) FILTER (WHERE s.delivered_at IS NULL) AS sin_entregar, round(avg(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0) FILTER (WHERE s.delivered_at IS NOT NULL)::numeric, 2) AS horas_promedio FROM shipments AS s GROUP BY s.carrier ORDER BY s.carrier;$c19386$, false, $c19387$Con FILTER explícito$c19387$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19388$tiempo-de-entrega-sin-contaminar$c19388$), $c19389$SELECT s.carrier, count(*) AS envios, count(s.delivered_at) AS entregados, count(*) - count(s.delivered_at) AS sin_entregar, round((sum(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0) / nullif(count(s.delivered_at), 0))::numeric, 2) AS horas_promedio FROM shipments AS s GROUP BY s.carrier ORDER BY s.carrier;$c19389$, false, $c19390$Suma dividida por los entregados$c19390$, 2);

