insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19427$reconciliar-paso-a-paso$c19427$), $c19428$WITH creados AS (
  SELECT id FROM orders
),
finalizados AS (
  SELECT id FROM orders WHERE status IN ('delivered', 'returned')
),
con_pago AS (
  SELECT f.id
  FROM finalizados AS f
  WHERE EXISTS (SELECT 1 FROM payments AS p WHERE p.order_id = f.id AND p.status = 'approved')
),
con_entrega AS (
  SELECT c.id
  FROM con_pago AS c
  WHERE EXISTS (SELECT 1 FROM shipments AS s WHERE s.order_id = c.id AND s.delivered_at IS NOT NULL)
),
sin_devolucion AS (
  SELECT e.id
  FROM con_entrega AS e
  WHERE NOT EXISTS (SELECT 1 FROM returns AS r WHERE r.order_id = e.id)
),
pasos AS (
  SELECT 1 AS paso, 'pedidos creados' AS etapa, count(*) AS pedidos FROM creados
  UNION ALL
  SELECT 2, 'entregados o devueltos', count(*) FROM finalizados
  UNION ALL
  SELECT 3, 'con pago aprobado', count(*) FROM con_pago
  UNION ALL
  SELECT 4, 'con envio entregado', count(*) FROM con_entrega
  UNION ALL
  SELECT 5, 'sin devolucion', count(*) FROM sin_devolucion
)
SELECT
  paso,
  etapa,
  pedidos,
  coalesce(lag(pedidos) OVER (ORDER BY paso) - pedidos, 0) AS perdidos
FROM pasos
ORDER BY paso;$c19428$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19429$reconciliar-paso-a-paso$c19429$), $c19430$WITH marcas AS (SELECT o.id, (o.status IN ('delivered','returned')) AS p2, EXISTS (SELECT 1 FROM payments AS p WHERE p.order_id = o.id AND p.status = 'approved') AS p3, EXISTS (SELECT 1 FROM shipments AS s WHERE s.order_id = o.id AND s.delivered_at IS NOT NULL) AS p4, NOT EXISTS (SELECT 1 FROM returns AS r WHERE r.order_id = o.id) AS p5 FROM orders AS o), pasos AS (SELECT 1 AS paso, 'pedidos creados' AS etapa, count(*) AS pedidos FROM marcas UNION ALL SELECT 2, 'entregados o devueltos', count(*) FILTER (WHERE p2) FROM marcas UNION ALL SELECT 3, 'con pago aprobado', count(*) FILTER (WHERE p2 AND p3) FROM marcas UNION ALL SELECT 4, 'con envio entregado', count(*) FILTER (WHERE p2 AND p3 AND p4) FROM marcas UNION ALL SELECT 5, 'sin devolucion', count(*) FILTER (WHERE p2 AND p3 AND p4 AND p5) FROM marcas) SELECT paso, etapa, pedidos, coalesce(lag(pedidos) OVER (ORDER BY paso) - pedidos, 0) AS perdidos FROM pasos ORDER BY paso;$c19430$, false, $c19431$Marcas booleanas por pedido$c19431$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19432$reconciliar-paso-a-paso$c19432$), $c19433$WITH finalizados AS (SELECT id FROM orders WHERE status IN ('delivered','returned')), con_pago AS (SELECT DISTINCT f.id FROM finalizados AS f INNER JOIN payments AS p ON p.order_id = f.id AND p.status = 'approved'), con_entrega AS (SELECT DISTINCT c.id FROM con_pago AS c INNER JOIN shipments AS s ON s.order_id = c.id AND s.delivered_at IS NOT NULL), sin_devolucion AS (SELECT e.id FROM con_entrega AS e LEFT JOIN returns AS r ON r.order_id = e.id WHERE r.id IS NULL), pasos AS (SELECT 1 AS paso, 'pedidos creados' AS etapa, count(*) AS pedidos FROM orders UNION ALL SELECT 2, 'entregados o devueltos', count(*) FROM finalizados UNION ALL SELECT 3, 'con pago aprobado', count(*) FROM con_pago UNION ALL SELECT 4, 'con envio entregado', count(*) FROM con_entrega UNION ALL SELECT 5, 'sin devolucion', count(*) FROM sin_devolucion) SELECT paso, etapa, pedidos, coalesce(lag(pedidos) OVER (ORDER BY paso) - pedidos, 0) AS perdidos FROM pasos ORDER BY paso;$c19433$, false, $c19434$Cadena con semi-joins en lugar de EXISTS$c19434$, 2);

