  SELECT ___ p.category_id, o.id AS order_id, (o.status = '___') AS devuelto
  FROM orders AS o
  INNER JOIN order_items AS oi ON oi.order_id = o.id
  INNER JOIN products AS p ON p.id = ___
  WHERE o.status IN (___, ___)
)
SELECT
  c.name AS categoria,
  count(*) AS pedidos,
  count(*) ___ (WHERE pc.devuelto) AS devueltos,
  round(100.0 * ___ / ___, 2) AS tasa_pct
FROM pedido_categoria AS pc
INNER JOIN categories AS c ON c.id = pc.category_id
GROUP BY c.name
ORDER BY tasa_pct DESC, categoria ASC;
