insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19587$mrr-al-cierre-de-agosto$c19587$), $c19588$SELECT
  s.currency AS moneda,
