insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19589$mrr-al-cierre-de-agosto$c19589$), $c19590$SELECT s.currency AS moneda, count(*) AS suscripciones, sum(CASE WHEN s.plan = 'premium' THEN 1 ELSE 0 END) AS premium, sum(CASE WHEN s.plan = 'familiar' THEN 1 ELSE 0 END) AS familiar, sum(s.amount_minor) AS mrr_minor FROM subscriptions AS s WHERE s.started_on <= DATE '2025-08-31' AND coalesce(s.ended_on, DATE '9999-12-31') > DATE '2025-08-31' GROUP BY s.currency ORDER BY s.currency;$c19590$, false, $c19591$Con coalesce en lugar de la rama IS NULL$c19591$, 1);

