insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19628$vendedores-a-priorizar-en-mexico$c19628$), $c19629$WITH vendidos AS (
  SELECT
    p.seller_id,
    o.id AS order_id,
    oi.quantity * oi.unit_price AS importe
  FROM order_items AS oi
  INNER JOIN orders AS o ON o.id = oi.order_id
  INNER JOIN products AS p ON p.id = oi.product_id
  WHERE o.status = 'delivered'
    AND o.currency = 'MXN'
    AND o.created_at >= timestamptz '2025-06-01 00:00:00+00'
    AND o.created_at <  timestamptz '2025-09-01 00:00:00+00'
),
por_vendedor AS (
  SELECT
    v.seller_id,
    count(DISTINCT v.order_id) AS pedidos,
    round(sum(v.importe), 2) AS ingresos
  FROM vendidos AS v
  GROUP BY v.seller_id
)
SELECT
  s.store_name AS vendedor,
  pv.pedidos,
  pv.ingresos,
  round(100.0 * pv.ingresos / sum(pv.ingresos) OVER (), 2) AS participacion_pct
FROM por_vendedor AS pv
INNER JOIN sellers AS s ON s.id = pv.seller_id
ORDER BY pv.ingresos DESC, s.store_name
LIMIT 10;$c19629$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19630$vendedores-a-priorizar-en-mexico$c19630$), $c19631$WITH vendidos AS (SELECT p.seller_id, o.id AS order_id, oi.quantity * oi.unit_price AS importe FROM order_items AS oi INNER JOIN orders AS o ON o.id = oi.order_id INNER JOIN products AS p ON p.id = oi.product_id WHERE o.status = 'delivered' AND o.currency = 'MXN' AND o.created_at >= timestamptz '2025-06-01 00:00:00+00' AND o.created_at < timestamptz '2025-09-01 00:00:00+00'), por_vendedor AS (SELECT v.seller_id, count(DISTINCT v.order_id) AS pedidos, round(sum(v.importe), 2) AS ingresos FROM vendidos AS v GROUP BY v.seller_id) SELECT s.store_name AS vendedor, pv.pedidos, pv.ingresos, round(100.0 * pv.ingresos / (SELECT sum(ingresos) FROM por_vendedor), 2) AS participacion_pct FROM por_vendedor AS pv INNER JOIN sellers AS s ON s.id = pv.seller_id ORDER BY pv.ingresos DESC, s.store_name LIMIT 10;$c19631$, false, $c19632$Con una subconsulta escalar como denominador$c19632$, 1);

