insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19752$volumen-transaccionado-en-dolares$c19752$), $c19753$WITH pagos AS (
  SELECT
    date_trunc('month', t.created_at AT TIME ZONE 'UTC')::date AS mes,
    a.user_id,
    t.amount / coalesce(f.usd_rate, 1) AS monto_usd
  FROM transactions AS t
  INNER JOIN accounts AS a ON a.id = t.account_id
  LEFT JOIN fx_rates AS f
    ON f.currency = t.currency
   AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date
  WHERE t.kind IN ('card_payment', 'qr_payment')
    AND t.status = 'completed'
    AND t.created_at >= timestamptz '2025-01-01 00:00:00+00'
    AND t.created_at <  timestamptz '2025-09-01 00:00:00+00'
)
SELECT
  p.mes,
  count(DISTINCT p.user_id) AS usuarios_activos,
  count(*) AS pagos,
  round(sum(p.monto_usd), 2) AS volumen_usd,
  round(sum(p.monto_usd) / count(*), 2) AS ticket_usd
FROM pagos AS p
GROUP BY p.mes
ORDER BY p.mes;$c19753$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19754$volumen-transaccionado-en-dolares$c19754$), $c19755$WITH pagos AS (SELECT date_trunc('month', t.created_at AT TIME ZONE 'UTC')::date AS mes, a.user_id, t.amount / coalesce(f.usd_rate, 1) AS monto_usd FROM transactions AS t INNER JOIN accounts AS a ON a.id = t.account_id LEFT JOIN fx_rates AS f ON f.currency = t.currency AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date WHERE t.kind IN ('card_payment', 'qr_payment') AND t.status = 'completed' AND t.created_at >= timestamptz '2025-01-01 00:00:00+00' AND t.created_at < timestamptz '2025-09-01 00:00:00+00') SELECT mes, count(DISTINCT user_id) AS usuarios_activos, count(*) AS pagos, round(sum(monto_usd), 2) AS volumen_usd, round(avg(monto_usd), 2) AS ticket_usd FROM pagos GROUP BY mes ORDER BY mes;$c19755$, false, $c19756$Con avg() para el ticket y la conversión en el SELECT$c19756$, 1);

