insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19792$entrevista-segundo-mas-vendido-por-categoria$c19792$), $c19793$WITH ventas AS (
  SELECT p.category_id, p.id AS product_id, p.name AS product_name, sum(oi.quantity) AS unidades
  FROM order_items AS oi
  INNER JOIN products AS p ON p.id = oi.product_id
