insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19834$entrevista-repartidores-sin-entregas$c19834$), $c19835$SELECT
  c.id AS courier_id,
  c.full_name,
  ci.name AS city,
  c.vehicle,
  c.started_at
FROM couriers AS c
INNER JOIN cities AS ci ON ci.id = c.city_id
WHERE c.is_active
