      AND o.placed_at >= timestamptz '2025-08-01 00:00:00+00'
      AND o.placed_at < timestamptz '2025-09-01 00:00:00+00'
  )
ORDER BY ci.name, c.full_name, c.id;$c19835$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19836$entrevista-repartidores-sin-entregas$c19836$), $c19837$SELECT c.id AS courier_id, c.full_name, ci.name AS city, c.vehicle, c.started_at
