 AND o.placed_at >= timestamptz '2025-08-01 00:00:00+00'
 AND o.placed_at < timestamptz '2025-09-01 00:00:00+00'
WHERE c.is_active AND o.id IS NULL
ORDER BY ci.name, c.full_name, c.id;$c19837$, false, $c19838$LEFT JOIN con la condición en el ON$c19838$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19839$entrevista-repartidores-sin-entregas$c19839$), $c19840$SELECT c.id AS courier_id, c.full_name, ci.name AS city, c.vehicle, c.started_at
