insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19918$entrevista-correos-duplicados-y-fila-ganadora$c19918$), $c19919$WITH normalizados AS (
  SELECT id, lower(trim(email)) AS correo, signup_at
  FROM customers
),
duplicados AS (
  SELECT correo, count(*) AS cuentas
  FROM normalizados
  GROUP BY correo
  HAVING count(*) > 1
),
ganador AS (
  SELECT DISTINCT ON (n.correo) n.correo, n.id AS id_a_conservar
  FROM normalizados AS n
  INNER JOIN duplicados AS d ON d.correo = n.correo
  ORDER BY n.correo, n.signup_at, n.id
)
SELECT
  d.correo,
  d.cuentas,
  g.id_a_conservar,
  count(o.id) AS pedidos_totales
FROM duplicados AS d
INNER JOIN ganador AS g ON g.correo = d.correo
INNER JOIN normalizados AS n ON n.correo = d.correo
LEFT JOIN orders AS o ON o.customer_id = n.id
GROUP BY d.correo, d.cuentas, g.id_a_conservar
ORDER BY d.cuentas DESC, d.correo;$c19919$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19920$entrevista-correos-duplicados-y-fila-ganadora$c19920$), $c19921$WITH normalizados AS (
  SELECT id, lower(trim(email)) AS correo, signup_at
  FROM customers
),
ordenados AS (
  SELECT
    correo,
    id,
    count(*) OVER (PARTITION BY correo) AS cuentas,
    row_number() OVER (PARTITION BY correo ORDER BY signup_at, id) AS orden
  FROM normalizados
),
ganador AS (
  SELECT correo, cuentas, id AS id_a_conservar FROM ordenados WHERE orden = 1 AND cuentas > 1
)
SELECT
  g.correo,
  g.cuentas,
  g.id_a_conservar,
  count(o.id) AS pedidos_totales
FROM ganador AS g
INNER JOIN normalizados AS n ON n.correo = g.correo
LEFT JOIN orders AS o ON o.customer_id = n.id
GROUP BY g.correo, g.cuentas, g.id_a_conservar
ORDER BY g.cuentas DESC, g.correo;$c19921$, false, $c19922$ROW_NUMBER en lugar de DISTINCT ON$c19922$, 1);

