insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19995$entrevista-tres-veces-seguidas$c19995$), $c19996$WITH secuencia AS (
  SELECT
    user_id,
    track_id,
    played_at,
    lag(track_id) OVER (PARTITION BY user_id ORDER BY played_at, id) AS anterior_1,
    lag(track_id, 2) OVER (PARTITION BY user_id ORDER BY played_at, id) AS anterior_2
  FROM plays
)
SELECT
  s.user_id,
  s.track_id,
  t.title,
  s.played_at AT TIME ZONE 'UTC' AS tercera_utc
FROM secuencia AS s
INNER JOIN tracks AS t ON t.id = s.track_id
WHERE s.track_id = s.anterior_1
  AND s.track_id = s.anterior_2
ORDER BY s.user_id, tercera_utc;$c19996$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19997$entrevista-tres-veces-seguidas$c19997$), $c19998$WITH ordenadas AS (
  SELECT
    user_id, track_id, played_at, id,
    row_number() OVER (PARTITION BY user_id ORDER BY played_at, id) AS pos_global,
    row_number() OVER (PARTITION BY user_id, track_id ORDER BY played_at, id) AS pos_cancion
  FROM plays
),
bloques AS (
  SELECT
    user_id, track_id, played_at,
    row_number() OVER (PARTITION BY user_id, track_id, pos_global - pos_cancion ORDER BY played_at, id) AS seguidas
  FROM ordenadas
)
SELECT b.user_id, b.track_id, t.title, b.played_at AT TIME ZONE 'UTC' AS tercera_utc
FROM bloques AS b
INNER JOIN tracks AS t ON t.id = b.track_id
WHERE b.seguidas >= 3
ORDER BY b.user_id, tercera_utc;$c19998$, false, $c19999$Brechas e islas sobre la secuencia de reproducciones$c19999$, 1);

