insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20155$cancion-estrella-de-cada-artista$c20155$), $c20156$SELECT
  a.name AS artista,
  t.cancion,
  t.reproducciones
FROM artists AS a
CROSS JOIN LATERAL (
  SELECT tr.title AS cancion, count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN tracks AS tr ON tr.id = p.track_id
  INNER JOIN albums AS al ON al.id = tr.album_id
  WHERE al.artist_id = a.id
    AND p.played_at >= '2025-01-01T00:00:00Z'::timestamptz
  GROUP BY tr.id, tr.title
  ORDER BY count(*) DESC, tr.title
  LIMIT 1
) AS t
WHERE a.genre = 'cumbia'
ORDER BY t.reproducciones DESC, a.name;$c20156$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20157$cancion-estrella-de-cada-artista$c20157$), $c20158$WITH conteos AS (
