    al.artist_id,
    tr.title AS cancion,
    count(*) AS reproducciones,
    row_number() OVER (PARTITION BY al.artist_id ORDER BY count(*) DESC, tr.title) AS puesto
  FROM plays AS p
  INNER JOIN tracks AS tr ON tr.id = p.track_id
  INNER JOIN albums AS al ON al.id = tr.album_id
  WHERE p.played_at >= '2025-01-01T00:00:00Z'::timestamptz
  GROUP BY al.artist_id, tr.id, tr.title
)
SELECT a.name AS artista, c.cancion, c.reproducciones
FROM conteos AS c
INNER JOIN artists AS a ON a.id = c.artist_id
WHERE c.puesto = 1 AND a.genre = 'cumbia'
ORDER BY c.reproducciones DESC, a.name;$c20158$, false, $c20159$Numerar con ROW_NUMBER en una CTE y quedarse con el puesto 1$c20159$, 1);

