insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20196$top-3-comercios-por-rubro$c20196$), $c20197$WITH pagos AS (
  SELECT m.category, m.name, count(*) AS operaciones
  FROM transactions AS t
  INNER JOIN merchants AS m ON m.id = t.merchant_id
  WHERE t.status = 'completed'
    AND t.created_at >= '2025-01-01T00:00:00Z'::timestamptz
    AND t.created_at < '2025-07-01T00:00:00Z'::timestamptz
  GROUP BY m.category, m.name
),
totales AS (
  SELECT category, sum(operaciones) AS operaciones_rubro
  FROM pagos
  GROUP BY category
)
SELECT
  c.category AS categoria,
  top.puesto,
  top.name AS comercio,
  top.operaciones,
  round(100.0 * top.operaciones / c.operaciones_rubro, 2) AS participacion
FROM totales AS c
CROSS JOIN LATERAL (
  SELECT
    p.name,
    p.operaciones,
    row_number() OVER (ORDER BY p.operaciones DESC, p.name) AS puesto
  FROM pagos AS p
  WHERE p.category = c.category
  ORDER BY p.operaciones DESC, p.name
  LIMIT 3
) AS top
ORDER BY c.category, top.puesto;$c20197$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20198$top-3-comercios-por-rubro$c20198$), $c20199$WITH pagos AS (
  SELECT m.category, m.name, count(*) AS operaciones
  FROM transactions AS t
  INNER JOIN merchants AS m ON m.id = t.merchant_id
  WHERE t.status = 'completed'
    AND t.created_at >= '2025-01-01T00:00:00Z'::timestamptz
    AND t.created_at < '2025-07-01T00:00:00Z'::timestamptz
  GROUP BY m.category, m.name
),
rankeados AS (
  SELECT
    category,
    name,
    operaciones,
    row_number() OVER (PARTITION BY category ORDER BY operaciones DESC, name) AS puesto,
    sum(operaciones) OVER (PARTITION BY category) AS operaciones_rubro
  FROM pagos
)
SELECT
  category AS categoria,
  puesto,
  name AS comercio,
  operaciones,
  round(100.0 * operaciones / operaciones_rubro, 2) AS participacion
FROM rankeados
WHERE puesto <= 3
ORDER BY categoria, puesto;$c20199$, false, $c20200$Numerar y totalizar con ventanas, sin LATERAL$c20200$, 1);

