insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20275$rutas-de-estado-de-los-pedidos$c20275$), $c20276$WITH rutas AS (
  SELECT
    e.order_id,
    array_agg(e.event ORDER BY e.event_at, e.id) AS eventos
  FROM order_events AS e
  GROUP BY e.order_id
)
SELECT
  array_to_string(eventos, ' > ') AS ruta,
  cardinality(eventos) AS pasos,
  count(*) AS pedidos,
  round(100.0 * count(*) / sum(count(*)) OVER (), 2) AS porcentaje
FROM rutas
GROUP BY eventos
ORDER BY pedidos DESC, ruta;$c20276$, true, 'reference', 0);

