insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20358$puntualidad-de-entregas-por-ciudad$c20358$), $c20359$SELECT
  ci.name AS city,
  date_trunc('month', o.placed_at AT TIME ZONE 'UTC')::date AS month,
  count(*) AS delivered_orders,
  count(*) FILTER (WHERE o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute') AS late_orders,
  round(100.0 * count(*) FILTER (WHERE o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute') / count(*), 2) AS late_pct,
  round(avg(extract(epoch FROM (o.delivered_at - o.placed_at)) / 60.0 - o.promised_minutes) FILTER (WHERE o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute'), 1) AS avg_minutes_late
FROM orders o
JOIN restaurants r ON r.id = o.restaurant_id
JOIN cities ci ON ci.id = r.city_id
WHERE o.status = 'delivered'
GROUP BY ci.name, date_trunc('month', o.placed_at AT TIME ZONE 'UTC')::date
ORDER BY city, month;$c20359$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20360$puntualidad-de-entregas-por-ciudad$c20360$), $c20361$WITH entregados AS (
  SELECT
    ci.name AS city,
    date_trunc('month', o.placed_at AT TIME ZONE 'UTC')::date AS month,
    o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute' AS is_late,
    extract(epoch FROM (o.delivered_at - (o.placed_at + o.promised_minutes * interval '1 minute'))) / 60.0 AS minutes_late
  FROM orders o
  JOIN restaurants r ON r.id = o.restaurant_id
  JOIN cities ci ON ci.id = r.city_id
  WHERE o.status = 'delivered'
)
SELECT
  city,
  month,
  count(*) AS delivered_orders,
  count(*) FILTER (WHERE is_late) AS late_orders,
  round(100.0 * count(*) FILTER (WHERE is_late) / count(*), 2) AS late_pct,
  round(avg(minutes_late) FILTER (WHERE is_late), 1) AS avg_minutes_late
FROM entregados
GROUP BY city, month
ORDER BY city, month;$c20361$, false, $c20362$La regla de retraso se calcula una sola vez en una CTE$c20362$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20363$puntualidad-de-entregas-por-ciudad$c20363$), $c20364$SELECT
  ci.name AS city,
  date_trunc('month', o.placed_at AT TIME ZONE 'UTC')::date AS month,
  count(*) AS delivered_orders,
  sum(CASE WHEN o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute' THEN 1 ELSE 0 END) AS late_orders,
  round(100.0 * sum(CASE WHEN o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute' THEN 1 ELSE 0 END) / count(*), 2) AS late_pct,
  round(avg(CASE WHEN o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute'
                 THEN extract(epoch FROM (o.delivered_at - o.placed_at)) / 60.0 - o.promised_minutes END), 1) AS avg_minutes_late
FROM orders o
JOIN restaurants r ON r.id = o.restaurant_id
JOIN cities ci ON ci.id = r.city_id
WHERE o.status = 'delivered'
GROUP BY ci.name, date_trunc('month', o.placed_at AT TIME ZONE 'UTC')::date
ORDER BY city, month;$c20364$, false, $c20365$Agregación condicional con CASE en lugar de FILTER$c20365$, 2);

insert into public.exercise_hints (exercise_id, level, body_md, coin_cost, xp_penalty_percent)
values ((select id from public.exercises where slug = $c20366$puntualidad-de-entregas-por-ciudad$c20366$), 1, $c20367$El informe tiene un solo nivel de detalle: una fila por ciudad y mes. Todo lo demás son conteos sobre el mismo conjunto de pedidos, así que **no necesitas más de una pasada**: el total y el subconjunto tardío salen de la misma agregación, uno sin condición y otro con condición.

La ciudad no está en `orders`: llega por el restaurante.$c20367$, 0, 10)
