insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20402$estado-de-resultados-mensual-tiendaviva$c20402$), $c20403$WITH cobrados AS (
  SELECT
    o.id,
    c.country,
    o.currency,
    date_trunc('month', o.created_at AT TIME ZONE 'UTC')::date AS month,
    p.amount
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
)
SELECT
  b.country,
  b.currency,
  b.month,
  count(*) AS paid_orders,
  sum(b.amount) AS gross_amount,
  coalesce(sum(r.refund_amount), 0) AS refunded_amount,
  sum(b.amount) - coalesce(sum(r.refund_amount), 0) AS net_amount
FROM cobrados b
LEFT JOIN returns r ON r.order_id = b.id
GROUP BY b.country, b.currency, b.month
ORDER BY b.country, b.month;$c20403$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20404$estado-de-resultados-mensual-tiendaviva$c20404$), $c20405$WITH cobrados AS (
  SELECT
    o.id,
    c.country,
    o.currency,
