delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c20493$tablero-de-vendedores-mexico$c20493$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20494$tablero-de-vendedores-mexico$c20494$), $c20495$WITH vendidos AS (
  SELECT
    pr.seller_id,
    oi.quantity,
    oi.quantity * oi.unit_price AS line_amount,
    o.status
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
  JOIN order_items oi ON oi.order_id = o.id
  JOIN products pr ON pr.id = oi.product_id
  WHERE c.country = 'MX'
    AND o.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
    AND o.created_at AT TIME ZONE 'UTC' < '2025-07-01'
),
resumen AS (
  SELECT
    seller_id,
    sum(quantity) AS units_sold,
    sum(line_amount) AS gross_amount,
    coalesce(sum(line_amount) FILTER (WHERE status = 'returned'), 0) AS returned_amount
  FROM vendidos
  GROUP BY seller_id
)
SELECT
  s.store_name,
  r.units_sold,
  r.gross_amount,
  r.returned_amount,
  round(100.0 * r.returned_amount / r.gross_amount, 2) AS returned_pct
FROM resumen r
JOIN sellers s ON s.id = r.seller_id
WHERE r.units_sold >= 40
ORDER BY r.gross_amount DESC, s.store_name;$c20495$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20496$tablero-de-vendedores-mexico$c20496$), $c20497$SELECT
  s.store_name,
  sum(oi.quantity) AS units_sold,
  sum(oi.quantity * oi.unit_price) AS gross_amount,
  coalesce(sum(oi.quantity * oi.unit_price) FILTER (WHERE o.status = 'returned'), 0) AS returned_amount,
  round(100.0 * coalesce(sum(oi.quantity * oi.unit_price) FILTER (WHERE o.status = 'returned'), 0) / sum(oi.quantity * oi.unit_price), 2) AS returned_pct
FROM orders o
JOIN customers c ON c.id = o.customer_id
JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
JOIN order_items oi ON oi.order_id = o.id
JOIN products pr ON pr.id = oi.product_id
JOIN sellers s ON s.id = pr.seller_id
WHERE c.country = 'MX'
  AND o.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
  AND o.created_at AT TIME ZONE 'UTC' < '2025-07-01'
GROUP BY s.id, s.store_name
HAVING sum(oi.quantity) >= 40
ORDER BY gross_amount DESC, store_name;$c20497$, false, $c20498$Una sola agregación con HAVING sobre las unidades$c20498$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20499$tablero-de-vendedores-mexico$c20499$), $c20500$WITH vendidos AS (
  SELECT
    pr.seller_id,
    oi.quantity,
    oi.quantity * oi.unit_price AS line_amount,
    CASE WHEN o.status = 'returned' THEN oi.quantity * oi.unit_price ELSE 0 END AS returned_line
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
  JOIN order_items oi ON oi.order_id = o.id
  JOIN products pr ON pr.id = oi.product_id
  WHERE c.country = 'MX'
    AND o.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
    AND o.created_at AT TIME ZONE 'UTC' < '2025-07-01'
)
SELECT
  s.store_name,
  sum(v.quantity) AS units_sold,
  sum(v.line_amount) AS gross_amount,
  sum(v.returned_line) AS returned_amount,
  round(100.0 * sum(v.returned_line) / sum(v.line_amount), 2) AS returned_pct
FROM vendidos v
JOIN sellers s ON s.id = v.seller_id
GROUP BY s.id, s.store_name
HAVING sum(v.quantity) >= 40
ORDER BY gross_amount DESC, store_name;$c20500$, false, $c20501$Importe devuelto con CASE en lugar de FILTER$c20501$, 2);

