insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20629$informe-final-de-cohortes-ritmo$c20629$), $c20630$WITH cohorte AS (
  SELECT
    u.id,
    u.signup_at,
    date_trunc('month', u.signup_at AT TIME ZONE 'UTC')::date AS cohort_month
  FROM users u
  WHERE u.signup_at AT TIME ZONE 'UTC' < '2025-07-01'
),
escuchas AS (
  SELECT DISTINCT user_id, track_id, played_at FROM plays
),
primeras AS (
  SELECT c.id, count(e.track_id) AS unique_plays
  FROM cohorte c
  LEFT JOIN escuchas e
    ON e.user_id = c.id
   AND e.played_at >= c.signup_at
   AND e.played_at < c.signup_at + interval '30 days'
  GROUP BY c.id
)
SELECT
  c.cohort_month,
  count(*) AS users,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM plays p
    WHERE p.user_id = c.id
      AND p.played_at >= c.signup_at
      AND p.played_at < c.signup_at + interval '7 days'
  )) AS activated_7d,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM plays p
    WHERE p.user_id = c.id
      AND p.played_at >= c.signup_at + interval '30 days'
      AND p.played_at < c.signup_at + interval '60 days'
  )) AS retained_d30,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM subscriptions s
    WHERE s.user_id = c.id
      AND s.started_on >= (c.signup_at AT TIME ZONE 'UTC')::date
      AND s.started_on < (c.signup_at AT TIME ZONE 'UTC')::date + 30
  )) AS converted_30d,
  round(avg(pr.unique_plays), 2) AS avg_unique_plays_30d
FROM cohorte c
JOIN primeras pr ON pr.id = c.id
GROUP BY c.cohort_month
ORDER BY c.cohort_month;$c20630$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20631$informe-final-de-cohortes-ritmo$c20631$), $c20632$WITH cohorte AS (
  SELECT
    u.id,
    u.signup_at,
    date_trunc('month', u.signup_at AT TIME ZONE 'UTC')::date AS cohort_month
  FROM users u
  WHERE u.signup_at AT TIME ZONE 'UTC' < '2025-07-01'
),
escuchas AS (
  SELECT DISTINCT user_id, track_id, played_at FROM plays
),
por_persona AS (
  SELECT
    c.id,
    c.cohort_month,
    count(*) FILTER (WHERE e.played_at < c.signup_at + interval '7 days') AS plays_7d,
    count(e.track_id) AS unique_plays_30d
  FROM cohorte c
  LEFT JOIN escuchas e
    ON e.user_id = c.id
   AND e.played_at >= c.signup_at
   AND e.played_at < c.signup_at + interval '30 days'
  GROUP BY c.id, c.cohort_month
)
SELECT
  p.cohort_month,
  count(*) AS users,
  count(*) FILTER (WHERE p.plays_7d > 0) AS activated_7d,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM plays pl
    WHERE pl.user_id = p.id
      AND pl.played_at >= (SELECT c.signup_at FROM cohorte c WHERE c.id = p.id) + interval '30 days'
      AND pl.played_at < (SELECT c.signup_at FROM cohorte c WHERE c.id = p.id) + interval '60 days'
  )) AS retained_d30,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM subscriptions s, cohorte c
    WHERE c.id = p.id AND s.user_id = p.id
      AND s.started_on >= (c.signup_at AT TIME ZONE 'UTC')::date
      AND s.started_on < (c.signup_at AT TIME ZONE 'UTC')::date + 30
  )) AS converted_30d,
  round(avg(CASE WHEN p.unique_plays_30d > 0 THEN p.unique_plays_30d ELSE 0 END), 2) AS avg_unique_plays_30d
FROM por_persona p
GROUP BY p.cohort_month
ORDER BY p.cohort_month;$c20632$, false, $c20633$Banderas por persona calculadas antes de agregar$c20633$, 1);

