insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20791$optimizacion-reducir-antes-de-unir-categorias$c20791$), $c20792$WITH entregados AS (
  SELECT o.id
  FROM orders AS o
  JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE r.city_id = 5
    AND o.status = 'delivered'
    AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
    AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
)
SELECT
  m.category,
  sum(oi.quantity)::int AS unidades,
  round(sum(oi.quantity * oi.unit_price), 2) AS monto
FROM entregados AS e
JOIN order_items AS oi ON oi.order_id = e.id
JOIN menu_items AS m ON m.id = oi.menu_item_id
GROUP BY m.category
ORDER BY unidades DESC;$c20792$, true, 'reference', 0);

