delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c20834$optimizacion-dos-tablas-hijas-sin-inflar$c20834$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20835$optimizacion-dos-tablas-hijas-sin-inflar$c20835$), $c20836$WITH entregados AS (
  SELECT o.id, o.restaurant_id
  FROM orders AS o
  JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE r.city_id = 7
    AND o.status = 'delivered'
    AND o.placed_at >= TIMESTAMPTZ '2025-07-01 00:00:00+00'
    AND o.placed_at <  TIMESTAMPTZ '2025-10-01 00:00:00+00'
),
pedidos AS (
  SELECT restaurant_id, count(*)::int AS pedidos
  FROM entregados
  GROUP BY restaurant_id
),
unidades AS (
  SELECT e.restaurant_id, sum(oi.quantity)::int AS unidades
  FROM entregados AS e
  JOIN order_items AS oi ON oi.order_id = e.id
  GROUP BY e.restaurant_id
),
calificaciones AS (
  SELECT e.restaurant_id, count(*)::int AS calificaciones
  FROM entregados AS e
  JOIN ratings AS rt ON rt.order_id = e.id
  GROUP BY e.restaurant_id
)
SELECT
  r.id AS restaurant_id,
  r.name,
  p.pedidos,
  coalesce(u.unidades, 0) AS unidades,
  coalesce(c.calificaciones, 0) AS calificaciones
FROM pedidos AS p
JOIN restaurants AS r ON r.id = p.restaurant_id
LEFT JOIN unidades AS u ON u.restaurant_id = p.restaurant_id
LEFT JOIN calificaciones AS c ON c.restaurant_id = p.restaurant_id
ORDER BY p.pedidos DESC, r.id;$c20836$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c20837$optimizacion-dos-tablas-hijas-sin-inflar$c20837$), $c20838$WITH entregados AS (
  SELECT o.id, o.restaurant_id
  FROM orders AS o
  JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE r.city_id = 7
    AND o.status = 'delivered'
    AND o.placed_at >= TIMESTAMPTZ '2025-07-01 00:00:00+00'
    AND o.placed_at <  TIMESTAMPTZ '2025-10-01 00:00:00+00'
),
base AS (
  SELECT restaurant_id, count(*)::int AS pedidos
  FROM entregados
  GROUP BY restaurant_id
)
SELECT
  r.id AS restaurant_id,
  r.name,
  b.pedidos,
  (SELECT coalesce(sum(oi.quantity), 0)::int
     FROM entregados AS e JOIN order_items AS oi ON oi.order_id = e.id
    WHERE e.restaurant_id = b.restaurant_id) AS unidades,
  (SELECT count(*)::int
     FROM entregados AS e JOIN ratings AS rt ON rt.order_id = e.id
    WHERE e.restaurant_id = b.restaurant_id) AS calificaciones
FROM base AS b
JOIN restaurants AS r ON r.id = b.restaurant_id
ORDER BY b.pedidos DESC, r.id;$c20838$, false, $c20839$Con subconsultas escalares correlacionadas$c20839$, 1);

