insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21146$indices-un-lado-chico-para-el-hash$c21146$), $c21147$SELECT r.id AS restaurant_id,
       r.name AS restaurante,
       count(*) AS pedidos,
       round(sum(o.total), 2) AS ventas
FROM orders AS o
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE c.name = 'Ciudad de México'
  AND o.status = 'delivered'
  AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
  AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
GROUP BY r.id, r.name
ORDER BY ventas DESC, restaurant_id ASC;$c21147$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21148$indices-un-lado-chico-para-el-hash$c21148$), $c21149$WITH agosto AS (
  SELECT restaurant_id, total
  FROM orders
  WHERE status = 'delivered'
    AND placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
    AND placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
)
SELECT r.id AS restaurant_id,
       r.name AS restaurante,
       count(*) AS pedidos,
       round(sum(a.total), 2) AS ventas
FROM agosto AS a
INNER JOIN restaurants AS r ON r.id = a.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE c.name = 'Ciudad de México'
GROUP BY r.id, r.name
ORDER BY ventas DESC, restaurant_id;$c21149$, false, $c21150$Recortando los pedidos del mes en una CTE antes de unir$c21150$, 1);

