delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c21184$indices-informe-de-selectividad-para-ingenieria$c21184$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21185$indices-informe-de-selectividad-para-ingenieria$c21185$), $c21186$WITH base AS (
  SELECT
    count(*) AS filas_tabla,
    count(*) FILTER (
      WHERE restaurant_id = 194
        AND placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
        AND placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
    ) AS restaurante_mes,
    count(*) FILTER (WHERE restaurant_id = 194) AS restaurante_historia,
    count(*) FILTER (
      WHERE placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
        AND placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
    ) AS mes_completo,
    count(*) FILTER (WHERE status = 'cancelled') AS cancelados,
    count(*) FILTER (WHERE status = 'delivered') AS entregados
  FROM orders
),
medidos AS (
  SELECT 'restaurante 194 en agosto de 2025' AS filtro, restaurante_mes AS filas_que_pasan, filas_tabla FROM base
  UNION ALL
  SELECT 'restaurante 194, toda la historia', restaurante_historia, filas_tabla FROM base
  UNION ALL
  SELECT 'agosto de 2025, todos los restaurantes', mes_completo, filas_tabla FROM base
  UNION ALL
  SELECT 'status = cancelled', cancelados, filas_tabla FROM base
  UNION ALL
  SELECT 'status = delivered', entregados, filas_tabla FROM base
)
SELECT
  filtro,
  filas_que_pasan,
  filas_tabla,
  round(100.0 * filas_que_pasan / filas_tabla, 4) AS pct_del_total,
  CASE
    WHEN 100.0 * filas_que_pasan / filas_tabla < 1  THEN 'indice muy conveniente'
    WHEN 100.0 * filas_que_pasan / filas_tabla < 10 THEN 'indice probablemente util'
    ELSE 'indice poco util'
  END AS veredicto
FROM medidos
ORDER BY pct_del_total ASC, filtro ASC;$c21186$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21187$indices-informe-de-selectividad-para-ingenieria$c21187$), $c21188$WITH base AS (
  SELECT
    count(*) AS filas_tabla,
    count(*) FILTER (
      WHERE restaurant_id = 194
        AND placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
        AND placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
    ) AS restaurante_mes,
    count(*) FILTER (WHERE restaurant_id = 194) AS restaurante_historia,
    count(*) FILTER (
      WHERE placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
        AND placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
    ) AS mes_completo,
    count(*) FILTER (WHERE status = 'cancelled') AS cancelados,
    count(*) FILTER (WHERE status = 'delivered') AS entregados
  FROM orders
),
medidos AS (
  SELECT 'restaurante 194 en agosto de 2025' AS filtro, restaurante_mes AS filas_que_pasan, filas_tabla FROM base
  UNION ALL SELECT 'restaurante 194, toda la historia', restaurante_historia, filas_tabla FROM base
  UNION ALL SELECT 'agosto de 2025, todos los restaurantes', mes_completo, filas_tabla FROM base
  UNION ALL SELECT 'status = cancelled', cancelados, filas_tabla FROM base
  UNION ALL SELECT 'status = delivered', entregados, filas_tabla FROM base
),
conpct AS (
  SELECT filtro, filas_que_pasan, filas_tabla,
         round(100.0 * filas_que_pasan / filas_tabla, 4) AS pct_del_total
  FROM medidos
)
SELECT filtro, filas_que_pasan, filas_tabla, pct_del_total,
       CASE
         WHEN pct_del_total < 1  THEN 'indice muy conveniente'
         WHEN pct_del_total < 10 THEN 'indice probablemente util'
         ELSE 'indice poco util'
       END AS veredicto
FROM conpct
ORDER BY pct_del_total, filtro;$c21188$, false, $c21189$Con el porcentaje calculado una sola vez en una CTE intermedia$c21189$, 1);

