insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21266$ia-top-de-sql-server$c21266$), $c21267$SELECT r.id AS restaurant_id, r.name AS restaurante, c.name AS ciudad, count(*) AS entregas
