insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21553$ia-auditoria-de-una-respuesta$c21553$), $c21554$WITH lineas AS (
  SELECT order_id, count(*) AS lineas
  FROM order_items
  GROUP BY order_id
)
SELECT
  c.name AS ciudad,
  count(*) AS pedidos,
  round(avg(o.total), 2) AS ticket_promedio,
  round(avg(coalesce(l.lineas, 0)), 2) AS lineas_por_pedido,
  round(
    100.0 * count(*) FILTER (
      WHERE o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute'
    ) / count(*),
    1
  ) AS pct_tarde
FROM orders AS o
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
LEFT JOIN lineas AS l ON l.order_id = o.id
WHERE o.status = 'delivered'
  AND o.placed_at >= timestamptz '2025-07-01 00:00:00+00'
  AND o.placed_at < timestamptz '2025-09-01 00:00:00+00'
GROUP BY c.name
ORDER BY ciudad;$c21554$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c21555$ia-auditoria-de-una-respuesta$c21555$), $c21556$WITH por_pedido AS (
  SELECT
    o.id,
    c.name AS ciudad,
    o.total,
    (SELECT count(*) FROM order_items AS oi WHERE oi.order_id = o.id) AS lineas,
    CASE
      WHEN extract(epoch FROM (o.delivered_at - o.placed_at)) / 60 > o.promised_minutes THEN 1
      ELSE 0
    END AS tarde
  FROM orders AS o
  INNER JOIN restaurants AS r ON r.id = o.restaurant_id
  INNER JOIN cities AS c ON c.id = r.city_id
  WHERE o.status = 'delivered'
    AND o.placed_at >= '2025-07-01'
    AND o.placed_at < '2025-09-01'
)
SELECT
  ciudad,
  count(*) AS pedidos,
  round(avg(total), 2) AS ticket_promedio,
  round(avg(lineas), 2) AS lineas_por_pedido,
  round(100.0 * sum(tarde) / count(*), 1) AS pct_tarde
FROM por_pedido
GROUP BY ciudad
ORDER BY ciudad;$c21556$, false, $c21557$Una fila por pedido en una CTE y después agregar por ciudad$c21557$, 1);

